/// The server sees submissions, not anyone's inference bill, and must never
/// imply otherwise. Scans the whole serialized response -- keys and string
/// values -- for anything naming or containing "spent" or "spend", rather
/// than checking one specific path, so a spend figure added anywhere in the
/// shape trips this test.
#[tokio::test]
async fn credit_summary_never_reports_a_spend_figure() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );

    let cookie_value = mint_redeem_session_cookie_value(&state, "token-a").await;
    let device_principal = static_token_principal_ref("token-a");
    let submission_id =
        insert_account_test_submission(backend.as_ref(), "tenant-a", &device_principal).await;
    insert_account_test_credit_event(
        backend.as_ref(),
        "tenant-a",
        submission_id,
        &device_principal,
        5.0,
    )
    .await;

    let ext = account_ctx_ext(
        &state,
        &cookie_request_headers("tc_account_session", &cookie_value),
    )
    .await;
    let Json(summary) = account_credit_summary_handler(State(state.clone()), ext)
        .await
        .expect("credit summary succeeds");
    let value = serde_json::to_value(&summary).expect("summary serializes");

    fn assert_no_spend_mentions(value: &serde_json::Value, path: &str) {
        match value {
            serde_json::Value::Object(map) => {
                for (key, child) in map {
                    let lower = key.to_ascii_lowercase();
                    assert!(
                        !lower.contains("spent") && !lower.contains("spend"),
                        "response key names spend at {path}.{key}"
                    );
                    assert_no_spend_mentions(child, &format!("{path}.{key}"));
                }
            }
            serde_json::Value::Array(items) => {
                for (i, item) in items.iter().enumerate() {
                    assert_no_spend_mentions(item, &format!("{path}[{i}]"));
                }
            }
            serde_json::Value::String(s) => {
                let lower = s.to_ascii_lowercase();
                assert!(
                    !lower.contains("spent") && !lower.contains("spend"),
                    "response value names spend at {path}: {s}"
                );
            }
            _ => {}
        }
    }
    assert_no_spend_mentions(&value, "$");

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

#[tokio::test]
async fn account_traces_list_returns_only_owned_submissions() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;
    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );

    // Link token-a's device principal to a durable account under tenant-a.
    let _ = mint_login_link_handler(State(state.clone()), auth_headers("token-a"))
        .await
        .expect("mint links the principal to an account");
    let device_principal = static_token_principal_ref("token-a");

    // One owned submission (device principal) and one foreign principal under the
    // same tenant that the account does NOT own.
    let owned =
        insert_account_test_submission(backend.as_ref(), "tenant-a", &device_principal).await;
    let _foreign =
        insert_account_test_submission(backend.as_ref(), "tenant-a", "principal_someone_else")
            .await;
    // And a submission under a different tenant entirely.
    let _other_tenant =
        insert_account_test_submission(backend.as_ref(), "tenant-b", &device_principal).await;

    let ext = account_ctx_ext(&state, &account_session_headers(&state, "token-a").await).await;
    let Json(page) = account_traces_list_handler(
        State(state.clone()),
        ext,
        Query(AccountTracesListQuery::default()),
    )
    .await
    .expect("list succeeds");

    let ids: Vec<Uuid> = page.items.iter().map(|item| item.submission_id).collect();
    assert_eq!(
        ids,
        vec![owned],
        "only the device-owned submission is visible"
    );
    assert!(
        page.next_cursor.is_none(),
        "single page has no continuation"
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;
}

#[tokio::test]
async fn account_traces_list_cursor_pages_are_disjoint_and_ordered() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );

    let _ = mint_login_link_handler(State(state.clone()), auth_headers("token-a"))
        .await
        .expect("mint");
    let device_principal = static_token_principal_ref("token-a");

    let mut inserted = Vec::new();
    for _ in 0..3 {
        inserted.push(
            insert_account_test_submission(backend.as_ref(), "tenant-a", &device_principal).await,
        );
    }

    // Page 1: limit 2.
    let ext1 = account_ctx_ext(&state, &account_session_headers(&state, "token-a").await).await;
    let Json(page1) = account_traces_list_handler(
        State(state.clone()),
        ext1,
        Query(AccountTracesListQuery {
            limit: Some(2),
            cursor: None,
        }),
    )
    .await
    .expect("page 1");
    assert_eq!(page1.items.len(), 2, "first page is full");
    let cursor = page1
        .next_cursor
        .clone()
        .expect("full page yields a cursor");

    // Page 2: continue from the cursor.
    let ext2 = account_ctx_ext(&state, &account_session_headers(&state, "token-a").await).await;
    let Json(page2) = account_traces_list_handler(
        State(state.clone()),
        ext2,
        Query(AccountTracesListQuery {
            limit: Some(2),
            cursor: Some(cursor),
        }),
    )
    .await
    .expect("page 2");
    assert_eq!(page2.items.len(), 1, "remaining page has the last row");

    let page1_ids: Vec<Uuid> = page1.items.iter().map(|item| item.submission_id).collect();
    let page2_ids: Vec<Uuid> = page2.items.iter().map(|item| item.submission_id).collect();
    // Disjoint.
    for id in &page2_ids {
        assert!(!page1_ids.contains(id), "pages must not overlap");
    }
    // Union covers every inserted row exactly once.
    let mut seen: Vec<Uuid> = page1_ids.iter().chain(page2_ids.iter()).copied().collect();
    seen.sort();
    let mut expected = inserted.clone();
    expected.sort();
    assert_eq!(seen, expected, "the two pages partition all owned rows");

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

