    // The unowned row is untouched: no tombstone was written for it.
    let columns = read_withdrawal_tombstone_columns(backend.as_ref(), "tenant-a", unowned).await;
    assert!(
        columns.is_empty(),
        "a rejected withdrawal must not write a tombstone"
    );

