fn audit_log_path(root: &Path, tenant_id: &str) -> PathBuf {
    root.join("tenants")
        .join(tenant_storage_key(tenant_id))
        .join("audit")
        .join("events.jsonl")
}

fn corrupt_submission_record_tenant(
    root: &Path,
    stored_tenant_id: &str,
    forged_tenant_id: &str,
    submission_id: Uuid,
) {
    let path = submission_metadata_path(root, stored_tenant_id, submission_id);
    let body = std::fs::read_to_string(&path).expect("metadata reads for corruption");
    let mut value: serde_json::Value = serde_json::from_str(&body).expect("metadata json parses");
    value["tenant_id"] = serde_json::json!(forged_tenant_id);
    value["tenant_storage_ref"] = serde_json::json!(tenant_storage_ref(forged_tenant_id));
    value["submitted_tenant_scope_ref"] = serde_json::json!(tenant_storage_ref(forged_tenant_id));
    std::fs::write(
        &path,
        serde_json::to_string_pretty(&value).expect("metadata serializes"),
    )
    .expect("metadata corruption writes");
}

fn read_raw_audit_events(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsAuditEvent>> {
    let path = audit_log_path(root, tenant_id);
    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read raw audit events {}", path.display()))?;
    body.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(|line| serde_json::from_str(line).context("failed to parse raw audit event"))
        .collect()
}

#[tokio::test]
async fn trace_content_read_per_source_emits_one_row_per_object_ref() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let auth = test_reviewer_auth("tenant-a");
    let submission_id = Uuid::new_v4();
    let object_refs = [Uuid::new_v4(), Uuid::new_v4(), Uuid::new_v4()];

    append_trace_content_read_audit_per_source(
        state.as_ref(),
        &auth,
        submission_id,
        &object_refs,
        "replay_export",
        Some("per-source coverage"),
    )
    .await
    .expect("per-source variant writes rows");

    let events = read_raw_audit_events(temp.path(), "tenant-a").expect("audit events parse");
    assert_eq!(events.len(), object_refs.len());
    for event in &events {
        assert_eq!(event.submission_id, submission_id);
        assert_eq!(event.kind, "trace_content_read");
        assert!(event.event_hash.is_some());
        assert!(event.previous_event_hash.is_some());
    }
    // Each row must have a distinct event_hash and link to the prior row's hash.
    let mut prev = "sha256:genesis".to_string();
    for event in &events {
        assert_eq!(event.previous_event_hash.as_deref(), Some(prev.as_str()));
        prev = event.event_hash.clone().unwrap();
    }
}

#[tokio::test]
async fn trace_content_read_per_source_empty_slice_emits_one_null_row() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let auth = test_reviewer_auth("tenant-a");
    let submission_id = Uuid::new_v4();

    append_trace_content_read_audit_per_source(
        state.as_ref(),
        &auth,
        submission_id,
        &[],
        "review_decision",
        None,
    )
    .await
    .expect("empty slice falls back to a single row");

    let events = read_raw_audit_events(temp.path(), "tenant-a").expect("audit events parse");
    assert_eq!(events.len(), 1);
    assert_eq!(events[0].submission_id, submission_id);
}

#[test]
fn token_role_parses_worker_roles() {
    let cases = [
        ("contributor", TokenRole::Contributor, "contributor"),
        ("reviewer", TokenRole::Reviewer, "reviewer"),
        ("admin", TokenRole::Admin, "admin"),
        ("export_worker", TokenRole::ExportWorker, "export_worker"),
        ("export-worker", TokenRole::ExportWorker, "export_worker"),
        (
            "retention_worker",
            TokenRole::RetentionWorker,
            "retention_worker",
        ),
        (
            "retention-worker",
            TokenRole::RetentionWorker,
            "retention_worker",
        ),
        ("vector_worker", TokenRole::VectorWorker, "vector_worker"),
        (
            "benchmark_worker",
            TokenRole::BenchmarkWorker,
            "benchmark_worker",
        ),
        ("utility_worker", TokenRole::UtilityWorker, "utility_worker"),
        ("utility-worker", TokenRole::UtilityWorker, "utility_worker"),
        (
            "process_eval_worker",
            TokenRole::ProcessEvalWorker,
            "process_eval_worker",
        ),
        (
            "process-evaluation-worker",
            TokenRole::ProcessEvalWorker,
            "process_eval_worker",
        ),
        (
            "revocation_worker",
            TokenRole::RevocationWorker,
            "revocation_worker",
        ),
        (
            "revocation-worker",
            TokenRole::RevocationWorker,
            "revocation_worker",
        ),
        (
            "competition_read_worker",
            TokenRole::CompetitionReadWorker,
            "competition_read_worker",
        ),
        (
            "competition-read-worker",
            TokenRole::CompetitionReadWorker,
            "competition_read_worker",
        ),
    ];

    for (raw, expected, storage_name) in cases {
        let parsed = TokenRole::parse(raw).expect("role parses");
        assert_eq!(parsed, expected);
        assert_eq!(parsed.storage_name(), storage_name);
    }
    assert!(TokenRole::parse("trainer").is_err());
}

#[test]
fn require_competition_operator_admits_admin_and_competition_worker_denies_others() {
    let build_auth = |role: TokenRole| TenantAuth {
        tenant_id: "tenant-a".to_string(),
        role,
        principal_ref: static_token_principal_ref("competition-read-worker-token-a"),
        legacy_principal_ref: None,
        expires_at: None,
        auth_method: TraceAuthMethod::StaticToken,
        signed_claim_issuer: None,
        signed_claim_audiences: BTreeSet::new(),
        signed_claim_subject: None,
        allowed_consent_scopes: BTreeSet::new(),
        allowed_uses: BTreeSet::new(),
    };

    let reviewer_err = require_competition_operator(&build_auth(TokenRole::Reviewer))
        .expect_err("reviewer token must be rejected");
    assert_eq!(reviewer_err.0, StatusCode::FORBIDDEN);

    require_competition_operator(&build_auth(TokenRole::CompetitionReadWorker))
        .expect("competition read worker token is admitted");

    require_competition_operator(&build_auth(TokenRole::Admin)).expect("admin token is admitted");
}

#[test]
fn trace_summary_similarity_exact_hash_wins_and_fuzzy_neighbors_are_ranked() {
    let target_submission =
        Uuid::parse_str("00000000-0000-0000-0000-000000000001").expect("uuid parses");
    let exact_trace = Uuid::parse_str("00000000-0000-0000-0000-000000000011").expect("uuid parses");
    let fuzzy_trace = Uuid::parse_str("00000000-0000-0000-0000-000000000012").expect("uuid parses");
    let unrelated_trace =
        Uuid::parse_str("00000000-0000-0000-0000-000000000013").expect("uuid parses");

    let neighbors = nearest_trace_neighbors(
        target_submission,
        "Task type: calendar scheduling timezone retry",
        "sha256:target",
        [
            TraceSimilarityCandidate {
                submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000021")
                    .expect("uuid parses"),
                trace_id: fuzzy_trace,
                canonical_summary: Some("Task type: calendar scheduling timezone ambiguity retry"),
                canonical_summary_hash: Some("sha256:fuzzy"),
            },
            TraceSimilarityCandidate {
                submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000022")
                    .expect("uuid parses"),
                trace_id: exact_trace,
                canonical_summary: Some("different text but same hash"),
                canonical_summary_hash: Some("sha256:target"),
            },
            TraceSimilarityCandidate {
                submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000023")
                    .expect("uuid parses"),
                trace_id: unrelated_trace,
                canonical_summary: Some("database migration checksum repair"),
                canonical_summary_hash: Some("sha256:unrelated"),
            },
        ],
    );

    assert_eq!(neighbors.len(), 2);
    assert_eq!(neighbors[0].trace_id, exact_trace.to_string());
    assert_eq!(neighbors[0].score, 1.0);
    assert_eq!(neighbors[1].trace_id, fuzzy_trace.to_string());
    assert!(neighbors[1].score > TRACE_SIMILARITY_NEIGHBOR_THRESHOLD);
    assert!(neighbors[1].score < 1.0);
}

#[test]
fn trace_summary_similarity_excludes_same_submission_and_sorts_ties() {
    let target_submission =
        Uuid::parse_str("00000000-0000-0000-0000-000000000001").expect("uuid parses");
    let first_trace = Uuid::parse_str("00000000-0000-0000-0000-000000000011").expect("uuid parses");
    let second_trace =
        Uuid::parse_str("00000000-0000-0000-0000-000000000012").expect("uuid parses");

    let neighbors = nearest_trace_neighbors(
        target_submission,
        "tool call retry calendar auth failure",
        "sha256:target",
        [
            TraceSimilarityCandidate {
                submission_id: target_submission,
                trace_id: Uuid::parse_str("00000000-0000-0000-0000-000000000010")
                    .expect("uuid parses"),
                canonical_summary: Some("tool call retry calendar auth failure"),
                canonical_summary_hash: Some("sha256:target"),
            },
            TraceSimilarityCandidate {
                submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000021")
                    .expect("uuid parses"),
                trace_id: second_trace,
                canonical_summary: Some("tool call retry calendar auth"),
                canonical_summary_hash: Some("sha256:two"),
            },
            TraceSimilarityCandidate {
                submission_id: Uuid::parse_str("00000000-0000-0000-0000-000000000022")
                    .expect("uuid parses"),
                trace_id: first_trace,
                canonical_summary: Some("tool call retry calendar auth"),
                canonical_summary_hash: Some("sha256:one"),
            },
        ],
    );

    assert_eq!(
        neighbors
            .iter()
            .map(|neighbor| neighbor.trace_id.as_str())
            .collect::<Vec<_>>(),
        vec![first_trace.to_string(), second_trace.to_string()]
    );
}

