#[tokio::test]
async fn submit_rate_limit_separates_delimiter_colliding_signed_principals() {
    let _lock = submit_rate_limit_test_lock().lock().await;
    reset_account_rate_limiter_for_test();
    let temp = tempfile::tempdir().expect("temp dir");
    let secret = "submit-rate-limit-collision-secret";
    let state =
        test_state_with_signed_token_verifier(temp.path().to_path_buf(), secret, None, None);
    let expires_at = (Utc::now() + Duration::minutes(5)).timestamp();
    let token_a = signed_tenant_token(
        secret,
        serde_json::json!({
            "tenant_id": "a",
            "role": "contributor",
            "principal_ref": "b:c",
            "exp": expires_at
        }),
    );
    let token_b = signed_tenant_token(
        secret,
        serde_json::json!({
            "tenant_id": "a:b",
            "role": "contributor",
            "principal_ref": "c",
            "exp": expires_at
        }),
    );
    let principal_a = authenticate_ctx(state.as_ref(), &auth_headers(&token_a))
        .expect("principal A authenticates");
    let principal_b = authenticate_ctx(state.as_ref(), &auth_headers(&token_b))
        .expect("principal B authenticates");
    assert_eq!(
        principal_a.principal_ref(),
        principal_b.principal_ref(),
        "the pre-existing signed-principal derivation collides for the review tuples"
    );
    let key_a = submit_principal_rate_limit_key(
        principal_a.tenant_id(),
        principal_a.safe_auth_method(),
        principal_a.principal_ref(),
    );
    let key_b = submit_principal_rate_limit_key(
        principal_b.tenant_id(),
        principal_b.safe_auth_method(),
        principal_b.principal_ref(),
    );
    assert_ne!(
        key_a, key_b,
        "tenant boundaries must produce distinct buckets"
    );
    let mut invalid = sample_envelope().await;
    invalidate_envelope_schema(&mut invalid);

    for _ in 0..SUBMIT_PER_PRINCIPAL_LIMIT {
        let (status, _) = submit_trace_handler(
            State(state.clone()),
            auth_headers(&token_a),
            submit_body(invalid.clone()),
        )
        .await
        .expect_err("principal A reaches validation while under its rate limit");
        assert_eq!(status, StatusCode::BAD_REQUEST);
    }
    let (status, _) = submit_trace_handler(
        State(state.clone()),
        auth_headers(&token_a),
        submit_body(invalid.clone()),
    )
    .await
    .expect_err("principal A exhausts its own bucket");
    assert_eq!(status, StatusCode::TOO_MANY_REQUESTS);

    let (status, _) =
        submit_trace_handler(State(state), auth_headers(&token_b), submit_body(invalid))
            .await
            .expect_err("principal B retains an independent bucket");
    assert_eq!(status, StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn submit_rate_limit_separates_colliding_static_and_signed_principals() {
    let _lock = submit_rate_limit_test_lock().lock().await;
    reset_account_rate_limiter_for_test();
    let temp = tempfile::tempdir().expect("temp dir");
    let secret = "submit-rate-limit-mixed-auth-secret";
    let static_token = "signed:a:b:c";
    let mut state =
        test_state_with_signed_token_verifier(temp.path().to_path_buf(), secret, None, None);
    let mut tokens = BTreeMap::new();
    insert_token(&mut tokens, "a", static_token, TokenRole::Contributor);
    Arc::make_mut(&mut state).tokens = Arc::new(tokens);
    let signed_token = signed_tenant_token(
        secret,
        serde_json::json!({
            "tenant_id": "a",
            "role": "contributor",
            "principal_ref": "b:c",
            "exp": (Utc::now() + Duration::minutes(5)).timestamp()
        }),
    );
    let static_principal = authenticate_ctx(state.as_ref(), &auth_headers(static_token))
        .expect("static principal authenticates");
    let signed_principal = authenticate_ctx(state.as_ref(), &auth_headers(&signed_token))
        .expect("signed principal authenticates");
    assert_eq!(static_principal.tenant_id(), signed_principal.tenant_id());
    assert_ne!(
        static_principal.principal_ref(),
        signed_principal.principal_ref(),
        "method-bound principal derivation keeps authentication methods in separate namespaces"
    );
    assert_eq!(
        static_principal.auth().legacy_principal_ref,
        signed_principal.auth().legacy_principal_ref,
        "pre-#209 legacy hashes still collide for the adversarial token shape"
    );
    let static_key = submit_principal_rate_limit_key(
        static_principal.tenant_id(),
        static_principal.safe_auth_method(),
        static_principal.principal_ref(),
    );
    let signed_key = submit_principal_rate_limit_key(
        signed_principal.tenant_id(),
        signed_principal.safe_auth_method(),
        signed_principal.principal_ref(),
    );
    assert_ne!(
        static_key, signed_key,
        "authentication methods must produce distinct buckets"
    );
    let mut invalid = sample_envelope().await;
    invalidate_envelope_schema(&mut invalid);

    for _ in 0..SUBMIT_PER_PRINCIPAL_LIMIT {
        let (status, _) = submit_trace_handler(
            State(state.clone()),
            auth_headers(&signed_token),
            submit_body(invalid.clone()),
        )
        .await
        .expect_err("signed principal reaches validation while under its rate limit");
        assert_eq!(status, StatusCode::BAD_REQUEST);
    }
    let (status, _) = submit_trace_handler(
        State(state.clone()),
        auth_headers(&signed_token),
        submit_body(invalid.clone()),
    )
    .await
    .expect_err("signed principal exhausts its own bucket");
    assert_eq!(status, StatusCode::TOO_MANY_REQUESTS);

    let (status, _) = submit_trace_handler(
        State(state),
        auth_headers(static_token),
        submit_body(invalid),
    )
    .await
    .expect_err("static principal retains an independent bucket");
    assert_eq!(status, StatusCode::BAD_REQUEST);
}

#[test]
fn method_bound_principal_refs_separate_static_and_signed_namespaces() {
    let colliding = "signed:a:b:c";
    let (static_ref, static_legacy) = static_token_principal_refs(colliding);
    let (signed_ref, signed_legacy) = signed_claim_principal_refs("a", "b:c");
    assert_ne!(static_ref, signed_ref);
    assert_eq!(static_legacy, signed_legacy);
    assert_ne!(static_ref, static_legacy);
    assert_ne!(signed_ref, signed_legacy);
}

#[test]
fn ownership_predicates_do_not_cross_colliding_auth_methods() {
    let colliding = "signed:a:b:c";
    let mut tokens = BTreeMap::new();
    insert_token(&mut tokens, "a", colliding, TokenRole::Contributor);
    let static_auth = tokens.get(colliding).expect("static auth").clone();
    let (signed_ref, signed_legacy) = signed_claim_principal_refs("a", "b:c");
    let signed_auth = TenantAuth {
        tenant_id: "a".to_string(),
        role: TokenRole::Contributor,
        principal_ref: signed_ref.clone(),
        legacy_principal_ref: Some(signed_legacy),
        expires_at: None,
        auth_method: TraceAuthMethod::SignedClaim,
        signed_claim_issuer: None,
        signed_claim_audiences: BTreeSet::new(),
        signed_claim_subject: None,
        allowed_consent_scopes: BTreeSet::new(),
        allowed_uses: BTreeSet::new(),
    };

    let signed_record = submission_record_with_principal(&signed_ref);
    assert!(principal_owns_submission(&signed_auth, &signed_record));
    assert!(!principal_owns_submission(&static_auth, &signed_record));
    assert!(principal_can_self_revoke_submission(
        &signed_auth,
        &signed_record
    ));
    assert!(!principal_can_self_revoke_submission(
        &static_auth,
        &signed_record
    ));

    let static_record = submission_record_with_principal(&static_auth.principal_ref);
    assert!(principal_owns_submission(&static_auth, &static_record));
    assert!(!principal_owns_submission(&signed_auth, &static_record));

    // Dual-read keeps same-credential continuity for pre-#209 rows.
    let legacy = static_auth.legacy_principal_ref.clone().expect("legacy");
    let legacy_record = submission_record_with_principal(&legacy);
    assert!(principal_owns_submission(&static_auth, &legacy_record));
    // Residual for historical colliding hashes only: both methods still match the
    // shared pre-#209 row. New submissions never write that hash.
    assert!(principal_owns_submission(&signed_auth, &legacy_record));
}

