#[tokio::test]
async fn audit_events_handler_uses_bounded_file_audit_reads() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let path = audit_log_path(temp.path(), "tenant-a");
    std::fs::create_dir_all(path.parent().expect("audit log has parent"))
        .expect("audit dir writes");
    let older_corrupt_event = TraceCommonsAuditEvent {
        event_id: Uuid::new_v4(),
        tenant_id: "tenant-b".to_string(),
        submission_id: Uuid::new_v4(),
        kind: "read".to_string(),
        created_at: Utc::now() - Duration::minutes(1),
        status: None,
        actor_role: Some(TokenRole::Reviewer),
        actor_principal_ref: Some(static_token_principal_ref("review-token-b")),
        reason: Some("older non-returned corrupt audit row".to_string()),
        export_count: None,
        export_id: None,
        decision_inputs_hash: None,
        previous_event_hash: None,
        event_hash: None,
    };
    let latest_event = TraceCommonsAuditEvent {
        event_id: Uuid::new_v4(),
        tenant_id: "tenant-a".to_string(),
        submission_id: Uuid::new_v4(),
        kind: "read".to_string(),
        created_at: Utc::now(),
        status: None,
        actor_role: Some(TokenRole::Reviewer),
        actor_principal_ref: Some(static_token_principal_ref("review-token-a")),
        reason: Some("latest bounded audit row".to_string()),
        export_count: None,
        export_id: None,
        decision_inputs_hash: None,
        previous_event_hash: None,
        event_hash: None,
    };
    let body = format!(
        "{}\n{}\n",
        serde_json::to_string(&older_corrupt_event).expect("older event serializes"),
        serde_json::to_string(&latest_event).expect("latest event serializes")
    );
    std::fs::write(&path, body).expect("audit log writes");

    let Json(events) = audit_events_handler(
        State(state),
        auth_headers("review-token-a"),
        Query(AuditEventsQuery { limit: Some(1) }),
    )
    .await
    .expect("bounded file audit read ignores older non-returned tenant drift");

    assert_eq!(events.len(), 1);
    assert_eq!(events[0].event_id, latest_event.event_id);
}

#[tokio::test]
async fn submit_rejects_mismatched_file_revocation_tenant_before_side_effects() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let envelope = sample_envelope().await;
    let submission_id = envelope.submission_id;
    let revocation_path = temp
        .path()
        .join("tenants")
        .join(tenant_storage_key("tenant-a"))
        .join("revocations")
        .join(format!("{}.json", Uuid::new_v4()));
    std::fs::create_dir_all(
        revocation_path
            .parent()
            .expect("revocation path has parent directory"),
    )
    .expect("revocation dir writes");
    std::fs::write(
        &revocation_path,
        serde_json::to_string_pretty(&TraceCommonsRevocation {
            tenant_id: "tenant-b".to_string(),
            tenant_storage_ref: tenant_storage_ref("tenant-b"),
            submission_id: Uuid::new_v4(),
            revoked_at: Utc::now(),
            reason: "mismatched file tenant should fail closed".to_string(),
            redaction_hash: None,
            canonical_summary_hash: None,
        })
        .expect("revocation serializes"),
    )
    .expect("corrupt revocation writes");

    let error = submit_trace_handler(State(state), auth_headers("token-a"), submit_body(envelope))
        .await
        .expect_err("mismatched revocation tenant fails closed");
    assert_eq!(error.0, StatusCode::INTERNAL_SERVER_ERROR);
    assert!(
        read_submission_record(temp.path(), "tenant-a", submission_id)
            .expect("tenant-a record lookup succeeds")
            .is_none()
    );
}

