#[tokio::test]
async fn ingestion_writes_derived_analytics_and_duplicate_precheck() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let first = sample_envelope().await;
    let second = sample_envelope().await;
    let second_id = second.submission_id;
    let mut third = sample_envelope().await;
    for event in &mut third.events {
        if event.event_type
            == trace_commons_protocol::trace_contribution::TraceContributionEventType::UserMessage
        {
            event.redacted_content = Some("Please inspect the workspace carefully".to_string());
            break;
        }
    }

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(first),
    )
    .await
    .expect("first submission succeeds");
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(second),
    )
    .await
    .expect("second submission succeeds");
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(third),
    )
    .await
    .expect("third similar submission succeeds");

    let derived = read_all_derived_records(temp.path(), "tenant-a").expect("derived reads");
    assert_eq!(derived.len(), 3);
    assert_eq!(
        derived[0].canonical_summary_hash,
        derived[1].canonical_summary_hash
    );
    assert_eq!(derived[0].duplicate_score, 0.0);
    assert_eq!(derived[1].duplicate_score, 1.0);
    assert_ne!(
        derived[0].canonical_summary_hash,
        derived[2].canonical_summary_hash
    );
    assert!(derived[2].duplicate_score > TRACE_SIMILARITY_NEIGHBOR_THRESHOLD);
    assert!(derived[2].duplicate_score < 1.0);
    assert!(derived[2].novelty_score < 0.65);
    assert!(
        derived[1]
            .coverage_tags
            .iter()
            .any(|tag| tag == "privacy:medium")
    );

    let record = read_submission_record(temp.path(), "tenant-a", second_id)
        .expect("record reads")
        .expect("record exists");
    let stored = std::fs::read_to_string(temp.path().join(record.object_key))
        .expect("stored envelope reads");
    assert!(stored.contains("\"duplicate_score\": 1.0"));

    let contributor_analytics_error = analytics_handler(
        State(state.clone()),
        Query(TraceAnalyticsQuery::default()),
        auth_headers("token-a"),
    )
    .await
    .expect_err("contributor cannot access tenant-wide analytics");
    assert_eq!(contributor_analytics_error.0, StatusCode::FORBIDDEN);

    let Json(analytics) = analytics_handler(
        State(state.clone()),
        Query(TraceAnalyticsQuery::default()),
        auth_headers("review-token-a"),
    )
    .await
    .expect("analytics succeeds");
    assert_eq!(analytics.submissions_total, 3);
    assert_eq!(analytics.duplicate_groups, 1);
    assert_eq!(analytics.by_privacy_risk.get("medium"), Some(&3));
    let mut suppressed_state = test_state(temp.path().to_path_buf());
    Arc::make_mut(&mut suppressed_state).analytics_min_cell_count = 4;
    let Json(suppressed_analytics) = analytics_handler(
        State(suppressed_state),
        Query(TraceAnalyticsQuery::default()),
        auth_headers("review-token-a"),
    )
    .await
    .expect("analytics suppression succeeds");
    assert_eq!(suppressed_analytics.submissions_total, 3);
    assert_eq!(suppressed_analytics.min_cell_count, Some(4));
    assert!(suppressed_analytics.suppressed_cell_count > 0);
    assert_eq!(
        suppressed_analytics.privacy_budget.strategy,
        "k_anonymity_min_cell"
    );
    assert_eq!(suppressed_analytics.privacy_budget.min_cell_count, Some(4));
    assert_eq!(
        suppressed_analytics.privacy_budget.suppressed_cell_count,
        suppressed_analytics.suppressed_cell_count
    );
    assert_eq!(suppressed_analytics.privacy_budget.released_cell_count, 0);
    assert!(suppressed_analytics.privacy_budget.suppression_applied);
    assert!(!suppressed_analytics.privacy_budget.broad_release_ready);
    assert!(
        suppressed_analytics
            .privacy_budget
            .broad_release_blocking_reasons
            .iter()
            .any(|reason| reason == "small_cells_suppressed")
    );
    assert!(suppressed_analytics.by_privacy_risk.is_empty());
    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit reads");
    assert!(audit_events.iter().any(|event| {
        event.kind == "read"
            && event
                .reason
                .as_deref()
                .is_some_and(|reason| reason.contains("surface=analytics_summary"))
            && event.export_count == Some(3)
    }));
}

