#[tokio::test]
async fn trace_review_escalation_marks_high_risk_and_overdue_items() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let envelope = sample_envelope().await;
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(State(state), auth_headers("token-a"), submit_body(envelope))
        .await
        .expect("submission succeeds");

    let now = Utc::now();
    let mut record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("record reads")
        .expect("record exists");
    record.privacy_risk = ResidualPiiRisk::High;
    record.received_at = now - Duration::hours(TRACE_REVIEW_HIGH_RISK_URGENT_AFTER_HOURS + 1);
    let urgent = trace_review_escalation(&record, now);
    assert_eq!(urgent.state, TraceReviewEscalationState::Urgent);
    assert!(urgent.age_hours >= TRACE_REVIEW_HIGH_RISK_URGENT_AFTER_HOURS);
    assert!(
        urgent
            .reasons
            .iter()
            .any(|reason| reason == "high_risk_sla_4h")
    );

    record.privacy_risk = ResidualPiiRisk::Medium;
    record.received_at = now - Duration::hours(TRACE_REVIEW_OVERDUE_AFTER_HOURS + 1);
    let overdue = trace_review_escalation(&record, now);
    assert_eq!(overdue.state, TraceReviewEscalationState::Overdue);
    assert!(
        overdue
            .reasons
            .iter()
            .any(|reason| reason == "review_overdue_72h")
    );

    record.privacy_risk = ResidualPiiRisk::Low;
    record.received_at = now;
    let fresh = trace_review_escalation(&record, now);
    assert_eq!(fresh.state, TraceReviewEscalationState::Fresh);
    assert_eq!(fresh.age_hours, 0);
    assert!(fresh.reasons.is_empty());
}

#[tokio::test]
async fn quarantine_queue_prioritizes_escalated_review_items() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let urgent_envelope = sample_envelope().await;
    let urgent_id = urgent_envelope.submission_id;
    let fresh_envelope = sample_envelope().await;
    let fresh_id = fresh_envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(fresh_envelope),
    )
    .await
    .expect("fresh submission succeeds");
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(urgent_envelope),
    )
    .await
    .expect("urgent submission succeeds");

    let now = Utc::now();
    let mut urgent_record = read_submission_record(temp.path(), "tenant-a", urgent_id)
        .expect("urgent record reads")
        .expect("urgent record exists");
    urgent_record.privacy_risk = ResidualPiiRisk::High;
    urgent_record.received_at =
        now - Duration::hours(TRACE_REVIEW_HIGH_RISK_URGENT_AFTER_HOURS + 1);
    write_submission_record(temp.path(), &urgent_record).expect("urgent record writes");

    let mut fresh_record = read_submission_record(temp.path(), "tenant-a", fresh_id)
        .expect("fresh record reads")
        .expect("fresh record exists");
    fresh_record.privacy_risk = ResidualPiiRisk::Medium;
    fresh_record.received_at = now - Duration::hours(1);
    write_submission_record(temp.path(), &fresh_record).expect("fresh record writes");

    let Json(queue) = review_quarantine_handler(
        State(state),
        auth_headers("review-token-a"),
        Query(ReviewQueueQuery::default()),
    )
    .await
    .expect("quarantine queue loads");
    assert_eq!(queue.len(), 2);
    assert_eq!(queue[0].submission_id, urgent_id);
    assert_eq!(
        queue[0].review_escalation_state,
        TraceReviewEscalationState::Urgent
    );
    assert!(queue[0].review_age_hours >= TRACE_REVIEW_HIGH_RISK_URGENT_AFTER_HOURS);
    assert!(
        queue[0]
            .review_escalation_reasons
            .iter()
            .any(|reason| reason == "high_risk_sla_4h")
    );
    assert_eq!(
        queue[1].review_escalation_state,
        TraceReviewEscalationState::Fresh
    );
}

#[tokio::test]
async fn process_evaluation_worker_attaches_labels_to_accepted_trace() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("accepted submission succeeds");

    let empty_version_error = process_evaluation_worker_handler(
        State(state.clone()),
        auth_headers("process-eval-worker-token-a"),
        Json(TraceProcessEvaluationJobRequest {
            submission_id,
            process_evaluation: ProcessEvaluationLabels {
                evaluator_version: " ".to_string(),
                ..ProcessEvaluationLabels::default()
            },
            reason: "missing evaluator version".to_string(),
            utility_credit_points_delta: None,
            utility_external_ref: None,
            ranking_label: None,
        }),
    )
    .await
    .expect_err("process evaluation worker requires evaluator version");
    assert_eq!(empty_version_error.0, StatusCode::BAD_REQUEST);

    let missing_external_ref_error = process_evaluation_worker_handler(
        State(state.clone()),
        auth_headers("process-eval-worker-token-a"),
        Json(TraceProcessEvaluationJobRequest {
            submission_id,
            process_evaluation: ProcessEvaluationLabels {
                evaluator_version: "judge-v1".to_string(),
                ..ProcessEvaluationLabels::default()
            },
            reason: "utility credit missing ref".to_string(),
            utility_credit_points_delta: Some(0.4),
            utility_external_ref: Some(" ".to_string()),
            ranking_label: None,
        }),
    )
    .await
    .expect_err("process evaluation utility credit requires external ref");
    assert_eq!(missing_external_ref_error.0, StatusCode::BAD_REQUEST);

    let reviewer_error = process_evaluation_worker_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Json(TraceProcessEvaluationJobRequest {
            submission_id: Uuid::new_v4(),
            process_evaluation: ProcessEvaluationLabels {
                evaluator_version: "judge-v1".to_string(),
                ..ProcessEvaluationLabels::default()
            },
            reason: "reviewer must not run process evaluation worker".to_string(),
            utility_credit_points_delta: None,
            utility_external_ref: None,
            ranking_label: None,
        }),
    )
    .await
    .expect_err("reviewer token must not reach process evaluation source checks");
    assert_eq!(reviewer_error.0, StatusCode::FORBIDDEN);

    let process_eval_reason = "offline trajectory evaluator";
    let Json(response) = process_evaluation_worker_handler(
            State(state.clone()),
            auth_headers("process-eval-worker-token-a"),
            Json(TraceProcessEvaluationJobRequest {
                submission_id,
                process_evaluation: ProcessEvaluationLabels {
                    evaluator_name: Some("trajectory-judge".to_string()),
                    evaluator_version: "judge-v1".to_string(),
                    labels: vec![
                        trace_commons_protocol::trace_contribution::ProcessEvaluatorLabel::CorrectToolSelection,
                        trace_commons_protocol::trace_contribution::ProcessEvaluatorLabel::ProperVerification,
                    ],
                    tool_selection: Some(ProcessEvalRating::Pass),
                    verification: Some(ProcessEvalRating::Pass),
                    overall_score: Some(0.91),
                    ..ProcessEvaluationLabels::default()
                },
                reason: process_eval_reason.to_string(),
                utility_credit_points_delta: Some(0.85),
                utility_external_ref: Some("process-eval:nightly-42".to_string()),
                ranking_label: None,
            }),
        )
        .await
        .expect("process evaluation worker can label accepted trace");
    assert_eq!(response.submission_id, submission_id);
    assert_eq!(response.status, TraceCorpusStatus::Accepted);
    assert_eq!(response.process_eval_value, Some(0.91));
    assert_eq!(response.review_scorecard.process_eval_value, Some(0.91));
    assert_eq!(response.utility_credit_appended_count, 1);
    assert_eq!(response.utility_credit_skipped_existing_count, 0);

    let Json(retry_response) = process_evaluation_worker_handler(
            State(state.clone()),
            auth_headers("process-eval-worker-token-a"),
            Json(TraceProcessEvaluationJobRequest {
                submission_id,
                process_evaluation: ProcessEvaluationLabels {
                    evaluator_name: Some("trajectory-judge".to_string()),
                    evaluator_version: "judge-v1".to_string(),
                    labels: vec![
                        trace_commons_protocol::trace_contribution::ProcessEvaluatorLabel::CorrectToolSelection,
                        trace_commons_protocol::trace_contribution::ProcessEvaluatorLabel::ProperVerification,
                    ],
                    verification: Some(ProcessEvalRating::Pass),
                    overall_score: Some(0.91),
                    ..ProcessEvaluationLabels::default()
                },
                reason: process_eval_reason.to_string(),
                utility_credit_points_delta: Some(0.85),
                utility_external_ref: Some("process-eval:nightly-42".to_string()),
                ranking_label: None,
            }),
        )
        .await
        .expect("process evaluation utility credit retry is idempotent");
    assert_eq!(retry_response.utility_credit_appended_count, 0);
    assert_eq!(retry_response.utility_credit_skipped_existing_count, 1);

    let record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("record reads")
        .expect("record exists");
    let stored = read_envelope_by_record(state.as_ref(), &record).expect("envelope reads");
    let labels = stored
        .process_evaluation
        .expect("process evaluation labels stored");
    assert_eq!(labels.evaluator_version, "judge-v1");
    assert_eq!(labels.overall_score, Some(0.91));

    let credit_events = read_all_credit_events(temp.path(), "tenant-a").expect("credit reads");
    let process_eval_credit_events = credit_events
        .iter()
        .filter(|event| {
            event.submission_id == submission_id
                && event.event_type == TraceCreditLedgerEventType::TrainingUtility
                && event.external_ref.as_deref() == Some("process-eval:nightly-42")
        })
        .collect::<Vec<_>>();
    assert_eq!(process_eval_credit_events.len(), 1);
    assert!(
        process_eval_credit_events[0]
            .reason
            .as_deref()
            .is_some_and(|reason| reason.contains("process evaluation utility"))
    );

    let derived = read_derived_record(temp.path(), "tenant-a", submission_id)
        .expect("derived reads")
        .expect("derived exists");
    assert!(
        derived
            .coverage_tags
            .iter()
            .any(|tag| tag == "process_eval:high")
    );
    assert!(
        derived
            .coverage_tags
            .iter()
            .any(|tag| tag == "process_label:proper_verification")
    );
    assert!(
        derived
            .coverage_tags
            .iter()
            .any(|tag| tag == "process_verification:pass")
    );

    let Json(analytics) = analytics_handler(
        State(state.clone()),
        Query(TraceAnalyticsQuery::default()),
        auth_headers("review-token-a"),
    )
    .await
    .expect("reviewer analytics reads process evaluation aggregates");
    assert_eq!(analytics.process_evaluation.evaluated_traces, 1);
    assert_eq!(
        analytics
            .process_evaluation
            .by_label
            .get("proper_verification"),
        Some(&1)
    );
    assert_eq!(
        analytics
            .process_evaluation
            .by_rating
            .get("verification")
            .and_then(|ratings| ratings.get("pass")),
        Some(&1)
    );
    assert_eq!(
        analytics.process_evaluation.by_score_band.get("high"),
        Some(&1)
    );

    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit reads");
    let content_read_reason = audit_events
        .iter()
        .find_map(|event| {
            (event.kind == "trace_content_read" && event.submission_id == submission_id)
                .then_some(event.reason.as_deref())
                .flatten()
        })
        .expect("process evaluation content read audit exists");
    assert!(content_read_reason.contains("surface=process_evaluation_worker"));
    assert!(content_read_reason.contains("purpose_hash=sha256:"));
    assert!(!content_read_reason.contains(process_eval_reason));
    assert!(audit_events.iter().any(|event| {
        event.kind == "process_evaluation"
            && event.submission_id == submission_id
            && event.reason.as_deref().is_some_and(|reason| {
                reason.contains("process_eval_value=0.9100")
                    && reason.contains("offline trajectory evaluator")
            })
    }));
}

#[test]
fn audit_backfill_projects_trace_content_read_metadata_without_raw_purpose() {
    let purpose_hash = sha256_prefixed("operator replay reason");
    let audit_event = TraceCommonsAuditEvent {
        event_id: Uuid::new_v4(),
        tenant_id: "tenant-a".to_string(),
        submission_id: Uuid::new_v4(),
        kind: "trace_content_read".to_string(),
        created_at: Utc::now(),
        status: None,
        actor_role: Some(TokenRole::Reviewer),
        actor_principal_ref: Some("reviewer-a".to_string()),
        reason: Some(format!(
            "surface=process_evaluation_worker;purpose_hash={purpose_hash}"
        )),
        export_count: None,
        export_id: None,
        decision_inputs_hash: None,
        previous_event_hash: None,
        event_hash: None,
    };

    let (action, metadata) = audit_backfill_storage_projection(&audit_event);

    assert_eq!(action, StorageTraceAuditAction::Read);
    let metadata_json =
        serde_json::to_value(&metadata).expect("trace content read metadata serializes");
    assert_eq!(
        metadata_json.get("kind").and_then(|value| value.as_str()),
        Some("trace_content_read")
    );
    assert_eq!(
        metadata_json
            .get("surface")
            .and_then(|value| value.as_str()),
        Some("process_evaluation_worker")
    );
    assert_eq!(
        metadata_json
            .get("purpose_hash")
            .and_then(|value| value.as_str()),
        Some(purpose_hash.as_str())
    );

    let storage_event = StorageTraceAuditEventRecord {
        audit_event_id: audit_event.event_id,
        tenant_id: audit_event.tenant_id.clone(),
        audit_sequence: 1,
        actor_principal_ref: audit_event.actor_principal_ref.clone().unwrap(),
        actor_role: "reviewer".to_string(),
        action,
        reason: audit_event.reason.clone(),
        request_id: None,
        submission_id: Some(audit_event.submission_id),
        object_ref_id: None,
        export_manifest_id: None,
        decision_inputs_hash: None,
        previous_event_hash: None,
        event_hash: None,
        canonical_event_json: None,
        metadata,
        occurred_at: audit_event.created_at,
    };
    let projected_event = trace_commons_audit_event_from_storage("tenant-a", storage_event)
        .expect("storage audit projects");
    assert_eq!(projected_event.kind, "trace_content_read");
    assert_eq!(projected_event.reason, audit_event.reason);
}

