#[tokio::test]
async fn retention_maintenance_scheduler_tick_purges_tenant_expired_objects_only() {
    let temp = tempfile::tempdir().expect("temp dir");
    let artifact_temp = tempfile::tempdir().expect("artifact temp dir");
    let artifact_store = test_artifact_store(artifact_temp.path());
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        None,
        Some(artifact_store.clone()),
        false,
        false,
        false,
        false,
    );
    let expired_at = Utc::now() - Duration::days(2);

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("tenant-a submission succeeds");
    let mut record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("tenant-a record reads")
        .expect("tenant-a record exists");
    let object_path = temp.path().join(&record.object_key);
    let receipt = record
        .artifact_receipt
        .clone()
        .expect("tenant-a encrypted receipt exists");
    record.status = TraceCorpusStatus::Expired;
    record.expires_at = Some(expired_at);
    write_submission_record(temp.path(), &record).expect("tenant-a expired record writes");

    let mut tenant_b_envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut tenant_b_envelope);
    let tenant_b_submission_id = tenant_b_envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-b"),
        submit_body(tenant_b_envelope),
    )
    .await
    .expect("tenant-b submission succeeds");
    let mut tenant_b_record =
        read_submission_record(temp.path(), "tenant-b", tenant_b_submission_id)
            .expect("tenant-b record reads")
            .expect("tenant-b record exists");
    let tenant_b_object_path = temp.path().join(&tenant_b_record.object_key);
    let tenant_b_receipt = tenant_b_record
        .artifact_receipt
        .clone()
        .expect("tenant-b encrypted receipt exists");
    tenant_b_record.status = TraceCorpusStatus::Expired;
    tenant_b_record.expires_at = Some(expired_at);
    write_submission_record(temp.path(), &tenant_b_record).expect("tenant-b expired record writes");

    let cutoff = Utc::now();
    let dry_run = run_trace_retention_maintenance_scheduler_tick(
        state.clone(),
        &TraceRetentionMaintenanceSchedulerConfig {
            worker_token: SecretString::from("retention-worker-token-a".to_string()),
            interval: StdDuration::from_secs(60),
            dry_run: true,
            purpose: "scheduled retention maintenance dry run".to_string(),
            prune_export_cache: false,
            max_export_age_hours: None,
            purge_expired_before: Some(cutoff),
        },
    )
    .await
    .expect("retention maintenance scheduler dry-run tick succeeds");
    assert!(dry_run.run.dry_run);
    assert_eq!(dry_run.run.tenant_id, "tenant-a");
    assert_eq!(dry_run.run.records_marked_purged, 1);
    assert_eq!(dry_run.run.trace_object_files_deleted, 0);
    assert_eq!(dry_run.run.encrypted_artifacts_deleted, 0);
    assert!(object_path.exists());
    artifact_store
        .read_artifact(&tenant_storage_ref("tenant-a"), &receipt)
        .expect("dry-run keeps tenant-a encrypted artifact");
    assert!(tenant_b_object_path.exists());
    artifact_store
        .read_artifact(&tenant_storage_ref("tenant-b"), &tenant_b_receipt)
        .expect("dry-run keeps tenant-b encrypted artifact");

    let live = run_trace_retention_maintenance_scheduler_tick(
        state,
        &TraceRetentionMaintenanceSchedulerConfig {
            worker_token: SecretString::from("retention-worker-token-a".to_string()),
            interval: StdDuration::from_secs(60),
            dry_run: false,
            purpose: "scheduled retention maintenance".to_string(),
            prune_export_cache: false,
            max_export_age_hours: None,
            purge_expired_before: Some(cutoff),
        },
    )
    .await
    .expect("retention maintenance scheduler live tick succeeds");
    assert!(!live.run.dry_run);
    assert_eq!(live.run.tenant_id, "tenant-a");
    assert_eq!(live.run.records_marked_purged, 1);
    assert_eq!(live.run.trace_object_files_deleted, 1);
    assert_eq!(live.run.encrypted_artifacts_deleted, 1);
    assert!(!object_path.exists());
    artifact_store
        .read_artifact(&tenant_storage_ref("tenant-a"), &receipt)
        .expect_err("live tick deletes tenant-a encrypted artifact");
    let purged_record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("tenant-a record reads after live tick")
        .expect("tenant-a record remains as tombstone");
    assert_eq!(purged_record.status, TraceCorpusStatus::Purged);
    assert!(purged_record.purged_at.is_some());
    assert!(tenant_b_object_path.exists());
    artifact_store
        .read_artifact(&tenant_storage_ref("tenant-b"), &tenant_b_receipt)
        .expect("tenant-a scheduler tick keeps tenant-b encrypted artifact");
    let tenant_b_record_after =
        read_submission_record(temp.path(), "tenant-b", tenant_b_submission_id)
            .expect("tenant-b record reads after live tick")
            .expect("tenant-b record remains");
    assert_eq!(tenant_b_record_after.status, TraceCorpusStatus::Expired);
    assert!(tenant_b_record_after.purged_at.is_none());
}

#[tokio::test]
async fn maintenance_purges_filesystem_remote_object_primary_artifact() {
    let temp = tempfile::tempdir().expect("temp dir");
    let remote_temp = tempfile::tempdir().expect("remote artifact temp dir");
    let key = trace_commons_server::secrets::keychain::generate_master_key_hex();
    let remote_config = TraceRemoteObjectStoreConfig::from_parts(
        Some("file_system"),
        Some(remote_temp.path().to_str().expect("utf8 temp path")),
        Some("retention-test-kms-key-ref"),
        Some("retention-test-credential-ref"),
    )
    .expect("filesystem remote config parses");
    let artifact_store =
        ConfiguredTraceArtifactStore::remote_service(remote_config, SecretString::from(key))
            .expect("filesystem remote service store builds");
    let mut state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        None,
        Some(artifact_store),
        false,
        false,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );
    Arc::make_mut(&mut state).object_primary_submit_review = true;

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("object-primary submission succeeds");
    let record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("record reads")
        .expect("record exists");
    let object_path = temp.path().join(&record.object_key);
    assert!(
        !object_path.exists(),
        "object-primary submit should not write a plaintext envelope body"
    );
    let receipt = record
        .artifact_receipt
        .clone()
        .expect("remote service artifact receipt exists");
    let artifact_store = state
        .artifact_store
        .as_ref()
        .expect("remote service artifact store is configured");
    let stored_envelope: TraceContributionEnvelope = artifact_store
        .get_json(&record.tenant_storage_ref, &receipt)
        .expect("remote service artifact can be read");
    assert_eq!(stored_envelope.submission_id, submission_id);
    assert_eq!(
        count_files_under_dir(remote_temp.path()),
        1,
        "remote service artifact provider should contain the submitted envelope only"
    );

    let mut tenant_b_envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut tenant_b_envelope);
    let tenant_b_submission_id = tenant_b_envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-b"),
        submit_body(tenant_b_envelope),
    )
    .await
    .expect("tenant-b object-primary submission succeeds");
    let tenant_b_record = read_submission_record(temp.path(), "tenant-b", tenant_b_submission_id)
        .expect("tenant-b record reads")
        .expect("tenant-b record exists");
    let tenant_b_object_path = temp.path().join(&tenant_b_record.object_key);
    assert!(
        !tenant_b_object_path.exists(),
        "object-primary submit should not write a tenant-b plaintext envelope body"
    );
    let tenant_b_receipt = tenant_b_record
        .artifact_receipt
        .clone()
        .expect("tenant-b remote service artifact receipt exists");
    let tenant_b_stored_envelope: TraceContributionEnvelope = artifact_store
        .get_json(&tenant_b_record.tenant_storage_ref, &tenant_b_receipt)
        .expect("tenant-b remote service artifact can be read");
    assert_eq!(
        tenant_b_stored_envelope.submission_id,
        tenant_b_submission_id
    );
    assert_eq!(
        count_files_under_dir(remote_temp.path()),
        2,
        "remote service artifact provider should contain both tenants' envelopes"
    );

    let metadata_path = temp
        .path()
        .join("tenants")
        .join(tenant_storage_key("tenant-a"))
        .join("metadata")
        .join(format!("{submission_id}.json"));
    let mut metadata_json = serde_json::to_value(record).expect("record serializes");
    let expired_at = Utc::now() - chrono::Duration::days(2);
    metadata_json["expires_at"] = serde_json::json!(expired_at.to_rfc3339());
    write_json_file(&metadata_path, &metadata_json, "expired trace metadata")
        .expect("expired metadata writes");

    let tenant_b_metadata_path = temp
        .path()
        .join("tenants")
        .join(tenant_storage_key("tenant-b"))
        .join("metadata")
        .join(format!("{tenant_b_submission_id}.json"));
    let mut tenant_b_metadata_json =
        serde_json::to_value(tenant_b_record).expect("tenant-b record serializes");
    tenant_b_metadata_json["expires_at"] = serde_json::json!(expired_at.to_rfc3339());
    write_json_file(
        &tenant_b_metadata_path,
        &tenant_b_metadata_json,
        "tenant-b expired trace metadata",
    )
    .expect("tenant-b expired metadata writes");

    let Json(dry_run) = maintenance_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceMaintenanceRequest {
            purpose: Some("test_remote_retention_purge_dry_run".to_string()),
            dry_run: true,
            backfill_db_mirror: false,
            index_vectors: false,
            reconcile_db_mirror: false,
            verify_audit_chain: false,
            prune_export_cache: false,
            max_export_age_hours: None,
            purge_expired_before: Some(Utc::now()),
        }),
    )
    .await
    .expect("remote dry-run purge succeeds");
    assert_eq!(dry_run.records_marked_purged, 0);
    assert_eq!(dry_run.trace_object_files_deleted, 0);
    assert_eq!(dry_run.encrypted_artifacts_deleted, 0);
    assert!(!object_path.exists());
    artifact_store
        .get_json::<TraceContributionEnvelope>(&tenant_storage_ref("tenant-a"), &receipt)
        .expect("dry-run keeps remote service artifact");
    artifact_store
        .get_json::<TraceContributionEnvelope>(&tenant_storage_ref("tenant-b"), &tenant_b_receipt)
        .expect("dry-run keeps tenant-b remote service artifact");
    assert_eq!(
        count_files_under_dir(remote_temp.path()),
        2,
        "dry-run purge must not delete remote service artifacts"
    );

    let Json(response) = maintenance_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceMaintenanceRequest {
            purpose: Some("test_remote_retention_purge".to_string()),
            dry_run: false,
            backfill_db_mirror: false,
            index_vectors: false,
            reconcile_db_mirror: false,
            verify_audit_chain: false,
            prune_export_cache: false,
            max_export_age_hours: None,
            purge_expired_before: Some(Utc::now()),
        }),
    )
    .await
    .expect("remote purge succeeds");
    assert_eq!(response.records_marked_expired, 1);
    assert_eq!(response.records_marked_purged, 1);
    assert_eq!(response.trace_object_files_deleted, 0);
    assert_eq!(response.encrypted_artifacts_deleted, 1);
    assert!(!object_path.exists());
    let purged_record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("purged record reads")
        .expect("purged record exists");
    assert_eq!(purged_record.status, TraceCorpusStatus::Purged);
    assert!(purged_record.purged_at.is_some());
    artifact_store
        .get_json::<TraceContributionEnvelope>(&tenant_storage_ref("tenant-a"), &receipt)
        .expect_err("remote service artifact was deleted");
    assert!(!tenant_b_object_path.exists());
    let tenant_b_record_after =
        read_submission_record(temp.path(), "tenant-b", tenant_b_submission_id)
            .expect("tenant-b record reads after tenant-a remote purge")
            .expect("tenant-b record remains after tenant-a remote purge");
    assert_ne!(tenant_b_record_after.status, TraceCorpusStatus::Purged);
    assert!(tenant_b_record_after.purged_at.is_none());
    artifact_store
        .get_json::<TraceContributionEnvelope>(&tenant_storage_ref("tenant-b"), &tenant_b_receipt)
        .expect("tenant-a remote purge keeps tenant-b remote service artifact");
    assert_eq!(
        count_files_under_dir(remote_temp.path()),
        1,
        "live purge must delete only the filesystem-remote artifact in tenant scope"
    );
}

#[tokio::test]
async fn retention_dry_run_drill_records_smoke_evidence_and_preserves_records() {
    use axum::body::Body;
    use tower::ServiceExt;

    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("submission succeeds");
    let record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("record reads")
        .expect("record exists");
    let mut tenant_b_envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut tenant_b_envelope);
    let tenant_b_submission_id = tenant_b_envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-b"),
        submit_body(tenant_b_envelope),
    )
    .await
    .expect("tenant-b submission succeeds");
    let tenant_b_record = read_submission_record(temp.path(), "tenant-b", tenant_b_submission_id)
        .expect("tenant-b record reads")
        .expect("tenant-b record exists");
    let Json(pre_expiry_export) = dataset_replay_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Query(DatasetExportQuery {
            limit: Some(10),
            purpose: Some("test_retention_dry_run_drill_cache".to_string()),
            status: None,
            privacy_risk: None,
            consent_scope: None,
        }),
    )
    .await
    .expect("pre-expiry export succeeds");
    let cached_export_path =
        export_artifact_dir(temp.path(), "tenant-a", pre_expiry_export.export_id)
            .join("dataset.json");
    write_json_file(
        &cached_export_path,
        &pre_expiry_export,
        "test retention dry-run source export cache",
    )
    .expect("expired source cache writes");

    let metadata_path = temp
        .path()
        .join("tenants")
        .join(tenant_storage_key("tenant-a"))
        .join("metadata")
        .join(format!("{submission_id}.json"));
    let mut metadata_json = serde_json::to_value(record).expect("record serializes");
    metadata_json["expires_at"] =
        serde_json::json!((Utc::now() - chrono::Duration::days(1)).to_rfc3339());
    write_json_file(&metadata_path, &metadata_json, "expired trace metadata")
        .expect("expired metadata writes");

    let tenant_b_metadata_path = temp
        .path()
        .join("tenants")
        .join(tenant_storage_key("tenant-b"))
        .join("metadata")
        .join(format!("{tenant_b_submission_id}.json"));
    let mut tenant_b_metadata_json =
        serde_json::to_value(tenant_b_record).expect("tenant-b record serializes");
    tenant_b_metadata_json["expires_at"] =
        serde_json::json!((Utc::now() - chrono::Duration::days(1)).to_rfc3339());
    write_json_file(
        &tenant_b_metadata_path,
        &tenant_b_metadata_json,
        "tenant-b expired trace metadata",
    )
    .expect("tenant-b expired metadata writes");

    let response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("POST")
                .uri("/v1/admin/retention-dry-run-drill")
                .header(AUTHORIZATION, "Bearer admin-token-a")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "purpose": "operator retention dry-run drill",
                        "record_evidence": true
                    })
                    .to_string(),
                ))
                .expect("request builds"),
        )
        .await
        .expect("retention dry-run drill response");
    assert_eq!(response.status(), StatusCode::OK);
    let body = axum::body::to_bytes(response.into_body(), 16 * 1024)
        .await
        .expect("body reads");
    let value: serde_json::Value =
        serde_json::from_slice(&body).expect("retention dry-run drill response parses");
    assert_eq!(value["ready"], serde_json::json!(true));
    assert_eq!(value["dry_run"], serde_json::json!(true));
    assert_eq!(value["records_marked_expired"], serde_json::json!(1));
    assert_eq!(value["derived_marked_expired"], serde_json::json!(1));
    assert_eq!(value["export_cache_files_pruned"], serde_json::json!(1));
    assert_eq!(value["trace_object_files_deleted"], serde_json::json!(0));
    assert_eq!(value["encrypted_artifacts_deleted"], serde_json::json!(0));
    assert_eq!(value["blocking_gaps"], serde_json::json!([]));
    assert_eq!(
        value["recorded_evidence"]["check_name"],
        serde_json::json!("retention_dry_run")
    );
    assert_eq!(
        value["recorded_evidence"]["status"],
        serde_json::json!("passed")
    );
    assert!(
        value["evidence_hash"]
            .as_str()
            .expect("evidence hash is string")
            .starts_with("sha256:")
    );
    let body_text = std::str::from_utf8(&body).expect("body is utf8");
    assert!(!body_text.contains("admin-token-a"));
    assert!(cached_export_path.exists());
    let dry_run_record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("dry-run record reads")
        .expect("dry-run record exists");
    assert_eq!(dry_run_record.status, TraceCorpusStatus::Accepted);
    let dry_run_derived = read_derived_record(temp.path(), "tenant-a", submission_id)
        .expect("dry-run derived reads")
        .expect("dry-run derived exists");
    assert_eq!(dry_run_derived.status, TraceCorpusStatus::Accepted);
    let tenant_b_record_after =
        read_submission_record(temp.path(), "tenant-b", tenant_b_submission_id)
            .expect("tenant-b record reads after tenant-a dry-run drill")
            .expect("tenant-b record remains after tenant-a dry-run drill");
    assert_eq!(tenant_b_record_after.status, TraceCorpusStatus::Accepted);
    assert!(tenant_b_record_after.purged_at.is_none());
    let tenant_b_derived_after =
        read_derived_record(temp.path(), "tenant-b", tenant_b_submission_id)
            .expect("tenant-b derived reads after tenant-a dry-run drill")
            .expect("tenant-b derived remains after tenant-a dry-run drill");
    assert_eq!(tenant_b_derived_after.status, TraceCorpusStatus::Accepted);
    let audit_events =
        read_all_audit_events(temp.path(), "tenant-a").expect("file audit events read");
    assert!(audit_events.iter().any(|event| {
        event.kind == "maintenance"
            && event.reason.as_deref().is_some_and(|reason| {
                reason.contains("dry_run=true") && reason.contains("records_marked_expired=1")
            })
    }));
    assert!(audit_events.iter().any(|event| {
        event.kind == "rollout_smoke_evidence"
            && event.reason.as_deref().is_some_and(|reason| {
                reason.contains("check_name=retention_dry_run") && reason.contains("status=passed")
            })
    }));
    let tenant_b_audit_events =
        read_all_audit_events(temp.path(), "tenant-b").expect("tenant-b audit events read");
    assert!(
        !tenant_b_audit_events
            .iter()
            .any(|event| event.kind == "maintenance")
    );
    assert!(
        !tenant_b_audit_events
            .iter()
            .any(|event| event.kind == "rollout_smoke_evidence")
    );
}

