#[tokio::test]
async fn credit_settlement_drill_requires_near_adapter_auth_when_requested() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    use axum::body::Body;
    use tower::ServiceExt;

    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    Arc::make_mut(&mut state).credit_settlement_max_micros_per_account = Some(2_000_000);
    Arc::make_mut(&mut state).near_credit_submitter =
        Some(Arc::new(FakeNearCreditSubmitter::default()));
    Arc::make_mut(&mut state).near_credit_confirmer =
        Some(Arc::new(FakeNearCreditConfirmer::default()));
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("submission succeeds");

    let Json(event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 0.75,
            reason: Some("frontier lab near adapter auth drill probe".to_string()),
            external_ref: Some("lab-attestation:near-adapter-auth-drill".to_string()),
        }),
    )
    .await
    .expect("reviewer can append delayed utility credit");

    let response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("POST")
                .uri("/v1/admin/credit-settlement-drill")
                .header(AUTHORIZATION, "Bearer admin-token-a")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "policy_version": "trace-credit-policy-v1",
                        "near_contract_id": "trace-credits.testnet",
                        "require_near_adapter_auth": true,
                        "record_evidence": true
                    })
                    .to_string(),
                ))
                .expect("adapter auth drill request builds"),
        )
        .await
        .expect("adapter auth drill response");
    assert_eq!(response.status(), StatusCode::OK);
    let body = axum::body::to_bytes(response.into_body(), 16384)
        .await
        .expect("adapter auth body reads");
    let value: serde_json::Value = serde_json::from_slice(&body).expect("adapter auth json parses");
    assert_eq!(value["ready"], serde_json::json!(false));
    assert_eq!(value["require_near_adapter_auth"], serde_json::json!(true));
    assert_eq!(value["near_submitter_configured"], serde_json::json!(true));
    assert_eq!(value["near_confirmer_configured"], serde_json::json!(true));
    assert_eq!(
        value["near_submitter_auth_configured"],
        serde_json::json!(false)
    );
    assert_eq!(
        value["near_confirmer_auth_configured"],
        serde_json::json!(false)
    );
    assert_eq!(
        value["blocking_gaps"],
        serde_json::json!([
            "near_credit_submitter_auth_missing",
            "near_credit_confirmer_auth_missing"
        ])
    );
    assert_eq!(
        value["recorded_evidence"]["status"],
        serde_json::json!("failed")
    );
    let body_text = std::str::from_utf8(&body).expect("body is utf8");
    assert!(!body_text.contains("admin-token-a"));
    assert!(!body_text.contains("token-a"));
    assert!(!body_text.contains(&event.event_id.to_string()));
    assert!(!body_text.contains("frontier lab near adapter auth drill probe"));
    assert!(!body_text.contains("lab-attestation:near-adapter-auth-drill"));
    assert!(
        read_all_credit_settlement_batches(temp.path(), "tenant-a")
            .expect("settlement reads")
            .is_empty()
    );
    assert!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-a")
            .expect("outbox reads")
            .is_empty()
    );
}

#[tokio::test]
async fn admin_credit_settlement_drill_dry_runs_risk_and_records_smoke_evidence() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    use axum::body::Body;
    use tower::ServiceExt;

    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    Arc::make_mut(&mut state).credit_settlement_max_micros_per_account = Some(1_000_000);
    Arc::make_mut(&mut state).near_credit_submitter =
        Some(Arc::new(FakeNearCreditSubmitter::default()));
    Arc::make_mut(&mut state).near_credit_confirmer =
        Some(Arc::new(FakeNearCreditConfirmer::default()));

    let mut high_utility = sample_envelope().await;
    make_metadata_only_low_risk(&mut high_utility);
    high_utility.consent.scopes = vec![ConsentScope::ModelTraining];
    high_utility.trace_card.consent_scope = ConsentScope::ModelTraining;
    high_utility.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let high_utility_submission_id = high_utility.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(high_utility),
    )
    .await
    .expect("high utility submission succeeds");
    let Json(high_event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(high_utility_submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 1.75,
            reason: Some("frontier lab high utility for drill".to_string()),
            external_ref: Some("lab-attestation:settlement-drill-high".to_string()),
        }),
    )
    .await
    .expect("reviewer can append high utility credit");

    let mut held_utility = sample_envelope().await;
    make_metadata_only_low_risk(&mut held_utility);
    held_utility.consent.scopes = vec![ConsentScope::ModelTraining];
    held_utility.trace_card.consent_scope = ConsentScope::ModelTraining;
    held_utility.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let held_utility_submission_id = held_utility.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a-2"),
        submit_body(held_utility),
    )
    .await
    .expect("held utility submission succeeds");
    let Json(held_event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(held_utility_submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 0.5,
            reason: Some("frontier lab held utility for drill".to_string()),
            external_ref: Some("lab-attestation:settlement-drill-held".to_string()),
        }),
    )
    .await
    .expect("reviewer can append held utility credit");
    let Json(_) = credit_hold_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditHoldRequest {
            credit_account_ref: held_event.auth_principal_ref.clone(),
            reason: StorageTraceCreditHoldReason::AttestationDispute,
            reason_detail: "settlement drill hold review".to_string(),
        }),
    )
    .await
    .expect("admin can place held-account review hold");

    let contributor_response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("POST")
                .uri("/v1/admin/credit-settlement-drill")
                .header(AUTHORIZATION, "Bearer token-a")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "policy_version": "trace-credit-policy-v1",
                        "near_contract_id": "trace-credits.testnet"
                    })
                    .to_string(),
                ))
                .expect("contributor request builds"),
        )
        .await
        .expect("contributor response");
    assert_eq!(contributor_response.status(), StatusCode::FORBIDDEN);

    let invalid_contract_response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("POST")
                .uri("/v1/admin/credit-settlement-drill")
                .header(AUTHORIZATION, "Bearer admin-token-a")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "policy_version": "trace-credit-policy-v1",
                        "near_contract_id": "Trace Credits.testnet"
                    })
                    .to_string(),
                ))
                .expect("invalid contract request builds"),
        )
        .await
        .expect("invalid contract response");
    assert_eq!(invalid_contract_response.status(), StatusCode::BAD_REQUEST);
    let invalid_body = axum::body::to_bytes(invalid_contract_response.into_body(), 8192)
        .await
        .expect("invalid body reads");
    let invalid_text = String::from_utf8(invalid_body.to_vec()).expect("invalid body utf8");
    assert!(invalid_text.contains("NEAR contract id"));

    let drill_response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("POST")
                .uri("/v1/admin/credit-settlement-drill")
                .header(AUTHORIZATION, "Bearer admin-token-a")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "policy_version": "trace-credit-policy-v1",
                        "near_contract_id": "trace-credits.testnet",
                        "account_limit": 10,
                        "record_evidence": true
                    })
                    .to_string(),
                ))
                .expect("drill request builds"),
        )
        .await
        .expect("drill response");
    assert_eq!(drill_response.status(), StatusCode::OK);
    let body = axum::body::to_bytes(drill_response.into_body(), 16384)
        .await
        .expect("body reads");
    let value: serde_json::Value = serde_json::from_slice(&body).expect("json parses");
    assert_eq!(value["ready"], serde_json::json!(false));
    assert_eq!(
        value["risk_summary"]["pending_account_count"],
        serde_json::json!(1)
    );
    assert_eq!(
        value["risk_summary"]["held_account_count"],
        serde_json::json!(1)
    );
    assert_eq!(
        value["risk_summary"]["over_cap_account_count"],
        serde_json::json!(1)
    );
    assert_eq!(value["settlement"]["dry_run"], serde_json::json!(true));
    assert_eq!(
        value["settlement"]["settled_source_event_count"],
        serde_json::json!(0)
    );
    assert_eq!(
        value["settlement"]["settlement_policy_excluded_source_event_count"],
        serde_json::json!(1)
    );
    assert_eq!(
        value["blocking_gaps"],
        serde_json::json!([
            "held_credit_accounts_present=1",
            "over_cap_credit_accounts_present=1",
            "settlement_policy_excluded_source_events=1"
        ])
    );
    assert!(
        value["evidence_hash"]
            .as_str()
            .is_some_and(|hash| hash.starts_with("sha256:"))
    );
    assert_eq!(
        value["recorded_evidence"]["check_name"],
        serde_json::json!("credit_settlement")
    );
    assert_eq!(
        value["recorded_evidence"]["status"],
        serde_json::json!("failed")
    );
    assert!(
        value["recorded_evidence"]["evidence_hash"]
            .as_str()
            .is_some_and(|hash| hash.starts_with("sha256:"))
    );

    let body_text = std::str::from_utf8(&body).expect("response is utf8");
    assert!(!body_text.contains("token-a"));
    assert!(!body_text.contains(&high_event.event_id.to_string()));
    assert!(!body_text.contains(&held_event.event_id.to_string()));
    assert!(!body_text.contains("frontier lab high utility for drill"));
    assert!(!body_text.contains("frontier lab held utility for drill"));
    assert!(
        read_all_credit_settlement_batches(temp.path(), "tenant-a")
            .expect("settlement reads")
            .is_empty()
    );
    assert!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-a")
            .expect("outbox reads")
            .is_empty()
    );
    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit reads");
    assert!(audit_events.iter().any(|event| {
        event.kind == "rollout_smoke_evidence"
            && event.reason.as_deref().is_some_and(|reason| {
                reason.contains("check_name=credit_settlement") && reason.contains("status=failed")
            })
    }));
}

#[tokio::test]
async fn credit_settlement_worker_run_finalizes_pending_utility_without_admin_scope() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("training submission succeeds");

    let tenant_b_credit_error = utility_credit_handler(
        State(state.clone()),
        auth_headers("admin-token-b"),
        Json(TraceUtilityCreditJobRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.25,
            reason: "tenant-b cannot credit tenant-a utility source".to_string(),
            external_ref: "frontier:tenant-b-cross-tenant-utility-credit".to_string(),
            submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect_err("tenant-b admin cannot credit tenant-a utility source");
    assert_eq!(tenant_b_credit_error.0, StatusCode::NOT_FOUND);
    assert!(
        read_all_credit_events(temp.path(), "tenant-b")
            .expect("tenant-b credit reads")
            .is_empty()
    );

    let Json(credit) = utility_credit_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceUtilityCreditJobRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.25,
            reason: "frontier lab training value".to_string(),
            external_ref: "frontier:worker-settlement".to_string(),
            submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect("utility worker can append training credit");
    assert_eq!(credit.appended_count, 1);

    let mut tenant_b_envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut tenant_b_envelope);
    tenant_b_envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    tenant_b_envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    tenant_b_envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let tenant_b_submission_id = tenant_b_envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-b"),
        submit_body(tenant_b_envelope),
    )
    .await
    .expect("tenant-b training submission succeeds");
    let Json(_) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-b"),
        AxumPath(tenant_b_submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 1.5,
            reason: Some("tenant-b frontier lab training value".to_string()),
            external_ref: Some("frontier:tenant-b-worker-settlement".to_string()),
        }),
    )
    .await
    .expect("tenant-b reviewer can append training credit");

    let admin_surface_error = credit_settlement_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "utility worker cannot use admin settlement route".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: None,
            ranking_model_version: None,
            ranking_target_use: None,
        }),
    )
    .await
    .expect_err("utility workers cannot call the admin settlement route");
    assert_eq!(admin_surface_error.0, StatusCode::FORBIDDEN);

    let Json(settlement) = credit_settlement_worker_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceCreditSettlementWorkerRunRequest {
            request: TraceCreditSettlementRunRequest {
                dry_run: false,
                policy_version: "trace-credit-policy-v1".to_string(),
                reason: "scheduled utility settlement".to_string(),
                issuer_approval_evidence_hash: None,
                near_contract_id: Some("trace-credits.near".to_string()),
                ranking_model_version: None,
                ranking_target_use: None,
            },
            limit: None,
        }),
    )
    .await
    .expect("utility worker can run dedicated settlement surface");
    assert_eq!(settlement.settled_source_event_count, 1);
    assert_eq!(settlement.settled_account_count, 1);
    assert_eq!(settlement.near_outbox_item_count, 1);

    let batches =
        read_all_credit_settlement_batches(temp.path(), "tenant-a").expect("settlement reads");
    assert_eq!(batches.len(), 1);
    assert_eq!(
        batches[0].actor_principal_ref,
        static_token_principal_ref("utility-worker-token-a")
    );
    assert!(
        read_all_credit_settlement_batches(temp.path(), "tenant-b")
            .expect("tenant-b settlement reads")
            .is_empty()
    );
    let outbox = read_all_near_credit_outbox_items(temp.path(), "tenant-a").expect("outbox reads");
    assert_eq!(outbox.len(), 1);
    assert_eq!(
        outbox[0].status,
        StorageTraceCreditSettlementNearStatus::Pending
    );
    assert!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-b")
            .expect("tenant-b outbox reads")
            .is_empty()
    );

    let Json(retry) = credit_settlement_worker_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceCreditSettlementWorkerRunRequest {
            request: TraceCreditSettlementRunRequest {
                dry_run: false,
                policy_version: "trace-credit-policy-v1".to_string(),
                reason: "scheduled utility settlement retry".to_string(),
                issuer_approval_evidence_hash: None,
                near_contract_id: Some("trace-credits.near".to_string()),
                ranking_model_version: None,
                ranking_target_use: None,
            },
            limit: None,
        }),
    )
    .await
    .expect("worker settlement retry is idempotent");
    assert_eq!(retry.settled_source_event_count, 0);
    assert_eq!(retry.near_outbox_item_count, 0);
    assert_eq!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-a")
            .expect("retry outbox reads")
            .len(),
        1
    );
    assert!(
        read_all_credit_settlement_batches(temp.path(), "tenant-b")
            .expect("tenant-b settlement reads after retry")
            .is_empty()
    );
    assert!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-b")
            .expect("tenant-b outbox reads after retry")
            .is_empty()
    );
}

#[tokio::test]
async fn utility_credit_worker_route_rejects_reviewer_tokens_before_source_checks() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());

    let error = utility_credit_handler(
        State(state),
        auth_headers("review-token-a"),
        Json(TraceUtilityCreditJobRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 1.0,
            reason: "reviewer must use manual credit surfaces".to_string(),
            external_ref: "frontier:reviewer-worker-route-denied".to_string(),
            submission_ids: vec![Uuid::new_v4()],
        }),
    )
    .await
    .expect_err("reviewer token must not reach utility credit source checks");

    assert_eq!(error.0, StatusCode::FORBIDDEN);
}

#[tokio::test]
async fn credit_settlement_scheduler_tick_uses_worker_surface_for_dry_run_and_live_settlement() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("training submission succeeds");
    let Json(credit) = utility_credit_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceUtilityCreditJobRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.25,
            reason: "frontier lab training value".to_string(),
            external_ref: "frontier:scheduler-settlement".to_string(),
            submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect("utility worker can append training credit");
    assert_eq!(credit.appended_count, 1);

    let dry_run = run_trace_credit_settlement_scheduler_tick(
        state.clone(),
        &TraceCreditSettlementSchedulerConfig {
            worker_token: SecretString::from("utility-worker-token-a".to_string()),
            interval: StdDuration::from_secs(60),
            dry_run: true,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "scheduled settlement dry run".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
            limit: 100,
        },
    )
    .await
    .expect("settlement scheduler dry-run tick succeeds");
    assert!(dry_run.dry_run);
    assert_eq!(dry_run.settled_source_event_count, 1);
    assert_eq!(dry_run.near_outbox_item_count, 0);
    assert!(
        read_all_credit_settlement_batches(temp.path(), "tenant-a")
            .expect("settlement reads")
            .is_empty()
    );
    assert!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-a")
            .expect("outbox reads")
            .is_empty()
    );

    let live = run_trace_credit_settlement_scheduler_tick(
        state.clone(),
        &TraceCreditSettlementSchedulerConfig {
            worker_token: SecretString::from("utility-worker-token-a".to_string()),
            interval: StdDuration::from_secs(60),
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "scheduled settlement finalization".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
            limit: 100,
        },
    )
    .await
    .expect("settlement scheduler live tick succeeds");
    assert!(!live.dry_run);
    assert_eq!(live.settled_source_event_count, 1);
    assert_eq!(live.settled_account_count, 1);
    assert_eq!(live.near_outbox_item_count, 1);
    let batches =
        read_all_credit_settlement_batches(temp.path(), "tenant-a").expect("settlement reads");
    assert_eq!(batches.len(), 1);
    assert_eq!(
        batches[0].actor_principal_ref,
        static_token_principal_ref("utility-worker-token-a")
    );
    let outbox = read_all_near_credit_outbox_items(temp.path(), "tenant-a").expect("outbox reads");
    assert_eq!(outbox.len(), 1);
    assert_eq!(
        outbox[0].status,
        StorageTraceCreditSettlementNearStatus::Pending
    );

    let retry = run_trace_credit_settlement_scheduler_tick(
        state.clone(),
        &TraceCreditSettlementSchedulerConfig {
            worker_token: SecretString::from("utility-worker-token-a".to_string()),
            interval: StdDuration::from_secs(60),
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "scheduled settlement retry".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
            limit: 100,
        },
    )
    .await
    .expect("settlement scheduler retry tick is idempotent");
    assert_eq!(retry.settled_source_event_count, 0);
    assert_eq!(retry.near_outbox_item_count, 0);
}

