#[tokio::test]
async fn credit_settlement_append_rejects_finalized_source_event_conflict() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let tenant = test_reviewer_auth("tenant-a");
    let source_credit_event_id = Uuid::new_v4();
    let submission_id = Uuid::new_v4();
    let first_batch_id = Uuid::new_v4();
    let first_item_source_hash =
        source_credit_event_ids_hash("trace-credit-policy-v1", &[source_credit_event_id]);
    let mut first = TraceCreditSettlementBatchRecord {
        settlement_batch_id: first_batch_id,
        tenant_id: "tenant-a".to_string(),
        tenant_storage_ref: tenant_storage_ref("tenant-a"),
        policy_version: "trace-credit-policy-v1".to_string(),
        status: StorageTraceCreditSettlementBatchStatus::Finalized,
        reason_hash: "sha256:first-settlement".to_string(),
        issuer_approval_evidence_hash: None,
        source_credit_event_ids: vec![source_credit_event_id],
        source_submission_ids: vec![submission_id],
        source_list_hash: first_item_source_hash.clone(),
        settled_credit_points: 1.0,
        settled_credit_micros: 1_000_000,
        line_items: vec![StorageTraceCreditAccountSettlementLineItem {
            credit_account_ref: static_token_principal_ref("token-a"),
            credit_account_hash: sha256_prefixed(&static_token_principal_ref("token-a")),
            settled_credit_delta_micros: 1_000_000,
            source_credit_event_ids: vec![source_credit_event_id],
            source_submission_ids: vec![submission_id],
            source_list_hash: first_item_source_hash,
            near_status: StorageTraceCreditSettlementNearStatus::Disabled,
            near_outbox_id: None,
            near_payout_hold_reason: None,
        }],
        near_contract_id: None,
        ranking_model_version: None,
        ranking_target_use: None,
        ranking_calibration_run_id: None,
        ranking_calibration_report_hash: None,
        ranking_calibration_joined_evidence_hash: None,
        ranking_credit_events_excluded_count: 0,
        ranking_credit_events_excluded_reason_counts: BTreeMap::new(),
        actor_principal_ref: tenant.principal_ref.clone(),
        created_at: Utc::now(),
    };
    append_credit_settlement_batch_with_db_mirror(state.as_ref(), &tenant, &first)
        .await
        .expect("initial finalized batch appends");

    first.settlement_batch_id = Uuid::new_v4();
    first.reason_hash = "sha256:conflicting-settlement".to_string();
    first.created_at = Utc::now();
    let error = append_credit_settlement_batch_with_db_mirror(state.as_ref(), &tenant, &first)
        .await
        .expect_err("conflicting finalized source event is rejected");
    assert!(
        error
            .to_string()
            .contains("already finalized source credit event")
    );
    assert_eq!(
        read_all_credit_settlement_batches(temp.path(), "tenant-a")
            .expect("settlement reads")
            .len(),
        1
    );
}

#[tokio::test]
async fn credit_settlement_retry_recovers_missing_near_outbox_after_append_failure() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("submission succeeds");

    let Json(event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.25,
            reason: Some("frontier lab utility attested".to_string()),
            external_ref: Some("lab-attestation:batch-retry".to_string()),
        }),
    )
    .await
    .expect("reviewer can append delayed utility credit");

    let outbox_path = near_credit_outbox_path(temp.path(), "tenant-a");
    std::fs::create_dir_all(outbox_path.parent().expect("outbox parent"))
        .expect("create outbox parent");
    std::fs::create_dir(&outbox_path).expect("block outbox append path with directory");

    let error = credit_settlement_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "finalize settlement with blocked outbox".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
        }),
    )
    .await
    .expect_err("outbox append failure propagates");
    assert_eq!(error.0, StatusCode::INTERNAL_SERVER_ERROR);
    let stranded_batches = read_all_credit_settlement_batches(temp.path(), "tenant-a")
        .expect("settlement batch remains stranded for retry recovery");
    assert_eq!(stranded_batches.len(), 1);
    let stranded_batch_id = stranded_batches[0].settlement_batch_id;

    std::fs::remove_dir(&outbox_path).expect("clear blocked outbox path before retry");
    let Json(retry) = credit_settlement_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "retry settlement should repair missing outbox".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
        }),
    )
    .await
    .expect("retry repairs missing outbox from finalized batch");
    assert_eq!(retry.settled_source_event_count, 0);

    let outbox = read_all_near_credit_outbox_items(temp.path(), "tenant-a").expect("outbox reads");
    assert_eq!(outbox.len(), 1);
    assert_eq!(outbox[0].settlement_batch_id, stranded_batch_id);
    assert_eq!(outbox[0].near_call.method_name, "settle_credit_receipt");
    assert!(
        !serde_json::to_string(&outbox[0].near_call.args)
            .expect("NEAR args serialize")
            .contains(&event.event_id.to_string()),
        "NEAR call must stay hash-only and not include raw source event ids"
    );
}

