fn pending_benchmark_registry_outbox_item(
    benchmark_outbox_id: Uuid,
) -> TraceBenchmarkRegistryOutboxItem {
    TraceBenchmarkRegistryOutboxItem {
        benchmark_outbox_id,
        tenant_id: "tenant-a".to_string(),
        tenant_storage_ref: tenant_storage_ref("tenant-a"),
        conversion_id: Uuid::new_v4(),
        operation: StorageTraceBenchmarkRegistryOutboxOperation::Publish,
        registry_ref: "benchmark-registry:worker-submit".to_string(),
        artifact_payload_hash: "sha256:benchmark-registry-worker-artifact".to_string(),
        source_submission_ids_hash: "sha256:benchmark-registry-worker-sources".to_string(),
        evaluator_ref: Some(static_token_principal_ref("benchmark-worker-token-a")),
        evaluation_score: Some(0.97),
        status: StorageTraceBenchmarkRegistryOutboxStatus::Pending,
        created_at: Utc::now(),
        submitted_at: None,
        external_receipt_ref: None,
        last_error_hash: None,
        confirmed_at: None,
    }
}

fn submitted_benchmark_registry_outbox_item(
    benchmark_outbox_id: Uuid,
    operation: StorageTraceBenchmarkRegistryOutboxOperation,
) -> TraceBenchmarkRegistryOutboxItem {
    let mut item = pending_benchmark_registry_outbox_item(benchmark_outbox_id);
    item.operation = operation;
    item.status = StorageTraceBenchmarkRegistryOutboxStatus::Submitted;
    item.submitted_at = Some(Utc::now());
    item.external_receipt_ref = Some(format!(
        "external-registry:receipt:{}",
        match operation {
            StorageTraceBenchmarkRegistryOutboxOperation::Publish => "publish",
            StorageTraceBenchmarkRegistryOutboxOperation::Revoke => "revoke",
        }
    ));
    item
}

fn submitted_near_credit_outbox_item(
    near_outbox_id: Uuid,
    near_transaction_hash: &str,
    amount_micros: i64,
) -> TraceNearCreditOutboxItem {
    let settlement_batch_id = Uuid::new_v4();
    let receipt = NearCreditReceipt {
        settlement_batch_id,
        credit_account_hash: sha256_prefixed(&format!("near-credit-account:{near_outbox_id}")),
        policy_version: "trace-credit-policy-v1".to_string(),
        source_list_hash: sha256_prefixed(&format!("near-credit-sources:{near_outbox_id}")),
        attestation_hash: sha256_prefixed(&format!("near-credit-attestation:{near_outbox_id}")),
        amount_micros,
        issuer_signature_hash: sha256_prefixed(&format!(
            "near-credit-issuer-signature:{near_outbox_id}"
        )),
    };
    TraceNearCreditOutboxItem {
        near_outbox_id,
        tenant_id: "tenant-a".to_string(),
        tenant_storage_ref: tenant_storage_ref("tenant-a"),
        settlement_batch_id,
        credit_account_hash: receipt.credit_account_hash.clone(),
        near_call: NearCreditReceiptCall::settle("trace-credits.testnet", receipt)
            .expect("NEAR call builds"),
        status: StorageTraceCreditSettlementNearStatus::Submitted,
        payout_near_account_id: None,
        created_at: Utc::now(),
        submitted_at: Some(Utc::now()),
        near_transaction_hash: Some(near_transaction_hash.to_string()),
        last_error_hash: None,
        confirmed_at: None,
    }
}

fn pending_near_credit_outbox_item(
    near_outbox_id: Uuid,
    amount_micros: i64,
) -> TraceNearCreditOutboxItem {
    let mut item =
        submitted_near_credit_outbox_item(near_outbox_id, TEST_NEAR_TX_HASH_1, amount_micros);
    item.status = StorageTraceCreditSettlementNearStatus::Pending;
    item.submitted_at = None;
    item.near_transaction_hash = None;
    item
}

#[tokio::test]
async fn benchmark_registry_outbox_mark_status_is_tenant_scoped() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());

    let benchmark_outbox_id = Uuid::new_v4();
    let item = pending_benchmark_registry_outbox_item(benchmark_outbox_id);
    upsert_benchmark_registry_outbox_item(temp.path(), "tenant-a", &item)
        .expect("benchmark registry outbox file writes");

    let tenant_b_benchmark_outbox_id = Uuid::new_v4();
    let mut tenant_b_item = pending_benchmark_registry_outbox_item(tenant_b_benchmark_outbox_id);
    tenant_b_item.tenant_id = "tenant-b".to_string();
    tenant_b_item.tenant_storage_ref = tenant_storage_ref("tenant-b");
    upsert_benchmark_registry_outbox_item(temp.path(), "tenant-b", &tenant_b_item)
        .expect("tenant-b benchmark registry outbox file writes");

    let Json(submitted) = mark_benchmark_registry_outbox_status_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
            external_receipt_ref: Some("external-registry:tenant-a-submit".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect("benchmark worker can mark tenant-a registry outbox submitted");
    assert_eq!(
        submitted.status,
        StorageTraceBenchmarkRegistryOutboxStatus::Submitted
    );
    assert_eq!(
        submitted.external_receipt_ref.as_deref(),
        Some("external-registry:tenant-a-submit")
    );

    let tenant_b_error = mark_benchmark_registry_outbox_status_handler(
        State(state),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: tenant_b_benchmark_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
            external_receipt_ref: Some("external-registry:tenant-b-submit".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect_err("tenant-a benchmark worker cannot mark tenant-b outbox status");
    assert_eq!(tenant_b_error.0, StatusCode::NOT_FOUND);

    let tenant_b_outbox = read_all_benchmark_registry_outbox_items(temp.path(), "tenant-b")
        .expect("tenant-b benchmark registry outbox reads");
    assert_eq!(tenant_b_outbox.len(), 1);
    assert_eq!(
        tenant_b_outbox[0].status,
        StorageTraceBenchmarkRegistryOutboxStatus::Pending
    );
    assert!(tenant_b_outbox[0].external_receipt_ref.is_none());
}

#[tokio::test]
async fn benchmark_registry_outbox_mark_status_requires_authorized_central_issuer() {
    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    Arc::make_mut(&mut state).credit_settlement_central_issuer_principal_refs = Arc::new(
        BTreeSet::from([static_token_principal_ref("admin-token-a")]),
    );

    let benchmark_outbox_id = Uuid::new_v4();
    let item = pending_benchmark_registry_outbox_item(benchmark_outbox_id);
    upsert_benchmark_registry_outbox_item(temp.path(), "tenant-a", &item)
        .expect("benchmark registry outbox file writes");

    let error = mark_benchmark_registry_outbox_status_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
            external_receipt_ref: Some("external-registry:tenant-a-submit".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect_err("manual benchmark registry outbox status requires listed central issuer principal");
    assert_eq!(error.0, StatusCode::FORBIDDEN);
    assert_eq!(
        error.1.0.error,
        "benchmark registry outbox status updates require an authorized central issuer principal"
    );

    let outbox = read_all_benchmark_registry_outbox_items(temp.path(), "tenant-a")
        .expect("benchmark registry outbox reads");
    assert_eq!(outbox.len(), 1);
    assert_eq!(
        outbox[0].status,
        StorageTraceBenchmarkRegistryOutboxStatus::Pending
    );
    assert!(outbox[0].external_receipt_ref.is_none());

    let Json(submitted) = mark_benchmark_registry_outbox_status_handler(
        State(state),
        auth_headers("admin-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
            external_receipt_ref: Some("external-registry:tenant-a-submit".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect("listed central issuer principal can mark registry outbox submitted");
    assert_eq!(
        submitted.status,
        StorageTraceBenchmarkRegistryOutboxStatus::Submitted
    );
    assert_eq!(
        submitted.external_receipt_ref.as_deref(),
        Some("external-registry:tenant-a-submit")
    );

    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit reads");
    let status_audit = audit_events
        .iter()
        .find(|event| event.kind == "benchmark_registry_outbox_status")
        .expect("benchmark registry outbox status audit exists");
    let status_reason = status_audit
        .reason
        .as_deref()
        .expect("benchmark registry status audit reason exists");
    assert!(status_reason.contains(&format!("benchmark_outbox_id={benchmark_outbox_id}")));
    assert!(status_reason.contains("status=submitted"));
    assert!(status_reason.contains(&format!(
        "external_receipt_ref_hash={}",
        sha256_prefixed("external-registry:tenant-a-submit")
    )));
    assert!(!status_reason.contains("external-registry:tenant-a-submit"));
}

#[tokio::test]
async fn benchmark_registry_outbox_mark_status_requires_adapter_auth_when_configured() {
    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    Arc::make_mut(&mut state).benchmark_registry_submitter =
        Some(Arc::new(FakeBenchmarkRegistrySubmitter::default()));
    Arc::make_mut(&mut state).benchmark_registry_confirmer =
        Some(Arc::new(FakeBenchmarkRegistryConfirmer::default()));
    Arc::make_mut(&mut state).benchmark_registry_require_adapter_auth = true;

    let pending_outbox_id = Uuid::new_v4();
    let pending_item = pending_benchmark_registry_outbox_item(pending_outbox_id);
    let submitted_outbox_id = Uuid::new_v4();
    let submitted_item = submitted_benchmark_registry_outbox_item(
        submitted_outbox_id,
        StorageTraceBenchmarkRegistryOutboxOperation::Publish,
    );
    upsert_benchmark_registry_outbox_item(temp.path(), "tenant-a", &pending_item)
        .expect("pending benchmark registry outbox file writes");
    upsert_benchmark_registry_outbox_item(temp.path(), "tenant-a", &submitted_item)
        .expect("submitted benchmark registry outbox file writes");

    let submit_error = mark_benchmark_registry_outbox_status_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: pending_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
            external_receipt_ref: Some("external-registry:manual-submit".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect_err("manual submitted status requires adapter bearer auth when configured");
    assert_eq!(submit_error.0, StatusCode::SERVICE_UNAVAILABLE);
    assert!(
        submit_error
            .1
            .0
            .error
            .contains(TRACE_COMMONS_BENCHMARK_REGISTRY_SUBMITTER_BEARER_TOKEN)
    );

    let confirm_error = mark_benchmark_registry_outbox_status_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: submitted_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Confirmed,
            external_receipt_ref: Some("external-registry:manual-confirm".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect_err("manual confirmed status requires adapter bearer auth when configured");
    assert_eq!(confirm_error.0, StatusCode::SERVICE_UNAVAILABLE);
    assert!(
        confirm_error
            .1
            .0
            .error
            .contains(TRACE_COMMONS_BENCHMARK_REGISTRY_CONFIRMATION_BEARER_TOKEN)
    );

    let outbox = read_all_benchmark_registry_outbox_items(temp.path(), "tenant-a")
        .expect("benchmark registry outbox reads");
    assert!(outbox.iter().any(|item| {
        item.benchmark_outbox_id == pending_outbox_id
            && item.status == StorageTraceBenchmarkRegistryOutboxStatus::Pending
            && item.external_receipt_ref.is_none()
    }));
    assert!(outbox.iter().any(|item| {
        item.benchmark_outbox_id == submitted_outbox_id
            && item.status == StorageTraceBenchmarkRegistryOutboxStatus::Submitted
            && item.external_receipt_ref.as_deref() == Some("external-registry:receipt:publish")
    }));

    let Json(failed) = mark_benchmark_registry_outbox_status_handler(
        State(state),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: pending_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Failed,
            external_receipt_ref: None,
            error_detail: Some("bounded registry failure".to_string()),
        }),
    )
    .await
    .expect("manual failed status remains available for recovery evidence");
    assert_eq!(
        failed.status,
        StorageTraceBenchmarkRegistryOutboxStatus::Failed
    );
    assert!(failed.last_error_hash.is_some());
}

#[tokio::test]
async fn benchmark_registry_outbox_mark_status_rejects_invalid_manual_transitions() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());

    let pending_outbox_id = Uuid::new_v4();
    let pending_item = pending_benchmark_registry_outbox_item(pending_outbox_id);
    upsert_benchmark_registry_outbox_item(temp.path(), "tenant-a", &pending_item)
        .expect("pending benchmark registry outbox file writes");

    let confirm_pending_error = mark_benchmark_registry_outbox_status_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: pending_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Confirmed,
            external_receipt_ref: Some("external-registry:tenant-a-confirm".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect_err("manual benchmark registry confirm requires submitted item state");
    assert_eq!(confirm_pending_error.0, StatusCode::CONFLICT);
    assert_eq!(
        confirm_pending_error.1.0.error,
        "manual benchmark registry outbox status update is not valid for the current item state"
    );

    let Json(submitted) = mark_benchmark_registry_outbox_status_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: pending_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
            external_receipt_ref: Some("external-registry:tenant-a-submit".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect("manual submitted status is valid from pending");
    assert_eq!(
        submitted.status,
        StorageTraceBenchmarkRegistryOutboxStatus::Submitted
    );

    let Json(confirmed) = mark_benchmark_registry_outbox_status_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: pending_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Confirmed,
            external_receipt_ref: Some("external-registry:tenant-a-confirm".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect("manual confirmed status is valid from submitted");
    assert_eq!(
        confirmed.status,
        StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
    );

    let downgrade_confirmed_error = mark_benchmark_registry_outbox_status_handler(
        State(state),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxStatusRequest {
            benchmark_outbox_id: pending_outbox_id,
            status: StorageTraceBenchmarkRegistryOutboxStatus::Submitted,
            external_receipt_ref: Some("external-registry:tenant-a-submit-again".to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect_err("manual benchmark registry status cannot downgrade confirmed item");
    assert_eq!(downgrade_confirmed_error.0, StatusCode::CONFLICT);

    let outbox = read_all_benchmark_registry_outbox_items(temp.path(), "tenant-a")
        .expect("benchmark registry outbox reads");
    assert_eq!(outbox.len(), 1);
    assert_eq!(
        outbox[0].status,
        StorageTraceBenchmarkRegistryOutboxStatus::Confirmed
    );
    assert_eq!(
        outbox[0].external_receipt_ref.as_deref(),
        Some("external-registry:tenant-a-confirm")
    );
}

