#[tokio::test]
async fn ranking_calibration_dataset_registry_rejects_manifest_rewrites() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());

    let Json(record) = ranking_calibration_dataset_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingCalibrationDatasetRequest {
            calibration_dataset_hash: sha256_prefixed("ranking-calibration-immutable-v1"),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: "trace-credit-policy-v1".to_string(),
            source_manifest_hash: sha256_prefixed("ranking-calibration-immutable-manifest-v1"),
            source_count: 128,
            label_source_count: 3,
            label_actor_count: 3,
            status: StorageTraceRankingCalibrationDatasetStatus::Candidate,
        }),
    )
    .await
    .expect("admin can register initial calibration dataset");

    let Json(status_update) = ranking_calibration_dataset_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingCalibrationDatasetRequest {
            calibration_dataset_hash: record.calibration_dataset_hash.clone(),
            target_use: record.target_use,
            policy_version: record.policy_version.clone(),
            source_manifest_hash: record.source_manifest_hash.clone(),
            source_count: record.source_count,
            label_source_count: record.label_source_count,
            label_actor_count: record.label_actor_count,
            status: StorageTraceRankingCalibrationDatasetStatus::Active,
        }),
    )
    .await
    .expect("admin can append lifecycle-only calibration dataset status update");
    assert_eq!(
        status_update.status,
        StorageTraceRankingCalibrationDatasetStatus::Active
    );

    let rewrite = ranking_calibration_dataset_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingCalibrationDatasetRequest {
            calibration_dataset_hash: record.calibration_dataset_hash.clone(),
            target_use: record.target_use,
            policy_version: record.policy_version.clone(),
            source_manifest_hash: sha256_prefixed("ranking-calibration-immutable-manifest-v2"),
            source_count: record.source_count,
            label_source_count: record.label_source_count,
            label_actor_count: record.label_actor_count,
            status: StorageTraceRankingCalibrationDatasetStatus::Active,
        }),
    )
    .await
    .expect_err("calibration dataset manifest fields are immutable for a registry key");
    assert_eq!(rewrite.0, StatusCode::CONFLICT);

    let Json(records) =
        ranking_calibration_datasets_handler(State(state), auth_headers("admin-token-a"))
            .await
            .expect("admin can list latest calibration dataset registry row");
    assert_eq!(records.len(), 1);
    assert_eq!(records[0].source_manifest_hash, record.source_manifest_hash);
    assert_eq!(
        records[0].status,
        StorageTraceRankingCalibrationDatasetStatus::Active
    );
}

#[tokio::test]
async fn ranking_calibration_dataset_append_rejects_manifest_rewrites() {
    let temp = tempfile::tempdir().expect("temp dir");
    let tenant_id = "tenant-a";
    let initial = TraceRankingCalibrationDatasetRecord {
        tenant_id: tenant_id.to_string(),
        tenant_storage_ref: tenant_storage_ref(tenant_id),
        calibration_dataset_hash: sha256_prefixed("ranking-calibration-storage-v1"),
        target_use: TraceAllowedUse::RankingModelTraining,
        policy_version: "trace-credit-policy-v1".to_string(),
        source_manifest_hash: sha256_prefixed("ranking-calibration-storage-manifest-v1"),
        source_count: 128,
        label_source_count: 3,
        label_actor_count: 3,
        status: StorageTraceRankingCalibrationDatasetStatus::Candidate,
        actor_principal_ref: "principal_sha256:ranker-admin".to_string(),
        created_at: Utc::now(),
    };

    append_ranking_calibration_dataset(temp.path(), tenant_id, &initial)
        .expect("initial calibration dataset registry append succeeds");

    let mut status_update = initial.clone();
    status_update.status = StorageTraceRankingCalibrationDatasetStatus::Active;
    status_update.created_at = Utc::now();
    append_ranking_calibration_dataset(temp.path(), tenant_id, &status_update)
        .expect("status-only calibration dataset append succeeds");

    let mut rewrite = status_update.clone();
    rewrite.source_manifest_hash = sha256_prefixed("ranking-calibration-storage-manifest-v2");
    let error = append_ranking_calibration_dataset(temp.path(), tenant_id, &rewrite)
        .expect_err("storage append rejects calibration dataset manifest rewrite");
    assert!(error.to_string().contains("immutable"));

    let records = read_all_ranking_calibration_datasets(temp.path(), tenant_id)
        .expect("calibration dataset registry remains readable");
    assert_eq!(records.len(), 1);
    assert_eq!(
        records[0].source_manifest_hash,
        initial.source_manifest_hash
    );
    assert_eq!(
        records[0].status,
        StorageTraceRankingCalibrationDatasetStatus::Active
    );
}

