#[tokio::test]
async fn credit_cycle_worker_marks_failed_when_later_step_fails() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());

    let error = credit_cycle_worker_run_handler(
        State(state),
        auth_headers("utility-worker-token-a"),
        Json(TraceCreditCycleWorkerRunRequest {
            dry_run: false,
            submit_near_outbox: true,
            confirm_near_outbox: false,
            target_use: TraceAllowedUse::RankingModelTraining,
            model_version: "trace-ranker-missing-model-v1".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "cycle should fail during near outbox".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            calibration_limit: Some(10),
            model_promotion_limit: Some(10),
            prediction_credit_limit: Some(10),
            credit_settlement_limit: Some(10),
            near_outbox_limit: Some(10),
            near_outbox_confirm_limit: Some(10),
            min_label_count: Some(1),
            confidence_threshold: Some(0.5),
            max_average_absolute_error_micros: Some(100_000),
            allow_at_risk_models: false,
        }),
    )
    .await
    .expect_err("unconfigured live near submitter fails the credit cycle");

    assert_eq!(error.0, StatusCode::SERVICE_UNAVAILABLE);
    let worker_runs =
        read_all_ranking_worker_runs(temp.path(), "tenant-a").expect("worker runs read");
    let credit_cycle_runs = worker_runs
        .iter()
        .filter(|run| run.run_kind == TraceRankingWorkerRunKind::CreditCycle)
        .collect::<Vec<_>>();
    assert_eq!(credit_cycle_runs.len(), 1);
    assert_eq!(
        credit_cycle_runs[0].status,
        TraceRankingWorkerRunStatus::Failed
    );
    assert_eq!(credit_cycle_runs[0].checked_count, 5);
    assert!(credit_cycle_runs[0].completed_at.is_some());
    assert!(
        credit_cycle_runs[0]
            .last_error_hash
            .as_deref()
            .is_some_and(|hash| hash.starts_with("sha256:"))
    );
    let raw_worker_runs =
        std::fs::read_to_string(ranking_worker_runs_path(temp.path(), "tenant-a"))
            .expect("raw worker runs read");
    assert!(!raw_worker_runs.contains("cycle should fail during near outbox"));
    assert!(
        read_all_credit_events(temp.path(), "tenant-a")
            .expect("credit ledger reads")
            .is_empty()
    );
    assert!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-a")
            .expect("NEAR outbox reads")
            .is_empty()
    );
}

#[tokio::test]
async fn ranking_model_promotion_worker_run_promotes_calibrated_candidates_only() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let Json(candidate) = ranking_model_version_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingModelVersionRequest {
            model_version: "trace-ranker-worker-promote-v1".to_string(),
            feature_schema_version: "ranking-features-worker-promote-v1".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            status: StorageTraceRankingModelStatus::Candidate,
            training_dataset_hash: sha256_prefixed("ranking-training-worker-promote"),
            calibration_dataset_hash: sha256_prefixed("ranking-calibration-worker-promote"),
            model_artifact_hash: sha256_prefixed("ranking-model-artifact-worker-promote"),
        }),
    )
    .await
    .expect("admin can stage promotable candidate");
    let Json(blocked_candidate) = ranking_model_version_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingModelVersionRequest {
            model_version: "trace-ranker-worker-promote-blocked-v1".to_string(),
            feature_schema_version: "ranking-features-worker-promote-blocked-v1".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            status: StorageTraceRankingModelStatus::Candidate,
            training_dataset_hash: sha256_prefixed("ranking-training-worker-promote-blocked"),
            calibration_dataset_hash: sha256_prefixed("ranking-calibration-worker-promote-blocked"),
            model_artifact_hash: sha256_prefixed("ranking-model-artifact-worker-promote-blocked"),
        }),
    )
    .await
    .expect("admin can stage blocked candidate");

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::RankingTraining];
    envelope.trace_card.consent_scope = ConsentScope::RankingTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::RankingModelTraining];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("ranking submission succeeds");
    let Json(feature) = ranking_feature_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingFeatureRequest {
            submission_id,
            target_use: TraceAllowedUse::RankingModelTraining,
            feature_schema_version: candidate.feature_schema_version.clone(),
            feature_vector_hash: sha256_prefixed("ranking-feature-worker-promote"),
            feature_names_hash: sha256_prefixed("ranking-feature-names-worker-promote"),
            source_feature_hash: sha256_prefixed("ranking-source-feature-worker-promote"),
            duplicate_score: Some(0.05),
            novelty_score: Some(0.91),
            privacy_risk_score: Some(0.02),
            quality_score: Some(0.88),
            coverage_tags: vec!["tool:terminal".to_string()],
        }),
    )
    .await
    .expect("utility worker can write ranking feature");
    let Json(_) = ranking_prediction_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingPredictionRequest {
            submission_id,
            target_use: TraceAllowedUse::RankingModelTraining,
            model_version: candidate.model_version.clone(),
            feature_schema_version: candidate.feature_schema_version.clone(),
            prediction_policy_version: candidate.policy_version.clone(),
            feature_vector_hash: feature.feature_vector_hash,
            predicted_utility_micros: 1_250_000,
            uncertainty_micros: 250_000,
            confidence: 0.9,
            risk_penalty_micros: 0,
            novelty_bonus_micros: 0,
            explanation_codes: vec!["ranking_pair_utility".to_string()],
        }),
    )
    .await
    .expect("utility worker can write ranking prediction");
    let Json(_) = ranking_label_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingLabelRequest {
            submission_id,
            target_use: TraceAllowedUse::RankingModelTraining,
            label_source: StorageTraceRankingLabelSource::FrontierLab,
            utility_category: StorageTraceRankingUtilityCategory::RankingTraining,
            label_outcome: StorageTraceRankingLabelOutcome::Useful,
            utility_delta_micros: 1_250_000,
            evidence_hash: sha256_prefixed("ranking-frontier-evidence-worker-promote"),
            external_ref: "private-ranking-worker-promote".to_string(),
        }),
    )
    .await
    .expect("utility worker can write ranking label");
    let Json(calibration) = ranking_calibration_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingCalibrationRunRequest {
            model_version: candidate.model_version.clone(),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: candidate.policy_version.clone(),
            evaluation_dataset_hash: candidate.calibration_dataset_hash.clone(),
            min_label_count: Some(1),
            confidence_threshold: Some(0.5),
            max_average_absolute_error_micros: Some(100_000),
        }),
    )
    .await
    .expect("utility worker can persist promotable calibration");
    assert!(calibration.promotable);

    let admin_only_error = ranking_model_promotion_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingModelPromotionRequest {
            dry_run: false,
            model_version: candidate.model_version.clone(),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: candidate.policy_version.clone(),
            reason: "utility worker should use scoped run route".to_string(),
        }),
    )
    .await
    .expect_err("utility worker cannot call generic admin promotion route");
    assert_eq!(admin_only_error.0, StatusCode::FORBIDDEN);

    let Json(run) = ranking_model_promotion_worker_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingModelPromotionRunRequest {
            dry_run: false,
            target_use: TraceAllowedUse::RankingModelTraining,
            reason: "scheduled calibrated candidate promotion".to_string(),
            limit: Some(10),
            model_version: None,
            policy_version: Some("trace-credit-policy-v1".to_string()),
        }),
    )
    .await
    .expect("utility worker can run scoped model promotion automation");
    assert_eq!(run.checked_count, 2);
    assert_eq!(run.promoted_count, 1);
    assert_eq!(run.skipped_ineligible_count, 1);
    assert_eq!(run.pending_after_count, 1);
    assert_eq!(run.promotions.len(), 1);
    assert_eq!(run.promotions[0].model_version, candidate.model_version);
    assert_eq!(
        run.promotions[0].calibration_run_id,
        calibration.calibration_run_id
    );
    let Json(worker_runs) =
        ranking_worker_runs_handler(State(state.clone()), auth_headers("admin-token-a"))
            .await
            .expect("admin can list ranking worker run ledger");
    assert_eq!(worker_runs.len(), 1);
    assert_eq!(
        worker_runs[0].ranking_worker_run_id,
        run.ranking_worker_run_id
    );
    assert_eq!(
        worker_runs[0].run_kind,
        TraceRankingWorkerRunKind::ModelPromotion
    );
    assert_eq!(
        worker_runs[0].status,
        TraceRankingWorkerRunStatus::Completed
    );
    assert!(!worker_runs[0].dry_run);
    assert_eq!(worker_runs[0].limit, 10);
    assert_eq!(
        worker_runs[0].target_use,
        Some(TraceAllowedUse::RankingModelTraining)
    );
    assert_eq!(
        worker_runs[0].policy_version.as_deref(),
        Some("trace-credit-policy-v1")
    );
    assert_eq!(worker_runs[0].checked_count, run.checked_count);
    assert_eq!(worker_runs[0].succeeded_count, run.promoted_count);
    assert_eq!(
        worker_runs[0].skipped_ineligible_count,
        run.skipped_ineligible_count
    );
    assert_eq!(worker_runs[0].pending_after_count, run.pending_after_count);
    assert_eq!(worker_runs[0].reason_hash, run.reason_hash);
    assert_eq!(
        worker_runs[0].result_refs,
        vec![format!("ranking_model:{}", candidate.model_version)]
    );
    assert!(
            worker_runs[0]
                .reason_counts
                .contains_key("ranking model promotion requires a calibration run for the requested model, target use, and policy")
        );
    let worker_runs_json = serde_json::to_string(&worker_runs).expect("worker runs serialize");
    assert!(!worker_runs_json.contains("scheduled calibrated candidate promotion"));
    let raw_worker_runs: Vec<TraceRankingWorkerRunRecord> = read_jsonl_records(
        &ranking_worker_runs_path(temp.path(), "tenant-a"),
        "ranking worker run",
    )
    .expect("raw worker runs read");
    assert_eq!(raw_worker_runs.len(), 2);
    assert_eq!(
        raw_worker_runs[0].ranking_worker_run_id,
        run.ranking_worker_run_id
    );
    assert_eq!(
        raw_worker_runs[0].status,
        TraceRankingWorkerRunStatus::Running
    );
    assert_eq!(
        raw_worker_runs[1].ranking_worker_run_id,
        run.ranking_worker_run_id
    );
    assert_eq!(
        raw_worker_runs[1].status,
        TraceRankingWorkerRunStatus::Completed
    );

    let model_versions =
        read_all_ranking_model_versions(temp.path(), "tenant-a").expect("model versions read");
    let latest_promoted =
        latest_ranking_model_version(&model_versions, &candidate.model_version).unwrap();
    assert_eq!(
        latest_promoted.status,
        StorageTraceRankingModelStatus::Active
    );
    let latest_blocked =
        latest_ranking_model_version(&model_versions, &blocked_candidate.model_version).unwrap();
    assert_eq!(
        latest_blocked.status,
        StorageTraceRankingModelStatus::Candidate
    );
}

