#[tokio::test]
async fn credit_control_plane_dual_writes_and_reads_postgres_when_enabled() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("submission mirrors to DB");

    let Json(event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 1.5,
            reason: Some("frontier training utility".to_string()),
            external_ref: Some("frontier:db-settlement".to_string()),
        }),
    )
    .await
    .expect("credit event mirrors to DB");

    let mut other_envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut other_envelope);
    other_envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    other_envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    other_envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let other_submission_id = other_envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-b"),
        submit_body(other_envelope),
    )
    .await
    .expect("other tenant submission mirrors to DB");
    let Json(other_event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-b"),
        AxumPath(other_submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 9.0,
            reason: Some("tenant B frontier training utility".to_string()),
            external_ref: Some("frontier:tenant-b-db-settlement".to_string()),
        }),
    )
    .await
    .expect("other tenant credit event mirrors to DB");

    let tenant_b_hold_error = credit_hold_handler(
        State(state.clone()),
        auth_headers("admin-token-b"),
        Json(TraceCreditHoldRequest {
            credit_account_ref: event.auth_principal_ref.clone(),
            reason: StorageTraceCreditHoldReason::AttestationDispute,
            reason_detail: "tenant-b cannot hold tenant-a DB ledger account".to_string(),
        }),
    )
    .await
    .expect_err("tenant-b admin cannot hold tenant-a DB-backed ledger account");
    assert_eq!(tenant_b_hold_error.0, StatusCode::NOT_FOUND);

    let Json(db_hold) = credit_hold_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditHoldRequest {
            credit_account_ref: event.auth_principal_ref.clone(),
            reason: StorageTraceCreditHoldReason::AttestationDispute,
            reason_detail: "DB-backed hold placement".to_string(),
        }),
    )
    .await
    .expect("tenant-a admin can place DB-backed hold");
    assert_eq!(db_hold.credit_account_ref, event.auth_principal_ref);

    let tenant_a_db_holds = backend
        .list_trace_credit_holds("tenant-a")
        .await
        .expect("tenant-a DB holds read after placement");
    assert_eq!(tenant_a_db_holds.len(), 1);
    assert_eq!(tenant_a_db_holds[0].hold_id, db_hold.hold_id);
    assert!(tenant_a_db_holds[0].released_at.is_none());
    assert!(
        backend
            .list_trace_credit_holds("tenant-b")
            .await
            .expect("tenant-b DB holds read after failed placement")
            .is_empty()
    );

    let Json(released_hold) = credit_hold_release_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        AxumPath(db_hold.hold_id),
        Json(TraceCreditHoldReleaseRequest {
            reason_detail: "DB-backed hold release".to_string(),
        }),
    )
    .await
    .expect("tenant-a admin can release DB-backed hold");
    assert_eq!(released_hold.hold_id, db_hold.hold_id);
    assert!(released_hold.released_at.is_some());

    let tenant_a_db_holds = backend
        .list_trace_credit_holds("tenant-a")
        .await
        .expect("tenant-a DB holds read after release");
    assert_eq!(tenant_a_db_holds.len(), 1);
    assert_eq!(tenant_a_db_holds[0].hold_id, db_hold.hold_id);
    assert!(tenant_a_db_holds[0].released_at.is_some());

    let tenant_a_audit_events = backend
        .list_trace_audit_events("tenant-a")
        .await
        .expect("tenant-a DB audit events read after hold release");
    let hold_audit = tenant_a_audit_events
        .iter()
        .find(|event| {
            event.action == StorageTraceAuditAction::CreditMutate
                && matches!(
                    &event.metadata,
                    StorageTraceAuditSafeMetadata::CreditHold {
                        action: StorageTraceCreditHoldAuditAction::Placed,
                        hold_id,
                        credit_account_hash,
                        hold_reason: StorageTraceCreditHoldReason::AttestationDispute,
                        reason_hash,
                    } if *hold_id == db_hold.hold_id
                        && credit_account_hash == &db_hold.credit_account_hash
                        && reason_hash == &db_hold.reason_hash
                )
        })
        .expect("DB hold placement audit metadata is typed");
    let hold_audit_metadata_json =
        serde_json::to_string(&hold_audit.metadata).expect("hold audit metadata serializes");
    assert!(!hold_audit_metadata_json.contains("DB-backed hold placement"));
    assert!(!hold_audit_metadata_json.contains(&event.auth_principal_ref));

    let release_reason_hash = sha256_prefixed("DB-backed hold release");
    let release_audit = tenant_a_audit_events
        .iter()
        .find(|event| {
            event.action == StorageTraceAuditAction::CreditMutate
                && matches!(
                    &event.metadata,
                    StorageTraceAuditSafeMetadata::CreditHold {
                        action: StorageTraceCreditHoldAuditAction::Released,
                        hold_id,
                        credit_account_hash,
                        hold_reason: StorageTraceCreditHoldReason::AttestationDispute,
                        reason_hash,
                    } if *hold_id == db_hold.hold_id
                        && credit_account_hash == &db_hold.credit_account_hash
                        && reason_hash == &release_reason_hash
                )
        })
        .expect("DB hold release audit metadata is typed");
    let release_audit_metadata_json = serde_json::to_string(&release_audit.metadata)
        .expect("hold release audit metadata serializes");
    assert!(!release_audit_metadata_json.contains("DB-backed hold release"));
    assert!(!release_audit_metadata_json.contains(&event.auth_principal_ref));

    let Json(finalized) = credit_settlement_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "DB-backed settlement".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
        }),
    )
    .await
    .expect("settlement mirrors to DB");
    assert_eq!(finalized.settled_source_event_count, 1);

    let db_batches = backend
        .list_trace_credit_settlement_batches("tenant-a")
        .await
        .expect("DB settlement batches read");
    assert_eq!(db_batches.len(), 1);
    assert_eq!(db_batches[0].source_credit_event_ids, vec![event.event_id]);
    assert!(
        !db_batches[0]
            .source_credit_event_ids
            .contains(&other_event.event_id)
    );

    let Json(listed_batches) =
        credit_settlements_handler(State(state.clone()), auth_headers("admin-token-a"))
            .await
            .expect("admin settlement list reads from DB");
    assert_eq!(listed_batches.len(), 1);
    assert_eq!(
        listed_batches[0].settlement_batch_id,
        finalized.settlement_batch_id
    );

    let Json(risk_summary) = credit_risk_summary_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Query(TraceCreditRiskSummaryQuery::default()),
    )
    .await
    .expect("admin tenant A risk summary reads from DB without tenant B credit");
    assert_eq!(risk_summary.tenant_id, "tenant-a");
    assert_eq!(risk_summary.account_count, 0);
    assert_eq!(risk_summary.pending_credit_micros, 0);
    assert_eq!(risk_summary.held_credit_micros, 0);

    let Json(outbox) =
        near_credit_outbox_handler(State(state.clone()), auth_headers("admin-token-a"))
            .await
            .expect("admin NEAR outbox reads from DB");
    assert_eq!(outbox.len(), 1);
    let Json(submitted) = mark_near_credit_outbox_status_handler(
        State(state),
        auth_headers("utility-worker-token-a"),
        Json(TraceNearCreditOutboxStatusRequest {
            near_outbox_id: outbox[0].near_outbox_id,
            status: StorageTraceCreditSettlementNearStatus::Submitted,
            near_transaction_hash: Some(TEST_NEAR_TX_HASH_5.to_string()),
            error_detail: None,
        }),
    )
    .await
    .expect("NEAR outbox status mirrors to DB");
    assert_eq!(
        submitted.status,
        StorageTraceCreditSettlementNearStatus::Submitted
    );

    let db_outbox = backend
        .list_trace_near_credit_outbox_items("tenant-a")
        .await
        .expect("DB NEAR outbox reads");
    assert_eq!(
        db_outbox[0].status,
        StorageTraceCreditSettlementNearStatus::Submitted
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;
}

#[test]
fn near_credit_reversal_outbox_uses_reverse_method_and_single_event_amount() {
    let settlement_batch_id = Uuid::new_v4();
    let credit_event_id = Uuid::new_v4();
    let other_credit_event_id = Uuid::new_v4();
    let submission_id = Uuid::new_v4();
    let line_source_hash = source_credit_event_ids_hash(
        "trace-credit-policy-v1",
        &[credit_event_id, other_credit_event_id],
    );
    let batch = TraceCreditSettlementBatchRecord {
        settlement_batch_id,
        tenant_id: "tenant-a".to_string(),
        tenant_storage_ref: tenant_storage_ref("tenant-a"),
        policy_version: "trace-credit-policy-v1".to_string(),
        status: StorageTraceCreditSettlementBatchStatus::Finalized,
        reason_hash: sha256_prefixed("settled before revocation"),
        issuer_approval_evidence_hash: None,
        source_credit_event_ids: vec![credit_event_id, other_credit_event_id],
        source_submission_ids: vec![submission_id, Uuid::new_v4()],
        source_list_hash: line_source_hash.clone(),
        settled_credit_points: 3.0,
        settled_credit_micros: 3_000_000,
        line_items: Vec::new(),
        near_contract_id: Some("trace-credits.testnet".to_string()),
        ranking_model_version: None,
        ranking_target_use: None,
        ranking_calibration_run_id: None,
        ranking_calibration_report_hash: None,
        ranking_calibration_joined_evidence_hash: None,
        ranking_credit_events_excluded_count: 0,
        ranking_credit_events_excluded_reason_counts: BTreeMap::new(),
        actor_principal_ref: static_token_principal_ref("admin-token-a"),
        created_at: Utc::now(),
    };
    let line_item = StorageTraceCreditAccountSettlementLineItem {
        credit_account_ref: static_token_principal_ref("token-a"),
        credit_account_hash: sha256_prefixed(&static_token_principal_ref("token-a")),
        settled_credit_delta_micros: 3_000_000,
        source_credit_event_ids: vec![credit_event_id, other_credit_event_id],
        source_submission_ids: batch.source_submission_ids.clone(),
        source_list_hash: line_source_hash,
        near_status: StorageTraceCreditSettlementNearStatus::Pending,
        near_outbox_id: Some(Uuid::new_v4()),
        near_payout_hold_reason: None,
    };
    let source_event = StorageTraceCreditEventRecord {
        credit_event_id,
        tenant_id: "tenant-a".to_string(),
        submission_id,
        trace_id: Uuid::new_v4(),
        credit_account_ref: static_token_principal_ref("token-a"),
        event_type: StorageTraceCreditEventType::TrainingUtility,
        points_delta: "1.2500".to_string(),
        reason: "frontier training utility".to_string(),
        external_ref: Some("frontier:revoked-credit".to_string()),
        actor_principal_ref: static_token_principal_ref("review-token-a"),
        actor_role: "reviewer".to_string(),
        settlement_state: StorageTraceCreditSettlementState::Final,
        occurred_at: Utc::now(),
    };
    let reversal_outbox_id = Uuid::new_v4();

    let outbox = near_credit_reversal_outbox_item_from_settled_credit_event(
        "tenant-a",
        &batch,
        &line_item,
        &source_event,
        "trace-credits.testnet",
        reversal_outbox_id,
    )
    .expect("reverse outbox item builds");

    assert_eq!(outbox.near_outbox_id, reversal_outbox_id);
    assert_eq!(outbox.near_call.method_name, "reverse_credit_receipt");
    assert_eq!(outbox.near_call.contract_id, "trace-credits.testnet");
    assert_eq!(
        outbox.near_call.args["amount_micros"],
        serde_json::json!(1_250_000)
    );
    assert_eq!(
        outbox.near_call.args["source_list_hash"],
        serde_json::json!(source_credit_event_ids_hash(
            "trace-credit-policy-v1",
            &[credit_event_id],
        ))
    );
    assert_ne!(
        outbox.near_call.args["source_list_hash"],
        serde_json::json!(line_item.source_list_hash)
    );
}

#[test]
fn novelty_utility_credit_is_not_settlement_eligible() {
    // Novelty is cheaply fabricated. The graded-credit design requires
    // dedup, caps, reputation and delayed settlement before novelty can
    // carry settlement-eligible value; none of those gate emission yet.
    // Until they do, novelty credit accrues as a signal but must never
    // reach on-chain issuance.
    assert!(!trace_credit_event_type_is_settlement_eligible(
        TraceCreditLedgerEventType::NoveltyUtility
    ));
}

#[test]
fn settlement_eligible_event_types_are_the_reviewed_set() {
    // Pins the whole set so adding a new event type is a deliberate
    // decision rather than something that inherits eligibility.
    for event_type in [
        TraceCreditLedgerEventType::BenchmarkConversion,
        TraceCreditLedgerEventType::RegressionCatch,
        TraceCreditLedgerEventType::TrainingUtility,
        TraceCreditLedgerEventType::RankingUtility,
    ] {
        assert!(
            trace_credit_event_type_is_settlement_eligible(event_type),
            "{event_type:?} should stay settlement-eligible"
        );
    }
    for event_type in [
        TraceCreditLedgerEventType::NoveltyUtility,
        TraceCreditLedgerEventType::ReviewerBonus,
        TraceCreditLedgerEventType::AbusePenalty,
    ] {
        assert!(
            !trace_credit_event_type_is_settlement_eligible(event_type),
            "{event_type:?} should not be settlement-eligible"
        );
    }
}

#[test]
fn novelty_utility_credit_points_delta_defaults_to_zero() {
    // Emission pays a flat delta without consulting the credit_quality
    // and contributor_cap signals that are computed and stored on every
    // gate decision. Defaulting to zero keeps the accounting path warm
    // without issuing value the quality signals never gated.
    assert_eq!(DEFAULT_NOVELTY_UTILITY_CREDIT_POINTS_DELTA, 0.0);
}

#[test]
fn revocation_credit_reversal_supports_ranking_utility_credit_events() {
    assert_eq!(
        trace_credit_event_type_from_storage(StorageTraceCreditEventType::RankingUtility),
        Some(TraceCreditLedgerEventType::RankingUtility)
    );
    assert!(trace_credit_event_type_is_settlement_eligible(
        TraceCreditLedgerEventType::RankingUtility
    ));
    assert_eq!(
        utility_credit_required_allowed_uses(TraceCreditLedgerEventType::RankingUtility),
        &[TraceAllowedUse::RankingModelTraining]
    );
}

#[tokio::test]
async fn revocation_leaves_settled_credit_and_enqueues_no_near_reverse_receipt() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("submission mirrors to DB");

    let Json(event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 1.25,
            reason: Some("frontier training utility to reverse".to_string()),
            external_ref: Some("frontier:revocation-near-reversal".to_string()),
        }),
    )
    .await
    .expect("credit event mirrors to DB");

    let Json(finalized) = credit_settlement_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "settlement before revocation".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
        }),
    )
    .await
    .expect("settlement mirrors to DB");
    assert_eq!(finalized.near_outbox_item_count, 1);

    let revoke_status = revoke_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        AxumPath(submission_id),
    )
    .await
    .expect("contributor can revoke settled trace");
    assert_eq!(revoke_status, StatusCode::NO_CONTENT);

    // Settled credit is NOT clawed back when the contributor withdraws the
    // trace. Revocation removes the trace from the commons and deletes its
    // content; it does not reach back onto the chain. No reversal propagation
    // item is enqueued, so the worker has nothing to reverse, no negative
    // credit event appears, and no `reverse_credit_receipt` NEAR outbox row is
    // written.
    let propagation_items = backend
        .list_trace_revocation_propagation_items("tenant-a", submission_id)
        .await
        .expect("revocation propagation items read");
    assert!(
        propagation_items.iter().all(|item| {
            item.action != StorageTraceRevocationPropagationAction::ReverseCreditSettlement
        }),
        "revocation must not enqueue a settled-credit reversal item"
    );

    let Json(response) = revocation_propagation_worker_handler(
        State(state.clone()),
        auth_headers("revocation-worker-token-a"),
        Json(TraceRevocationPropagationWorkerRequest {
            purpose: Some("drain_revocation_propagation_without_clawback".to_string()),
            dry_run: false,
            limit: 10,
        }),
    )
    .await
    .expect("revocation worker drains remaining propagation items");
    assert_eq!(response.failed, 0);

    let db_credit_events = backend
        .list_trace_credit_events("tenant-a")
        .await
        .expect("DB credit events read");
    assert!(
        db_credit_events.iter().all(|record| {
            record.external_ref.as_deref()
                != Some(&format!("revocation_credit_reversal:{}", event.event_id))
        }),
        "revocation must not mirror a reversal credit event"
    );
    let settled_event = db_credit_events
        .iter()
        .find(|record| record.credit_event_id == event.event_id)
        .expect("the settled credit event survives revocation");
    assert_eq!(
        settled_event.settlement_state,
        StorageTraceCreditSettlementState::Final
    );

    let db_outbox = backend
        .list_trace_near_credit_outbox_items("tenant-a")
        .await
        .expect("DB NEAR outbox reads")
        .into_iter()
        .map(near_credit_outbox_item_from_storage)
        .collect::<anyhow::Result<Vec<_>>>()
        .expect("DB NEAR outbox records convert");
    assert!(
        db_outbox
            .iter()
            .any(|item| item.near_call.method_name == "settle_credit_receipt")
    );
    assert!(
        db_outbox
            .iter()
            .all(|item| item.near_call.method_name != "reverse_credit_receipt"),
        "revocation must not enqueue a NEAR reverse receipt"
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

