#[test]
fn rollout_smoke_latest_evidence_uses_recorded_at_not_input_order() {
    let newer_passed = TraceRolloutSmokeEvidenceResponse {
        event_id: Uuid::new_v4(),
        tenant_id: "tenant-a".to_string(),
        tenant_storage_ref: tenant_storage_ref("tenant-a"),
        check_name: "audit_reads".to_string(),
        status: TraceRolloutSmokeEvidenceStatus::Passed,
        evidence_hash: sha256_prefixed("newer audit reads passed"),
        evidence_ref_hash: None,
        actor_principal_ref: static_token_principal_ref("admin-token-a"),
        recorded_at: Utc::now(),
    };
    let older_failed = TraceRolloutSmokeEvidenceResponse {
        event_id: Uuid::new_v4(),
        tenant_id: "tenant-a".to_string(),
        tenant_storage_ref: tenant_storage_ref("tenant-a"),
        check_name: "audit_reads".to_string(),
        status: TraceRolloutSmokeEvidenceStatus::Failed,
        evidence_hash: sha256_prefixed("older audit reads failed"),
        evidence_ref_hash: None,
        actor_principal_ref: static_token_principal_ref("admin-token-a"),
        recorded_at: newer_passed.recorded_at - Duration::minutes(10),
    };
    let out_of_order_evidence = vec![newer_passed.clone(), older_failed];

    let latest = latest_rollout_smoke_evidence_by_check(out_of_order_evidence.clone());
    assert_eq!(latest.len(), 1);
    assert_eq!(latest[0].status, TraceRolloutSmokeEvidenceStatus::Passed);
    assert_eq!(latest[0].evidence_hash, newer_passed.evidence_hash);

    let summary = TraceOperationalRolloutSmokeSummary::from_promotion_gates_and_evidence(
        &TraceOperationalPromotionGateSummary {
            ready: true,
            ..TraceOperationalPromotionGateSummary::default()
        },
        &out_of_order_evidence,
        Utc::now(),
        true,
    );
    assert_eq!(summary.passed_evidence_checks, vec!["audit_reads"]);
    assert!(summary.failed_evidence_checks.is_empty());
    assert!(
        !summary
            .missing_evidence_checks
            .contains(&"audit_reads".to_string())
    );
}

#[test]
fn rollout_smoke_summary_blocks_stale_passed_evidence() {
    let generated_at = Utc::now();
    let old_passed_evidence = TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS
        .iter()
        .map(|check_name| TraceRolloutSmokeEvidenceResponse {
            event_id: Uuid::new_v4(),
            tenant_id: "tenant-a".to_string(),
            tenant_storage_ref: tenant_storage_ref("tenant-a"),
            check_name: (*check_name).to_string(),
            status: TraceRolloutSmokeEvidenceStatus::Passed,
            evidence_hash: sha256_prefixed(&format!("{check_name} stale rehearsal")),
            evidence_ref_hash: None,
            actor_principal_ref: static_token_principal_ref("admin-token-a"),
            recorded_at: generated_at - Duration::hours(25),
        })
        .collect::<Vec<_>>();

    let summary = TraceOperationalRolloutSmokeSummary::from_promotion_gates_and_evidence(
        &TraceOperationalPromotionGateSummary {
            ready: true,
            ..TraceOperationalPromotionGateSummary::default()
        },
        &old_passed_evidence,
        generated_at,
        // Every check in the catalogue, including the conditional one, so
        // the counts below are over the full set.
        true,
    );

    assert!(!summary.ready);
    assert_eq!(summary.evidence_status, "stale_rehearsal_evidence");
    assert_eq!(
        summary.stale_evidence_count,
        TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS.len()
    );
    assert_eq!(summary.missing_evidence_count, 0);
    assert_eq!(summary.passed_evidence_count, 0);
    assert!(summary.blocker_reasons.contains(&format!(
        "smoke_rehearsal_evidence_stale={}",
        TRACE_OPERATIONAL_ROLLOUT_SMOKE_REQUIRED_CHECKS.len()
    )));
}

#[tokio::test]
async fn admin_rollout_smoke_evidence_list_can_return_latest_per_check() {
    use axum::body::Body;
    use tower::ServiceExt;

    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    for (status, marker) in [
        ("failed", "audit reads smoke rehearsal failed first"),
        ("passed", "audit reads smoke rehearsal passed later"),
    ] {
        let evidence_body = serde_json::json!({
            "check_name": "audit_reads",
            "status": status,
            "evidence_hash": sha256_prefixed(marker),
            "evidence_ref": format!("runbook://trace-commons/smoke/audit-reads/{status}")
        });
        let append_response = app(state.clone())
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/admin/rollout-smoke/evidence")
                    .header(AUTHORIZATION, "Bearer admin-token-a")
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(evidence_body.to_string()))
                    .expect("request builds"),
            )
            .await
            .expect("append response");
        assert_eq!(append_response.status(), StatusCode::OK);
    }

    let latest_response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("GET")
                .uri("/v1/admin/rollout-smoke/evidence?latest_only=true")
                .header(AUTHORIZATION, "Bearer admin-token-a")
                .body(Body::empty())
                .expect("request builds"),
        )
        .await
        .expect("latest response");
    assert_eq!(latest_response.status(), StatusCode::OK);
    let body = axum::body::to_bytes(latest_response.into_body(), 8192)
        .await
        .expect("body reads");
    let evidence: Vec<serde_json::Value> =
        serde_json::from_slice(&body).expect("evidence list parses");
    assert_eq!(evidence.len(), 1);
    assert_eq!(evidence[0]["check_name"], serde_json::json!("audit_reads"));
    assert_eq!(evidence[0]["status"], serde_json::json!("passed"));
}

#[tokio::test]
async fn admin_rollout_smoke_preflight_returns_latest_hash_only_evidence() {
    use axum::body::Body;
    use tower::ServiceExt;

    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());

    let contributor_response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("GET")
                .uri("/v1/admin/rollout-smoke/preflight")
                .header(AUTHORIZATION, "Bearer token-a")
                .body(Body::empty())
                .expect("request builds"),
        )
        .await
        .expect("contributor response");
    assert_eq!(contributor_response.status(), StatusCode::FORBIDDEN);

    let raw_evidence_ref = "runbook://trace-commons/smoke/submit-status";
    for (status, marker) in [
        ("failed", "submit status smoke rehearsal failed first"),
        ("passed", "submit status smoke rehearsal passed later"),
    ] {
        let evidence_body = serde_json::json!({
            "check_name": "submit_status",
            "status": status,
            "evidence_hash": sha256_prefixed(marker),
            "evidence_ref": raw_evidence_ref
        });
        let append_response = app(state.clone())
            .oneshot(
                axum::http::Request::builder()
                    .method("POST")
                    .uri("/v1/admin/rollout-smoke/evidence")
                    .header(AUTHORIZATION, "Bearer admin-token-a")
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(evidence_body.to_string()))
                    .expect("request builds"),
            )
            .await
            .expect("append response");
        assert_eq!(append_response.status(), StatusCode::OK);
        tokio::time::sleep(std::time::Duration::from_millis(1)).await;
    }

    let preflight_response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("GET")
                .uri("/v1/admin/rollout-smoke/preflight")
                .header(AUTHORIZATION, "Bearer admin-token-a")
                .body(Body::empty())
                .expect("request builds"),
        )
        .await
        .expect("preflight response");
    assert_eq!(preflight_response.status(), StatusCode::OK);
    let body = axum::body::to_bytes(preflight_response.into_body(), 16384)
        .await
        .expect("body reads");
    let preflight_json: serde_json::Value =
        serde_json::from_slice(&body).expect("preflight json parses");
    assert_eq!(
        preflight_json["tenant_storage_ref"],
        serde_json::json!(tenant_storage_ref("tenant-a"))
    );
    assert_eq!(
        preflight_json["rollout_smoke"]["required_check_count"],
        serde_json::json!(23)
    );
    assert_eq!(
        preflight_json["rollout_smoke"]["recorded_evidence_count"],
        serde_json::json!(1)
    );
    assert_eq!(
        preflight_json["rollout_smoke"]["passed_evidence_checks"],
        serde_json::json!(["submit_status"])
    );
    assert_eq!(
        preflight_json["rollout_smoke"]["missing_evidence_count"],
        serde_json::json!(22)
    );
    assert_eq!(
        preflight_json["latest_evidence"].as_array().map(Vec::len),
        Some(1)
    );
    assert_eq!(
        preflight_json["latest_evidence"][0]["check_name"],
        serde_json::json!("submit_status")
    );
    assert_eq!(
        preflight_json["latest_evidence"][0]["status"],
        serde_json::json!("passed")
    );
    assert!(
        preflight_json["latest_evidence"][0]["evidence_hash"]
            .as_str()
            .is_some_and(|value| value.starts_with("sha256:"))
    );
    assert!(
        preflight_json["latest_evidence"][0]["evidence_ref_hash"]
            .as_str()
            .is_some_and(|value| value.starts_with("sha256:"))
    );
    assert!(
        !body
            .windows(raw_evidence_ref.len())
            .any(|window| window == raw_evidence_ref.as_bytes())
    );
    assert!(
        !body
            .windows(b"admin-token-a".len())
            .any(|window| window == b"admin-token-a")
    );

    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit reads");
    assert!(audit_events.iter().any(|event| {
        event.kind == "read"
            && event
                .reason
                .as_deref()
                .is_some_and(|reason| reason.starts_with("surface=rollout_smoke_preflight;"))
    }));
}

