/// The narrower sibling: `update_trace_gate_decision_dedup_cluster` moves ONLY
/// `dedup_cluster_id` and `dedup_cluster_size`. The simhash and its version
/// stamp are left exactly as they were, INCLUDING a stamp that is NULL.
///
/// This is what the recluster sweep uses, and the whole point of a second,
/// narrower write is that a row recorded before V57 comes out of a sweep
/// still recorded before V57. If the pass wrote the version it read the row
/// as, every pre-column row would acquire the legacy literal on the first
/// sweep -- the schema-level assertion V57's header refuses a DEFAULT for,
/// made by a background job instead, and no later pass could then tell a
/// row it re-derived from a row it merely re-clustered.
#[tokio::test]
async fn update_trace_gate_decision_dedup_cluster_touches_only_cluster_columns() {
    let db = PerplexityDriverTestDb::new();
    let submission_id = Uuid::new_v4();
    let before_row = rescore_test_decision_row(submission_id);
    let decision_id = before_row.decision_id;
    db.seed_gate_decision("tenant-a", before_row.clone());

    // A row as it exists before V57: a simhash, a cluster, and no stamp.
    db.update_trace_gate_decision_dedup(
        "tenant-a",
        decision_id,
        trace_commons_server::trace_corpus_storage::DedupAssignmentWrite {
            dedup_simhash: 42,
            dedup_cluster_id: Uuid::from_u128(7),
            dedup_cluster_size: 3,
            dedup_signal_version: "events.v1+fnv1a-2shingle.v1".to_string(),
        },
    )
    .await
    .expect("dedup update succeeds");
    db.overwrite_dedup_signal_version_for_tests("tenant-a", decision_id, None);

    let moved = Uuid::from_u128(9);
    db.update_trace_gate_decision_dedup_cluster("tenant-a", decision_id, moved, 5)
        .await
        .expect("cluster update succeeds");

    let after = db
        .gate_decision_with_dedup_by_id("tenant-a", decision_id)
        .expect("row still present");

    // The two cluster values moved to exactly what we passed.
    assert_eq!(after.dedup_cluster_id, Some(moved));
    assert_eq!(after.dedup_cluster_size, Some(5));

    // The two derived values did not.
    assert_eq!(
        after.dedup_simhash,
        Some(42),
        "the sweep re-clusters a stored simhash; it never recomputes one"
    );
    assert_eq!(
        after.dedup_signal_version,
        Some(None),
        "a NULL stamp survives the write: the pass reads the row as the \
         legacy version but has no evidence to record that it IS one"
    );

    // Every base-row column is byte-identical to before.
    assert_eq!(after.row.decision_id, before_row.decision_id);
    assert_eq!(after.row.submission_id, before_row.submission_id);
    assert_eq!(after.row.gate_version_hash, before_row.gate_version_hash);
    assert_eq!(after.row.perplexity_micros, before_row.perplexity_micros);
    assert_eq!(
        after.row.novelty_score_micros,
        before_row.novelty_score_micros
    );
    assert_eq!(after.row.decided_at, before_row.decided_at);
    assert_eq!(after.row.chunk_count, before_row.chunk_count);
    assert_eq!(after.row.chunks_capped, before_row.chunks_capped);
}

// -----------------------------------------------------------------------
// Task 6: inline cross-trace dedup (simhash-only) tests
// -----------------------------------------------------------------------

/// Same fixture as `fixture_gate_worker_artifact_store` but also returns a
/// `KmsKeyWrapper` decryptor built from the SAME underlying key material and
/// key-ref label as the artifact store's KEK. `LocalMasterKeyWrapper`/
/// `SecretsCrypto` derive their AES key from the master-key string plus a
/// per-encryption salt carried inline in the wrapped output (see
/// `SecretsCrypto::decrypt`), so a second, independently-constructed wrapper
/// over the same key string can unwrap DEKs the store's own (moved-in) KEK
/// wrapped — letting a caller build a real `EnclaveGateService` that decrypts
/// the exact envelopes this store writes. The Task 6 dedup test needs this:
/// it asserts on the ACTUAL decrypted plaintext's simhash, not a synthetic
/// stand-in, so it must exercise the real `EnclaveGateService::evaluate_trace`
/// decrypt path (Part A wires `dedup_simhash` from `plaintext` there).
fn fixture_gate_worker_artifact_store_with_decryptor(
    artifact_root: &Path,
) -> (ConfiguredTraceArtifactStore, Arc<dyn KmsKeyWrapper>, String) {
    let object_store = TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE.to_string();
    let key = trace_commons_server::secrets::keychain::generate_master_key_hex();
    let crypto = SecretsCrypto::new(SecretString::from(key.clone())).expect("fixture crypto");
    let kek_crypto =
        SecretsCrypto::new(SecretString::from(key.clone())).expect("fixture kek crypto");
    let kek = LocalMasterKeyWrapper::new(kek_crypto, "trace-commons-gate-worker-test-v1");
    let provider_config = TraceArtifactProviderConfig::service_owned_remote(object_store.clone())
        .expect("provider config");
    let provider = FileRemoteTraceArtifactProvider::new(artifact_root.to_path_buf());
    let store = Arc::new(ServiceOwnedTraceArtifactStore::new(
        provider_config,
        crypto,
        kek,
        provider,
    ));
    let configured = ConfiguredTraceArtifactStore::new(object_store.clone(), store);
    let decryptor_crypto = SecretsCrypto::new(SecretString::from(key)).expect("decryptor crypto");
    let decryptor: Arc<dyn KmsKeyWrapper> = Arc::new(LocalMasterKeyWrapper::new(
        decryptor_crypto,
        "trace-commons-gate-worker-test-v1",
    ));
    (configured, decryptor, object_store)
}

/// Like `seed_perplexity_driver_test_db` but takes one plaintext-JSON payload
/// per submission (instead of a fixed `{"safe": true}` for every one), so a
/// test can control which submissions carry byte-identical vs distinct
/// canonical text. Returns the submission ids in the same order as `texts`.
fn seed_perplexity_driver_test_db_with_texts(
    artifact_store: &ConfiguredTraceArtifactStore,
    tenant_id: &str,
    texts: &[&str],
) -> (Arc<PerplexityDriverTestDb>, Vec<Uuid>) {
    let db = Arc::new(PerplexityDriverTestDb::new());
    let mut submission_ids = Vec::with_capacity(texts.len());
    for text in texts {
        let submission_id = Uuid::new_v4();
        let plaintext =
            serde_json::to_vec(&serde_json::json!({"text": text})).expect("plaintext serializes");
        let receipt = artifact_store
            .store
            .put_serialized_json(
                &tenant_storage_ref(tenant_id),
                TraceArtifactKind::ContributionEnvelope,
                &submission_id.to_string(),
                &plaintext,
            )
            .expect("v2 artifact write");
        // See `seed_perplexity_driver_test_db`: `created_at` must be
        // `receipt.encrypted_at` so the reconstructed receipt round-trips.
        db.seed_ungated_submission(
            tenant_id,
            submission_id,
            StorageTraceObjectRefRecord {
                tenant_id: tenant_id.to_string(),
                submission_id,
                object_ref_id: Uuid::new_v4(),
                artifact_kind: StorageTraceObjectArtifactKind::SubmittedEnvelope,
                object_store: artifact_store.object_store_name().to_string(),
                object_key: receipt.object_key.clone(),
                content_sha256: format!("sha256:{}", receipt.ciphertext_sha256),
                encryption_key_ref: format!("tenant:{}", tenant_storage_ref(tenant_id)),
                size_bytes: plaintext.len() as i64,
                compression: None,
                created_by_job_id: None,
                invalidated_at: None,
                deleted_at: None,
                updated_at: receipt.encrypted_at,
                created_at: receipt.encrypted_at,
            },
        );
        submission_ids.push(submission_id);
    }
    (db, submission_ids)
}

/// Task 6 payoff: `evaluate_and_record_gate` clusters duplicate traces by
/// their gate-service-computed simhash. Drives THREE real
/// `evaluate_and_record_gate` calls (real v2 KEK-wrapped envelopes, real
/// `EnclaveGateService` decrypt path) — two submissions carry byte-identical
/// canonical text, one carries unrelated text — and asserts, via
/// `gate_decision_with_dedup_by_id`, that the two duplicates land in the same
/// `dedup_cluster_id` with `dedup_cluster_size == 2` while the distinct trace
/// gets its own singleton cluster (`dedup_cluster_size == 1`).
#[tokio::test]
async fn evaluate_and_record_gate_clusters_duplicate_traces_by_simhash() {
    let temp = tempfile::tempdir().expect("temp dir");
    let artifact_temp = tempfile::tempdir().expect("artifact temp dir");
    let (artifact_store, decryptor, _object_store_name) =
        fixture_gate_worker_artifact_store_with_decryptor(artifact_temp.path());
    let tenant_id = "tenant-a";

    let duplicate_text = "the quick brown fox jumps over the lazy dog near the riverbank at dawn";
    let distinct_text = "an entirely unrelated trace about deploying kubernetes clusters";

    let (db, submission_ids) = seed_perplexity_driver_test_db_with_texts(
        &artifact_store,
        tenant_id,
        &[duplicate_text, duplicate_text, distinct_text],
    );
    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        Some(artifact_store),
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );
    Arc::make_mut(&mut state).gate_service =
        Arc::new(EnclaveGateService::mock_with_decryptor(decryptor));

    let mut decision_ids = Vec::with_capacity(submission_ids.len());
    for submission_id in &submission_ids {
        let outcome = evaluate_and_record_gate(state.as_ref(), tenant_id, *submission_id)
            .await
            .expect("evaluate_and_record_gate succeeds");
        let GateOutcome::Scored { decision_id, .. } = outcome else {
            panic!("expected GateOutcome::Scored, got {outcome:?}");
        };
        decision_ids.push(decision_id);
    }

    let first = db
        .gate_decision_with_dedup_by_id(tenant_id, decision_ids[0])
        .expect("first decision row present");
    let second = db
        .gate_decision_with_dedup_by_id(tenant_id, decision_ids[1])
        .expect("second decision row present");
    let third = db
        .gate_decision_with_dedup_by_id(tenant_id, decision_ids[2])
        .expect("third decision row present");

    assert!(
        first.dedup_cluster_id.is_some(),
        "first decision must be assigned a cluster"
    );
    assert_eq!(
        first.dedup_cluster_id, second.dedup_cluster_id,
        "byte-identical canonical text must land in the same dedup cluster"
    );
    assert_eq!(
        second.dedup_cluster_size,
        Some(2),
        "second duplicate observes cluster size 2 (itself + the first)"
    );
    assert_ne!(
        third.dedup_cluster_id, first.dedup_cluster_id,
        "unrelated canonical text must land in a distinct dedup cluster"
    );
    assert_eq!(
        third.dedup_cluster_size,
        Some(1),
        "the distinct trace is a singleton cluster"
    );
}

/// Run one submission through `evaluate_and_record_gate` and return the
/// decision id it recorded, panicking on any outcome but `Scored`. Shared by
/// the dedup tests that need several sequential real gate evaluations and
/// care about what each one clustered against.
async fn score_submission_for_dedup_test(
    state: &Arc<AppState>,
    tenant_id: &str,
    submission_id: Uuid,
) -> Uuid {
    let outcome = evaluate_and_record_gate(state.as_ref(), tenant_id, submission_id)
        .await
        .expect("evaluate_and_record_gate succeeds");
    let GateOutcome::Scored { decision_id, .. } = outcome else {
        panic!("expected GateOutcome::Scored, got {outcome:?}");
    };
    decision_id
}

/// The inline half of V57's version scoping, through three real
/// `evaluate_and_record_gate` calls over BYTE-IDENTICAL text — so every
/// simhash here is the same number and the stamp is the only variable.
///
/// Two claims, in order:
///
///  1. `NULL` maps to the legacy v1 stamp (D2). The first decision's stamp is
///     dropped to `NULL` — the shape of every row recorded before the column
///     existed — and the second decision, stamped v1 by the enclave path,
///     must still join its cluster. If `NULL` were read as its own version,
///     the entire pre-transition corpus would fall out of clustering the
///     moment this column shipped: a worse split than the one it exists to
///     prevent, and a silent one.
///  2. Two named versions never join. Both earlier rows are then re-stamped
///     to a v2, and the third decision — still v1 — must mint its own cluster
///     at Hamming distance 0 from both.
#[tokio::test]
async fn evaluate_and_record_gate_clusters_only_within_one_dedup_signal_version() {
    let temp = tempfile::tempdir().expect("temp dir");
    let artifact_temp = tempfile::tempdir().expect("artifact temp dir");
    let (artifact_store, decryptor, _object_store_name) =
        fixture_gate_worker_artifact_store_with_decryptor(artifact_temp.path());
    let tenant_id = "tenant-a";
    const V2_STAMP: &str = "events.v2+fnv1a-2shingle.v1";

    let shared_text = "the quick brown fox jumps over the lazy dog near the riverbank at dawn";
    let (db, submission_ids) = seed_perplexity_driver_test_db_with_texts(
        &artifact_store,
        tenant_id,
        &[shared_text, shared_text, shared_text],
    );
    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        Some(artifact_store),
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );
    Arc::make_mut(&mut state).gate_service =
        Arc::new(EnclaveGateService::mock_with_decryptor(decryptor));

    // --- 1. The enclave path stamps the composed v1 version. ---
    let first_id = score_submission_for_dedup_test(&state, tenant_id, submission_ids[0]).await;
    let first = db
        .gate_decision_with_dedup_by_id(tenant_id, first_id)
        .expect("first decision row present");
    let v1_stamp = format!(
        "{}+{}",
        trace_commons_gate_enclave::chunker::CANONICAL_RENDER_VERSION,
        trace_commons_server::dedup_simhash::DEDUP_SIMHASH_ALGORITHM
    );
    assert_eq!(
        first.dedup_signal_version,
        Some(Some(v1_stamp.clone())),
        "the enclave path names both halves of its derivation"
    );
    assert_eq!(
        v1_stamp,
        trace_commons_server::dedup_assign::LEGACY_DEDUP_SIGNAL_VERSION,
        "PR 1 leaves behaviour byte-identical: what the code stamps today and \
         what a pre-column row is read as are the same string"
    );

    // --- 2. A NULL stamp still clusters with a v1 one. ---
    db.overwrite_dedup_signal_version_for_tests(tenant_id, first_id, None);
    let second_id = score_submission_for_dedup_test(&state, tenant_id, submission_ids[1]).await;
    let second = db
        .gate_decision_with_dedup_by_id(tenant_id, second_id)
        .expect("second decision row present");
    assert!(
        first.dedup_cluster_id.is_some(),
        "first decision must be assigned a cluster"
    );
    assert_eq!(
        second.dedup_cluster_id, first.dedup_cluster_id,
        "a NULL-stamped row reads as the legacy v1 stamp, so an incoming v1 \
         decision joins its cluster"
    );
    assert_eq!(
        second.dedup_cluster_size,
        Some(2),
        "the second decision observes cluster size 2"
    );

    // --- 3. A differently stamped cluster is not a candidate at all. ---
    db.overwrite_dedup_signal_version_for_tests(tenant_id, first_id, Some(V2_STAMP));
    db.overwrite_dedup_signal_version_for_tests(tenant_id, second_id, Some(V2_STAMP));
    let third_id = score_submission_for_dedup_test(&state, tenant_id, submission_ids[2]).await;
    let third = db
        .gate_decision_with_dedup_by_id(tenant_id, third_id)
        .expect("third decision row present");
    assert_ne!(
        third.dedup_cluster_id, first.dedup_cluster_id,
        "identical canonical text must NOT join a cluster whose representative \
         was rendered by a different version"
    );
    assert_eq!(
        third.dedup_cluster_size,
        Some(1),
        "the version-isolated decision is a singleton despite Hamming 0"
    );
    assert_eq!(
        third.dedup_signal_version,
        Some(Some(v1_stamp)),
        "and it stamps its own version, not the one it declined to join"
    );
    assert_eq!(
        third.dedup_simhash, first.dedup_simhash,
        "the split is the stamp's doing: the simhashes are identical"
    );
}

/// Like `seed_perplexity_driver_test_db_with_texts` but each entry is a full
/// `TraceContributionEnvelope`-shaped JSON payload (an `events` array of
/// `{event_type, tool_name, redacted_content}` plus per-submission-unique
/// envelope metadata: `submission_id`, `trace_id`, `created_at`, and a
/// per-event `event_id`/`timestamp`). This is the shape
/// `parse_envelope_rendered_events` (chunker.rs:74) actually parses, and the
/// shape `EnclaveGateService::evaluate_trace` decrypts in production — unlike
/// `seed_perplexity_driver_test_db_with_texts`'s bare `{"text": ...}` stand-in,
/// which never exercises the metadata-carrying envelope fields at all.
fn seed_perplexity_driver_test_db_with_envelopes(
    artifact_store: &ConfiguredTraceArtifactStore,
    tenant_id: &str,
    // One entry per submission: the events (event_type, tool_name, content)
    // that make up that submission's canonical rendered text.
    events_per_submission: &[&[(&str, Option<&str>, &str)]],
) -> (Arc<PerplexityDriverTestDb>, Vec<Uuid>) {
    let db = Arc::new(PerplexityDriverTestDb::new());
    let mut submission_ids = Vec::with_capacity(events_per_submission.len());
    for events in events_per_submission {
        let submission_id = Uuid::new_v4();
        let trace_id = Uuid::new_v4();
        let created_at = chrono::Utc::now() + chrono::Duration::milliseconds(rand_offset_ms());
        let events_json: Vec<serde_json::Value> = events
            .iter()
            .map(|(event_type, tool_name, content)| {
                serde_json::json!({
                    "event_id": Uuid::new_v4().to_string(),
                    "event_type": event_type,
                    "tool_name": tool_name,
                    "redacted_content": content,
                    "timestamp": (chrono::Utc::now() + chrono::Duration::milliseconds(rand_offset_ms())).to_rfc3339(),
                })
            })
            .collect();
        let plaintext = serde_json::to_vec(&serde_json::json!({
            "submission_id": submission_id.to_string(),
            "trace_id": trace_id.to_string(),
            "created_at": created_at.to_rfc3339(),
            "events": events_json,
        }))
        .expect("plaintext serializes");
        let receipt = artifact_store
            .store
            .put_serialized_json(
                &tenant_storage_ref(tenant_id),
                TraceArtifactKind::ContributionEnvelope,
                &submission_id.to_string(),
                &plaintext,
            )
            .expect("v2 artifact write");
        db.seed_ungated_submission(
            tenant_id,
            submission_id,
            StorageTraceObjectRefRecord {
                tenant_id: tenant_id.to_string(),
                submission_id,
                object_ref_id: Uuid::new_v4(),
                artifact_kind: StorageTraceObjectArtifactKind::SubmittedEnvelope,
                object_store: artifact_store.object_store_name().to_string(),
                object_key: receipt.object_key.clone(),
                content_sha256: format!("sha256:{}", receipt.ciphertext_sha256),
                encryption_key_ref: format!("tenant:{}", tenant_storage_ref(tenant_id)),
                size_bytes: plaintext.len() as i64,
                compression: None,
                created_by_job_id: None,
                invalidated_at: None,
                deleted_at: None,
                updated_at: receipt.encrypted_at,
                created_at: receipt.encrypted_at,
            },
        );
        submission_ids.push(submission_id);
    }
    (db, submission_ids)
}

/// Like `seed_perplexity_driver_test_db_with_envelopes`, but each submission
/// also carries an `outcome` block with an optional `human_correction` — the
/// shape the S5 correction path reads. Every submission gets DISTINCT session
/// events so the trace-level dedup clustering cannot be what a correction
/// assertion is really observing.
fn seed_perplexity_driver_test_db_with_corrections(
    artifact_store: &ConfiguredTraceArtifactStore,
    tenant_id: &str,
    // One entry per submission: its correction text, or None for a submission
    // that carries no correction at all.
    corrections: &[Option<&str>],
) -> (Arc<PerplexityDriverTestDb>, Vec<Uuid>) {
    let db = Arc::new(PerplexityDriverTestDb::new());
    let mut submission_ids = Vec::with_capacity(corrections.len());
    for (index, correction) in corrections.iter().enumerate() {
        let submission_id = Uuid::new_v4();
        let trace_id = Uuid::new_v4();
        let created_at = chrono::Utc::now() + chrono::Duration::milliseconds(rand_offset_ms());
        let mut outcome = serde_json::json!({"task_success": "failure"});
        if let Some(text) = correction {
            outcome["human_correction"] = serde_json::Value::String((*text).to_string());
        }
        let plaintext = serde_json::to_vec(&serde_json::json!({
            "submission_id": submission_id.to_string(),
            "trace_id": trace_id.to_string(),
            "created_at": created_at.to_rfc3339(),
            "events": [{
                "event_id": Uuid::new_v4().to_string(),
                "event_type": "user_message",
                "redacted_content": format!(
                    "session {index} asked the agent to do something quite different from every \
                     other session in this fixture, number {index}"
                ),
                "timestamp": created_at.to_rfc3339(),
            }],
            "outcome": outcome,
        }))
        .expect("plaintext serializes");
        let receipt = artifact_store
            .store
            .put_serialized_json(
                &tenant_storage_ref(tenant_id),
                TraceArtifactKind::ContributionEnvelope,
                &submission_id.to_string(),
                &plaintext,
            )
            .expect("v2 artifact write");
        db.seed_ungated_submission(
            tenant_id,
            submission_id,
            StorageTraceObjectRefRecord {
                tenant_id: tenant_id.to_string(),
                submission_id,
                object_ref_id: Uuid::new_v4(),
                artifact_kind: StorageTraceObjectArtifactKind::SubmittedEnvelope,
                object_store: artifact_store.object_store_name().to_string(),
                object_key: receipt.object_key.clone(),
                content_sha256: format!("sha256:{}", receipt.ciphertext_sha256),
                encryption_key_ref: format!("tenant:{}", tenant_storage_ref(tenant_id)),
                size_bytes: plaintext.len() as i64,
                compression: None,
                created_by_job_id: None,
                invalidated_at: None,
                deleted_at: None,
                updated_at: receipt.encrypted_at,
                created_at: receipt.encrypted_at,
            },
        );
        submission_ids.push(submission_id);
    }
    (db, submission_ids)
}

/// Drive `evaluate_and_record_gate` over the given corrections and return the
/// stored correction-value view for each, in submission order.
async fn run_gate_over_corrections(
    corrections: &[Option<&str>],
) -> Vec<DecisionRowWithCorrectionValue> {
    let temp = tempfile::tempdir().expect("temp dir");
    let artifact_temp = tempfile::tempdir().expect("artifact temp dir");
    let (artifact_store, decryptor, _object_store_name) =
        fixture_gate_worker_artifact_store_with_decryptor(artifact_temp.path());
    let tenant_id = "tenant-a";
    let (db, submission_ids) =
        seed_perplexity_driver_test_db_with_corrections(&artifact_store, tenant_id, corrections);
    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        Some(artifact_store),
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );
    Arc::make_mut(&mut state).gate_service =
        Arc::new(EnclaveGateService::mock_with_decryptor(decryptor));

    let mut rows = Vec::with_capacity(submission_ids.len());
    for submission_id in &submission_ids {
        let outcome = evaluate_and_record_gate(state.as_ref(), tenant_id, *submission_id)
            .await
            .expect("evaluate_and_record_gate succeeds");
        let GateOutcome::Scored { decision_id, .. } = outcome else {
            panic!("expected GateOutcome::Scored, got {outcome:?}");
        };
        rows.push(
            db.gate_decision_with_correction_value_by_id(tenant_id, decision_id)
                .expect("decision row present"),
        );
    }
    rows
}

/// S5 payoff: a correction gets a stored shadow value, and a repeat paste of
/// the same correction does not earn again — the cluster it joins carries the
/// duplicate penalty and its novelty against the one already in the corpus is
/// zero.
#[tokio::test]
async fn evaluate_and_record_gate_stores_a_shadow_value_for_a_correction() {
    let correction = "the agent edited config/prod.toml when the task asked for the staging \
                      one; it should have written config/staging.toml and re-run the migration \
                      check afterwards";
    let other = "the assistant never ran the failing regression test before declaring the bug \
                 fixed, so the off by one in the pagination cursor survived the session";

    let rows =
        run_gate_over_corrections(&[Some(correction), Some(correction), Some(other), None]).await;

    // 1. A correction produces a stored value.
    assert!(
        rows[0].correction_simhash.is_some(),
        "a correction must produce a stored correction signal"
    );
    assert_eq!(rows[0].correction_cluster_size, Some(1));
    assert_eq!(rows[0].correction_novelty_micros, Some(1_000_000));
    assert!(
        rows[0].correction_value_micros.unwrap_or(0) > 0,
        "a first-of-its-kind correction must score above zero, got {:?}",
        rows[0].correction_value_micros
    );
    assert_eq!(
        rows[0].correction_value_version,
        Some(trace_commons_server::correction_value::CORRECTION_VALUE_ACTIVE.version)
    );

    // 2. The repeat paste joins the same cluster and earns nothing.
    assert_eq!(
        rows[1].correction_cluster_id, rows[0].correction_cluster_id,
        "an identical correction must join the same cluster"
    );
    assert_eq!(rows[1].correction_cluster_size, Some(2));
    assert_eq!(rows[1].correction_novelty_micros, Some(0));
    assert_eq!(
        rows[1].correction_value_micros,
        Some(0),
        "a repeat paste of the same correction must not earn again"
    );

    // 3. A genuinely different correction is not collapsed into it.
    assert_ne!(rows[2].correction_cluster_id, rows[0].correction_cluster_id);
    assert!(rows[2].correction_value_micros.unwrap_or(0) > 0);

    // 4. An envelope with NO correction is unchanged from today: no correction
    //    columns are written at all.
    assert_eq!(rows[3].correction_simhash, None);
    assert_eq!(rows[3].correction_cluster_id, None);
    assert_eq!(rows[3].correction_value_micros, None);
}

/// The shadow-mode guarantee, end to end: computing a correction's value must
/// not change what the contributor is credited. Two runs identical except for
/// the correction they carry produce the same gate status, the same credit
/// fields, and the same trace-level dedup and credit-quality signals.
#[tokio::test]
async fn a_correction_value_does_not_change_the_credited_decision() {
    let loud = "the agent edited config/prod.toml when the task asked for the staging one and \
                never re-ran the migration check, so the schema drifted for the rest of the run";

    let with_correction = run_gate_over_corrections(&[Some(loud)]).await;
    let without_correction = run_gate_over_corrections(&[None]).await;

    assert!(
        with_correction[0].correction_value_micros.unwrap_or(0) > 0,
        "the correction must actually have been valued, or this proves nothing"
    );
    assert_eq!(without_correction[0].correction_value_micros, None);

    // Everything the contributor is actually credited on is identical.
    let a = &with_correction[0].row;
    let b = &without_correction[0].row;
    assert_eq!(a.perplexity_passed, b.perplexity_passed);
    assert_eq!(a.novelty_passed, b.novelty_passed);
    assert_eq!(a.credit_withheld_reason, b.credit_withheld_reason);
    assert_eq!(a.gate_policy_version, b.gate_policy_version);
    assert_eq!(a.gate_version_hash, b.gate_version_hash);
}

/// Small helper so successive `chrono::Utc::now()` calls in
/// `seed_perplexity_driver_test_db_with_envelopes` don't collide when the
/// clock resolution is coarse; not cryptographic, just a decorrelation nudge.
fn rand_offset_ms() -> i64 {
    use std::sync::atomic::{AtomicI64, Ordering};
    static COUNTER: AtomicI64 = AtomicI64::new(0);
    COUNTER.fetch_add(1, Ordering::Relaxed)
}

/// C1 regression: the dedup simhash must be computed over the CANONICAL
/// RENDERED EVENT TEXT (metadata-free), not the raw envelope JSON. Two
/// submissions with byte-identical events but different
/// `submission_id`/`trace_id`/`created_at`/per-event `event_id`/`timestamp`
/// must still cluster together. Before the fix, `evaluate_trace` hashed
/// `String::from_utf8_lossy(&plaintext)` (the full envelope JSON including
/// the unique metadata fields), so this test fails: the two "duplicate"
/// submissions get different simhashes and land in different clusters.
#[tokio::test]
async fn evaluate_and_record_gate_clusters_duplicates_despite_distinct_envelope_metadata() {
    let temp = tempfile::tempdir().expect("temp dir");
    let artifact_temp = tempfile::tempdir().expect("artifact temp dir");
    let (artifact_store, decryptor, _object_store_name) =
        fixture_gate_worker_artifact_store_with_decryptor(artifact_temp.path());
    let tenant_id = "tenant-a";

    // Same canonical events (content, event_type, tool_name) for the first
    // two submissions; the third has unrelated content. Envelope-level
    // metadata (submission_id, trace_id, created_at, event_id, timestamp) is
    // regenerated fresh per submission by the seeding helper, so the two
    // "duplicates" are byte-identical only in their rendered event text.
    let shared_events: &[(&str, Option<&str>, &str)] = &[
        ("user_message", None, "please refactor the auth module"),
        (
            "tool_call",
            Some("Bash"),
            "cargo test -p trace-commons-server",
        ),
        (
            "assistant_message",
            None,
            "refactored auth module and tests pass",
        ),
    ];
    let distinct_events: &[(&str, Option<&str>, &str)] = &[(
        "user_message",
        None,
        "an entirely unrelated trace about deploying kubernetes clusters",
    )];

    let (db, submission_ids) = seed_perplexity_driver_test_db_with_envelopes(
        &artifact_store,
        tenant_id,
        &[shared_events, shared_events, distinct_events],
    );
    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        Some(artifact_store),
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );
    Arc::make_mut(&mut state).gate_service =
        Arc::new(EnclaveGateService::mock_with_decryptor(decryptor));

    let mut decision_ids = Vec::with_capacity(submission_ids.len());
    for submission_id in &submission_ids {
        let outcome = evaluate_and_record_gate(state.as_ref(), tenant_id, *submission_id)
            .await
            .expect("evaluate_and_record_gate succeeds");
        let GateOutcome::Scored { decision_id, .. } = outcome else {
            panic!("expected GateOutcome::Scored, got {outcome:?}");
        };
        decision_ids.push(decision_id);
    }

    let first = db
        .gate_decision_with_dedup_by_id(tenant_id, decision_ids[0])
        .expect("first decision row present");
    let second = db
        .gate_decision_with_dedup_by_id(tenant_id, decision_ids[1])
        .expect("second decision row present");
    let third = db
        .gate_decision_with_dedup_by_id(tenant_id, decision_ids[2])
        .expect("third decision row present");

    assert!(
        first.dedup_cluster_id.is_some(),
        "first decision must be assigned a cluster"
    );
    assert_eq!(
        first.dedup_cluster_id, second.dedup_cluster_id,
        "same canonical event text with different envelope metadata must still cluster together"
    );
    assert_eq!(
        second.dedup_cluster_size,
        Some(2),
        "second duplicate observes cluster size 2 (itself + the first)"
    );
    assert_ne!(
        third.dedup_cluster_id, first.dedup_cluster_id,
        "unrelated canonical text must land in a distinct dedup cluster"
    );
    assert_eq!(
        third.dedup_cluster_size,
        Some(1),
        "the distinct trace is a singleton cluster"
    );
}

/// Task 7 payoff: `run_recluster_dedup_pass` recomputes cluster assignments
/// over the whole corpus snapshot in a single deterministic sweep. Seeds
/// three decisions with `dedup_simhash` already set directly (no gate
/// evaluation): two carry the SAME simhash across two DIFFERENT tenants
/// (proving clustering is cross-tenant), one carries a distinct simhash.
/// After the pass, the two same-simhash rows must share a `dedup_cluster_id`
/// with `dedup_cluster_size == 2`; the distinct row must be a singleton
/// (`dedup_cluster_size == 1`). Also asserts the perplexity/novelty/
/// credit_quality columns are byte-identical before and after — the pass
/// writes ONLY the dedup side table.
#[tokio::test]
async fn recluster_dedup_pass_clusters_cross_tenant_and_leaves_other_columns_untouched() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let db_mirror: Arc<dyn Database> = db.clone();
    let state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );

    let shared_simhash: i64 = 0x1234_5678_9abc_def0;
    let distinct_simhash: i64 = 0x0f0f_0f0f_0f0f_0f0f;
    const V1_STAMP: &str = trace_commons_server::dedup_assign::LEGACY_DEDUP_SIGNAL_VERSION;

    let row_a = rescore_test_decision_row(Uuid::new_v4());
    let row_b = rescore_test_decision_row(Uuid::new_v4());
    let row_c = rescore_test_decision_row(Uuid::new_v4());

    db.seed_gate_decision("tenant-a", row_a.clone());
    db.seed_gate_decision("tenant-b", row_b.clone());
    db.seed_gate_decision("tenant-a", row_c.clone());

    // Seed initial dedup_simhash values directly (as if a prior inline gate
    // pass had recorded them), with placeholder cluster assignments the
    // recluster pass is expected to overwrite entirely.
    db.update_trace_gate_decision_dedup(
        "tenant-a",
        row_a.decision_id,
        trace_commons_server::trace_corpus_storage::DedupAssignmentWrite {
            dedup_simhash: shared_simhash,
            dedup_cluster_id: Uuid::new_v4(),
            dedup_cluster_size: 1,
            dedup_signal_version: V1_STAMP.to_string(),
        },
    )
    .await
    .expect("seed row_a dedup");
    db.update_trace_gate_decision_dedup(
        "tenant-b",
        row_b.decision_id,
        trace_commons_server::trace_corpus_storage::DedupAssignmentWrite {
            dedup_simhash: shared_simhash,
            dedup_cluster_id: Uuid::new_v4(),
            dedup_cluster_size: 1,
            dedup_signal_version: V1_STAMP.to_string(),
        },
    )
    .await
    .expect("seed row_b dedup");
    db.update_trace_gate_decision_dedup(
        "tenant-a",
        row_c.decision_id,
        trace_commons_server::trace_corpus_storage::DedupAssignmentWrite {
            dedup_simhash: distinct_simhash,
            dedup_cluster_id: Uuid::new_v4(),
            dedup_cluster_size: 1,
            dedup_signal_version: V1_STAMP.to_string(),
        },
    )
    .await
    .expect("seed row_c dedup");

    let snapshot = [
        ("tenant-a", row_a.clone()),
        ("tenant-b", row_b.clone()),
        ("tenant-a", row_c.clone()),
    ];

    let summary = run_recluster_dedup_pass(state.clone(), None)
        .await
        .expect("recluster pass succeeds");
    assert_eq!(
        summary.reclustered, 3,
        "all 3 rows must be reclustered: {summary:?}"
    );
    assert_eq!(summary.failed, 0, "no row should fail: {summary:?}");

    let after_a = db
        .gate_decision_with_dedup_by_id("tenant-a", row_a.decision_id)
        .expect("row_a present");
    let after_b = db
        .gate_decision_with_dedup_by_id("tenant-b", row_b.decision_id)
        .expect("row_b present");
    let after_c = db
        .gate_decision_with_dedup_by_id("tenant-a", row_c.decision_id)
        .expect("row_c present");

    assert!(
        after_a.dedup_cluster_id.is_some(),
        "row_a must be assigned a cluster"
    );
    assert_eq!(
        after_a.dedup_cluster_id, after_b.dedup_cluster_id,
        "same simhash across two different tenants must land in the same cluster"
    );
    assert_eq!(
        after_a.dedup_cluster_size,
        Some(2),
        "shared-simhash cluster has 2 members"
    );
    assert_eq!(
        after_b.dedup_cluster_size,
        Some(2),
        "shared-simhash cluster has 2 members"
    );
    assert_ne!(
        after_c.dedup_cluster_id, after_a.dedup_cluster_id,
        "distinct simhash must land in a different cluster"
    );
    assert_eq!(
        after_c.dedup_cluster_size,
        Some(1),
        "distinct simhash is a singleton cluster"
    );

    // Isolation: perplexity/novelty/credit_quality columns are byte-identical
    // before and after — the recluster pass writes ONLY the dedup side table.
    for (tenant_id, original) in &snapshot {
        let after = db
            .gate_decision_with_dedup_by_id(tenant_id, original.decision_id)
            .expect("row present");
        assert_eq!(after.row.decision_id, original.decision_id);
        assert_eq!(after.row.submission_id, original.submission_id);
        assert_eq!(after.row.perplexity_micros, original.perplexity_micros);
        assert_eq!(
            after.row.peak_perplexity_micros,
            original.peak_perplexity_micros
        );
        assert_eq!(after.row.perplexity_passed, original.perplexity_passed);
        assert_eq!(
            after.row.novelty_score_micros,
            original.novelty_score_micros
        );
        assert_eq!(after.row.novelty_passed, original.novelty_passed);
    }
    let credit_after = db
        .gate_decision_with_credit_quality_by_id("tenant-a", row_a.decision_id)
        .expect("row_a present");
    assert_eq!(
        credit_after.credit_quality_micros, None,
        "recluster pass must never touch the credit-quality side table"
    );
}

/// Sibling of the test above, for the property migration V57 exists to give
/// the pass: `run_recluster_dedup_pass` never fuses rows whose
/// `dedup_signal_version` differs, however close their simhashes are.
///
/// The pass reads stored simhashes and never re-renders, so once a renderer
/// bump lands, a corpus holds two populations whose numbers are not measuring
/// the same thing. Four rows carry the IDENTICAL simhash: two stamped v1, one
/// stamped NULL (recorded before the column existed), and one stamped v2. The
/// three v1-effective rows must form one cluster of three — NULL reads as the
/// legacy v1 stamp (D2), not as its own version and not as "matches
/// everything" — and the v2 row must sit alone at Hamming distance 0 from all
/// three.
#[tokio::test]
async fn recluster_dedup_pass_never_clusters_across_dedup_signal_versions() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let db_mirror: Arc<dyn Database> = db.clone();
    let state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );

    // One simhash for every row: the ONLY thing separating them is the stamp.
    let shared_simhash: i64 = 0x1234_5678_9abc_def0;
    const V1_STAMP: &str = trace_commons_server::dedup_assign::LEGACY_DEDUP_SIGNAL_VERSION;
    const V2_STAMP: &str = "events.v2+fnv1a-2shingle.v1";

    let row_v1_a = rescore_test_decision_row(Uuid::new_v4());
    let row_v1_b = rescore_test_decision_row(Uuid::new_v4());
    let row_null = rescore_test_decision_row(Uuid::new_v4());
    let row_v2 = rescore_test_decision_row(Uuid::new_v4());

    // Insertion order is the sweep order (`list_dedup_signals` mirrors the
    // real `decided_at ASC`), so the v1 rows form their cluster first and the
    // v2 row meets an established, differently-stamped candidate.
    db.seed_gate_decision("tenant-a", row_v1_a.clone());
    db.seed_gate_decision("tenant-b", row_v1_b.clone());
    db.seed_gate_decision("tenant-a", row_null.clone());
    db.seed_gate_decision("tenant-a", row_v2.clone());

    for (tenant, row, stamp) in [
        ("tenant-a", &row_v1_a, V1_STAMP),
        ("tenant-b", &row_v1_b, V1_STAMP),
        ("tenant-a", &row_null, V1_STAMP),
        ("tenant-a", &row_v2, V2_STAMP),
    ] {
        db.update_trace_gate_decision_dedup(
            tenant,
            row.decision_id,
            trace_commons_server::trace_corpus_storage::DedupAssignmentWrite {
                dedup_simhash: shared_simhash,
                dedup_cluster_id: Uuid::new_v4(),
                dedup_cluster_size: 1,
                dedup_signal_version: stamp.to_string(),
            },
        )
        .await
        .expect("seed dedup");
    }
    // Drop the third row's stamp to NULL. Nothing in the server can write a
    // simhash without a stamp; this is what a row recorded before V57 looks
    // like, and the pass has to read it as v1 rather than as its own version.
    db.overwrite_dedup_signal_version_for_tests("tenant-a", row_null.decision_id, None);

    let summary = run_recluster_dedup_pass(state.clone(), None)
        .await
        .expect("recluster pass succeeds");
    assert_eq!(
        summary.reclustered, 4,
        "all 4 rows must be reclustered: {summary:?}"
    );
    assert_eq!(summary.failed, 0, "no row should fail: {summary:?}");

    let after_v1_a = db
        .gate_decision_with_dedup_by_id("tenant-a", row_v1_a.decision_id)
        .expect("row_v1_a present");
    let after_v1_b = db
        .gate_decision_with_dedup_by_id("tenant-b", row_v1_b.decision_id)
        .expect("row_v1_b present");
    let after_null = db
        .gate_decision_with_dedup_by_id("tenant-a", row_null.decision_id)
        .expect("row_null present");
    let after_v2 = db
        .gate_decision_with_dedup_by_id("tenant-a", row_v2.decision_id)
        .expect("row_v2 present");

    assert_eq!(
        after_v1_a.dedup_cluster_id, after_v1_b.dedup_cluster_id,
        "the same simhash under the same stamp still clusters cross-tenant"
    );
    assert_eq!(
        after_null.dedup_cluster_id, after_v1_a.dedup_cluster_id,
        "a NULL stamp reads as the legacy v1 stamp, so a pre-V57 row clusters \
         with freshly stamped v1 rows"
    );
    assert_eq!(
        after_v1_a.dedup_cluster_size,
        Some(3),
        "the v1-effective cluster holds all three v1-effective rows"
    );
    assert_ne!(
        after_v2.dedup_cluster_id, after_v1_a.dedup_cluster_id,
        "an identical simhash under a different stamp must NEVER join: the \
         two numbers are not measuring the same thing"
    );
    assert_eq!(
        after_v2.dedup_cluster_size,
        Some(1),
        "the v2 row is a singleton despite Hamming distance 0 from three peers"
    );

    // The pass writes NO stamp at all: it re-clusters stored simhashes and
    // never re-renders, so it derives neither the simhash nor the version and
    // has nothing to say about either. Every row keeps exactly the stamp it
    // arrived with.
    assert_eq!(
        after_v1_a.dedup_signal_version,
        Some(Some(V1_STAMP.to_string()))
    );
    assert_eq!(
        after_null.dedup_signal_version,
        Some(None),
        "a NULL stamp is READ as the legacy version and STAYS NULL: the pass \
         has no evidence for the reading, and a row it stamped would be \
         indistinguishable from one the re-derivation pass actually \
         re-derived -- which is the reason V57 refuses a column DEFAULT"
    );
    assert_eq!(
        after_v2.dedup_signal_version,
        Some(Some(V2_STAMP.to_string())),
        "the v2 row keeps its own stamp"
    );

    // The simhash itself is untouched: only the cluster columns move.
    for after in [&after_v1_a, &after_v1_b, &after_null, &after_v2] {
        assert_eq!(after.dedup_simhash, Some(shared_simhash));
    }
}

/// The version gate, exercised with the two stamps this build actually
/// writes rather than a synthetic v2: a deterministic service's
/// `digest-prefix.v1` and the enclave's composed render+simhash.
///
/// A deterministic service never sees plaintext, so its `dedup_simhash` is an
/// eight-byte window of the decision digest -- not a simhash of anything. It
/// lands in the same column as the enclave's, enters the same sweep, and
/// before V57 nothing recorded the difference. Both rows here carry an
/// IDENTICAL value, which is the case a threshold cannot save you from:
/// Hamming distance 0 between two numbers that are not measuring the same
/// thing.
#[tokio::test]
async fn recluster_dedup_pass_never_clusters_a_deterministic_row_with_an_enclave_row() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let db_mirror: Arc<dyn Database> = db.clone();
    let state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );

    let shared_simhash: i64 = 0x1234_5678_9abc_def0;
    const ENCLAVE: &str = trace_commons_server::dedup_assign::LEGACY_DEDUP_SIGNAL_VERSION;
    const DETERMINISTIC: &str =
        trace_commons_server::trace_gate_service::DETERMINISTIC_DEDUP_SIGNAL_VERSION;

    let enclave_row = rescore_test_decision_row(Uuid::new_v4());
    let deterministic_row = rescore_test_decision_row(Uuid::new_v4());
    db.seed_gate_decision("tenant-a", enclave_row.clone());
    db.seed_gate_decision("tenant-b", deterministic_row.clone());

    for (tenant, row, stamp) in [
        ("tenant-a", &enclave_row, ENCLAVE),
        ("tenant-b", &deterministic_row, DETERMINISTIC),
    ] {
        db.update_trace_gate_decision_dedup(
            tenant,
            row.decision_id,
            trace_commons_server::trace_corpus_storage::DedupAssignmentWrite {
                dedup_simhash: shared_simhash,
                dedup_cluster_id: Uuid::new_v4(),
                dedup_cluster_size: 1,
                dedup_signal_version: stamp.to_string(),
            },
        )
        .await
        .expect("seed dedup");
    }

    let summary = run_recluster_dedup_pass(state.clone(), None)
        .await
        .expect("recluster pass succeeds");
    assert_eq!(summary.reclustered, 2, "both rows sweep: {summary:?}");
    assert_eq!(summary.failed, 0, "no row should fail: {summary:?}");

    let after_enclave = db
        .gate_decision_with_dedup_by_id("tenant-a", enclave_row.decision_id)
        .expect("enclave row present");
    let after_deterministic = db
        .gate_decision_with_dedup_by_id("tenant-b", deterministic_row.decision_id)
        .expect("deterministic row present");

    assert_ne!(
        after_enclave.dedup_cluster_id, after_deterministic.dedup_cluster_id,
        "a digest window and a text simhash must never share a cluster, \
         however equal the two numbers are"
    );
    assert_eq!(after_enclave.dedup_cluster_size, Some(1));
    assert_eq!(after_deterministic.dedup_cluster_size, Some(1));
}

// -----------------------------------------------------------------------
// Task 4 (contributor-cap slice): `run_recompute_contributor_caps_pass` tests
// -----------------------------------------------------------------------

/// Cross-tenant: the SAME `auth_principal_ref` submitting through two
/// DIFFERENT tenants in the SAME epoch shares ONE per-epoch running total.
/// Decision 2 accumulates on top of decision 1's `r`, so its marginal factor
/// must be strictly smaller than decision 1's, and its cumulative snapshot
/// must equal `r1 + r2`.
#[tokio::test]
async fn recompute_contributor_caps_shares_running_total_across_tenants() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let db_mirror: Arc<dyn Database> = db.clone();
    let state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );

    let shared_principal = "shared-contributor-cross-tenant";
    let now = Utc::now();

    let mut row_1 = rescore_test_decision_row(Uuid::new_v4());
    row_1.decided_at = now;
    let mut row_2 = rescore_test_decision_row(Uuid::new_v4());
    row_2.decided_at = now + chrono::Duration::seconds(60);

    db.seed_submission_with_principal("tenant-a", row_1.submission_id, shared_principal);
    db.seed_submission_with_principal("tenant-b", row_2.submission_id, shared_principal);
    db.seed_gate_decision("tenant-a", row_1.clone());
    db.seed_gate_decision("tenant-b", row_2.clone());

    // Sizable raw increment (q = 0.8, no dedup penalty) for both decisions,
    // pushing the running total well into the concave region so the second
    // decision's marginal factor is visibly smaller than the first's.
    db.update_trace_gate_decision_credit_quality("tenant-a", row_1.decision_id, 800_000, 0, 1)
        .await
        .expect("seed row_1 credit quality");
    db.update_trace_gate_decision_credit_quality("tenant-b", row_2.decision_id, 800_000, 0, 1)
        .await
        .expect("seed row_2 credit quality");

    let summary = run_recompute_contributor_caps_pass(state.clone(), None)
        .await
        .expect("recompute pass succeeds");
    assert_eq!(summary.updated, 2, "both rows must be updated: {summary:?}");
    assert_eq!(summary.failed, 0, "no row should fail: {summary:?}");

    let after_1 = db
        .gate_decision_with_contributor_cap_by_id("tenant-a", row_1.decision_id)
        .expect("row_1 present");
    let after_2 = db
        .gate_decision_with_contributor_cap_by_id("tenant-b", row_2.decision_id)
        .expect("row_2 present");

    let factor_1 = after_1
        .contributor_factor_micros
        .expect("row_1 factor written");
    let factor_2 = after_2
        .contributor_factor_micros
        .expect("row_2 factor written");
    assert!(
        factor_2 < factor_1,
        "second decision for the SAME principal across tenants must have a \
         strictly smaller marginal factor: factor_1={factor_1} factor_2={factor_2}"
    );

    let cumulative_1 = after_1
        .contributor_cumulative_raw_micros
        .expect("row_1 cumulative written");
    let cumulative_2 = after_2
        .contributor_cumulative_raw_micros
        .expect("row_2 cumulative written");
    assert_eq!(cumulative_1, 800_000, "row_1 cumulative == r1 (R_before=0)");
    assert_eq!(
        cumulative_2, 1_600_000,
        "row_2 cumulative == r1 + r2, shared running total across tenants"
    );
}

/// Epoch reset: two decisions for ONE principal in DIFFERENT 7-day epochs
/// each start from `R_before = 0`, so both get a marginal factor near 1.0
/// (~1_000_000 micros) regardless of order.
#[tokio::test]
async fn recompute_contributor_caps_resets_each_epoch() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let db_mirror: Arc<dyn Database> = db.clone();
    let state = test_state_with_configured_artifact_store_policies_and_export_guardrails(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
        false,
        false,
        BTreeMap::new(),
        false,
        false,
    );

    let principal = "epoch-reset-contributor";
    // Epoch-align to unix epoch 0 so the 8-day gap unambiguously crosses a
    // 7-day epoch boundary regardless of "now"'s phase within its epoch.
    let epoch0_anchor = DateTime::<Utc>::from_timestamp(0, 0).expect("valid timestamp");

    let mut row_1 = rescore_test_decision_row(Uuid::new_v4());
    row_1.decided_at = epoch0_anchor + chrono::Duration::hours(1);
    let mut row_2 = rescore_test_decision_row(Uuid::new_v4());
    row_2.decided_at = epoch0_anchor + chrono::Duration::days(8);

    db.seed_submission_with_principal("tenant-a", row_1.submission_id, principal);
    db.seed_submission_with_principal("tenant-a", row_2.submission_id, principal);
    db.seed_gate_decision("tenant-a", row_1.clone());
    db.seed_gate_decision("tenant-a", row_2.clone());

    // Modest raw increment: r = 0.1 for both, well within the near-linear
    // region so a fresh-epoch factor should read close to 1.0.
    db.update_trace_gate_decision_credit_quality("tenant-a", row_1.decision_id, 100_000, 0, 1)
        .await
        .expect("seed row_1 credit quality");
    db.update_trace_gate_decision_credit_quality("tenant-a", row_2.decision_id, 100_000, 0, 1)
        .await
        .expect("seed row_2 credit quality");

    let summary = run_recompute_contributor_caps_pass(state.clone(), None)
        .await
        .expect("recompute pass succeeds");
    assert_eq!(summary.updated, 2, "both rows must be updated: {summary:?}");
    assert_eq!(summary.failed, 0, "no row should fail: {summary:?}");

    let after_1 = db
        .gate_decision_with_contributor_cap_by_id("tenant-a", row_1.decision_id)
        .expect("row_1 present");
    let after_2 = db
        .gate_decision_with_contributor_cap_by_id("tenant-a", row_2.decision_id)
        .expect("row_2 present");

    assert_ne!(
        after_1.contributor_cap_epoch, after_2.contributor_cap_epoch,
        "an 8-day gap must cross a 7-day epoch boundary"
    );
    let factor_1 = after_1
        .contributor_factor_micros
        .expect("row_1 factor written");
    let factor_2 = after_2
        .contributor_factor_micros
        .expect("row_2 factor written");
    assert!(
        factor_1 > 990_000,
        "row_1 is first-in-epoch, expected near-1.0, got {factor_1}"
    );
    assert!(
        factor_2 > 990_000,
        "row_2 resets into a fresh epoch, expected near-1.0, got {factor_2}"
    );
}

/// Column isolation: capture a decision's `credit_quality_micros`,
