impl Database for PiiBackstopDriverTestDb {
    async fn run_migrations(&self) -> Result<(), DatabaseError> {
        Ok(())
    }

    async fn enroll_instance_user(
        &self,
        _p: trace_commons_server::db::InstanceUserProvision,
    ) -> Result<(), DatabaseError> {
        Err(DatabaseError::Pool("stub".into()))
    }

    async fn reserve_instance_enrollment(
        &self,
        _instance_subject_hash: &str,
        _user_subject_hash: &str,
        _tenant_id: &str,
        _max_enrollments: i64,
    ) -> Result<trace_commons_server::db::InstanceEnrollmentOutcome, DatabaseError> {
        Err(DatabaseError::Pool("stub".into()))
    }

    async fn instance_ledger_rls_ready(&self) -> Result<bool, DatabaseError> {
        Ok(false)
    }

    async fn list_submissions_needing_gate_decision(
        &self,
        _now: DateTime<Utc>,
        _max_attempts: i32,
        _backoff_base_seconds: i64,
        limit: i64,
    ) -> Result<Vec<GateWorkItem>, DatabaseError> {
        let limit = usize::try_from(limit.max(0)).unwrap_or(usize::MAX);
        Ok(self
            .ungated
            .read()
            .unwrap()
            .iter()
            .take(limit)
            .cloned()
            .collect())
    }

    /// Override the defaulted "pool not configured" body: enumerate every
    /// seeded submission still held on `AwaitingPiiBackstop` whose attempt
    /// count is below `max_attempts`, mirroring the real cross-tenant query the
    /// production driver runs. A released (Accepted/Quarantined) submission
    /// drops out, so a second tick against a drained backlog returns empty.
    async fn list_submissions_awaiting_pii_backstop(
        &self,
        _now: DateTime<Utc>,
        max_attempts: i32,
        _backoff_base_seconds: i64,
        limit: i64,
    ) -> Result<Vec<GateWorkItem>, DatabaseError> {
        let limit = usize::try_from(limit.max(0)).unwrap_or(usize::MAX);
        let statuses = self.statuses.read().unwrap();
        let attempts = self.pii_backstop_attempts.read().unwrap();
        let mut eligible = self
            .awaiting_pii_backstop
            .read()
            .unwrap()
            .iter()
            .filter(|item| {
                statuses
                    .get(&(item.tenant_id.clone(), item.submission_id))
                    .copied()
                    == Some(StorageTraceCorpusStatus::AwaitingPiiBackstop)
            })
            .filter(|item| {
                attempts
                    .get(&(item.tenant_id.clone(), item.submission_id))
                    .map(|(count, _, _)| *count < max_attempts)
                    .unwrap_or(true)
            })
            .cloned()
            .collect::<Vec<_>>();
        // Mirror the production ORDER BY: least-recently-attempted first,
        // never-attempted (NULL) before everything else. `sort_by_key` is
        // stable, so ties keep seeding order, which stands in for the
        // `received_at ASC` tiebreak.
        eligible.sort_by_key(|item| {
            attempts
                .get(&(item.tenant_id.clone(), item.submission_id))
                .and_then(|(_, _, at)| *at)
        });
        eligible.truncate(limit);
        Ok(eligible)
    }
}

// --- Live-PG variant (Task 7 read-path finding) ------------------------
//
// `#[ignore]`d and gated on a reachable Postgres (`postgres_backend_for_ingest_test`).
// CI never runs Postgres, so this does not run in CI; it compiles under
// `cargo test --no-run` and is meant for local/PG runs. It pins the Task 7
// finding: a released-backstop trace (pre-backstop `SubmittedEnvelope` ref
// invalidated, only a `RescrubbedEnvelope` ref active) must still be resolvable
// by a `require_object_refs` reader via `read_envelope_from_active_db_object_ref`.
#[tokio::test]
#[ignore = "requires PostgreSQL (TRACE_COMMONS_PG_TEST_DATABASE_URL); not run in CI"]
async fn released_backstop_trace_resolves_via_db_ref_read_path_live_pg() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let remote_temp = tempfile::tempdir().expect("remote artifact temp dir");
    let key = trace_commons_server::secrets::keychain::generate_master_key_hex();
    let remote_config = TraceRemoteObjectStoreConfig::from_parts(
        Some("file_system"),
        Some(remote_temp.path().to_str().expect("utf8 temp path")),
        Some("test-kms-key-ref"),
        Some("test-credential-ref"),
    )
    .expect("filesystem remote config parses");
    let artifact_store =
        ConfiguredTraceArtifactStore::remote_service(remote_config, SecretString::from(key))
            .expect("filesystem remote service store builds");
    let mut state =
        test_state_with_configured_artifact_store_policies_export_guardrails_and_required_db_writes(
            temp.path().to_path_buf(),
            Some(backend.clone()),
            Some(artifact_store),
            false,
            true,
            false,
            false,
            false,
            false,
            BTreeMap::new(),
            false,
            false,
            true,
            false,
        );
    {
        let state_mut = Arc::make_mut(&mut state);
        // The hardening whose satisfiability the Task 7 fix restores.
        state_mut.db_reviewer_require_object_refs = true;
        state_mut.tenant_rollout_gates = TraceTenantRolloutGates {
            tenant_ids_by_feature: Arc::new(BTreeMap::from([(
                TraceTenantRolloutFeature::ObjectPrimarySubmitReview,
                BTreeSet::from(["tenant-a".to_string()]),
            )])),
        };
    }

    // A normal Accepted submission mirrors an active `SubmittedEnvelope` ref.
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        submit_body(envelope),
    )
    .await
    .expect("object-primary submission mirrors to DB");

    // Before invalidation the read path resolves the submitted envelope.
    read_envelope_from_active_db_object_ref(state.as_ref(), "tenant-a", submission_id)
        .await
        .expect("submitted read succeeds")
        .expect("submitted envelope resolves before backstop release");

    // Simulate the backstop release: write a rescrubbed envelope + ref, then
    // invalidate the pre-backstop submitted ref (exactly what
    // `process_one_pii_backstop` does).
    let tenant_ref = tenant_storage_ref("tenant-a");
    let store = state
        .artifact_store
        .as_ref()
        .expect("artifact store configured");
    let mut rescrubbed = sample_envelope().await;
    make_metadata_only_low_risk(&mut rescrubbed);
    rescrubbed.submission_id = submission_id;
    rescrubbed.contributor.tenant_scope_ref = Some(tenant_ref.clone());
    rescrubbed.privacy.redaction_pipeline_version = format!(
        "{}+near-ai-pii-backstop-v1",
        rescrubbed.privacy.redaction_pipeline_version
    );
    let rescrubbed_receipt = store
        .put_json(
            &tenant_ref,
            TraceArtifactKind::ContributionEnvelope,
            "backstop-released-rescrubbed-envelope",
            &rescrubbed,
        )
        .expect("rescrubbed envelope artifact writes");
    backend
        .append_trace_object_ref(StorageTraceObjectRefWrite {
            object_ref_id: Uuid::new_v4(),
            tenant_id: "tenant-a".to_string(),
            submission_id,
            artifact_kind: StorageTraceObjectArtifactKind::RescrubbedEnvelope,
            object_store: store.object_store_name().to_string(),
            object_key: rescrubbed_receipt.object_key,
            content_sha256: format!("sha256:{}", rescrubbed_receipt.ciphertext_sha256),
            encryption_key_ref: format!("tenant:{tenant_ref}"),
            size_bytes: 128,
            compression: None,
            created_by_job_id: None,
        })
        .await
        .expect("rescrubbed object ref writes");
    backend
        .invalidate_trace_object_refs_by_kind(
            "tenant-a",
            submission_id,
            StorageTraceObjectArtifactKind::SubmittedEnvelope,
        )
        .await
        .expect("pre-backstop submitted ref invalidated");

    // The Task 7 guarantee: with only the rescrubbed ref active, a
    // require_object_refs reader still resolves the released-backstop trace,
    // and it carries the backstop pipeline label.
    let body = read_envelope_from_active_db_object_ref(state.as_ref(), "tenant-a", submission_id)
        .await
        .expect("released-backstop read succeeds")
        .expect("rescrubbed envelope resolves after submitted ref invalidated");
    assert!(
        body.envelope
            .privacy
            .redaction_pipeline_version
            .contains("near-ai-pii-backstop-v1"),
        "resolved body must be the rescrubbed envelope"
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

/// Handler-level test for the devfolio score read-back route
/// (`POST /v1/admin/scores-by-submission`). Covers the scoped credential
/// (`CompetitionReadWorker` admitted, contributor rejected), the batch cap,
/// the cross-tenant bundle shape, and the fail-closed 503 when no DB mirror
/// is configured.
#[tokio::test]
async fn scores_by_submission_handler_serves_competition_worker_and_fails_closed() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());

    // id1 lives in tenant-a and is fully scored; id2 lives in tenant-b and has
    // no credit-quality score yet. The route must return BOTH (cross-tenant).
    let id1 = Uuid::new_v4();
    let mut row1 = rescore_test_decision_row(id1);
    row1.perplexity_passed = true;
    row1.novelty_passed = true;
    db.seed_gate_decision("tenant-a", row1.clone());
    db.update_trace_gate_decision_credit_quality("tenant-a", row1.decision_id, 700_000, 0, 1)
        .await
        .expect("seed row1 credit quality");

    let id2 = Uuid::new_v4();
    let mut row2 = rescore_test_decision_row(id2);
    row2.perplexity_passed = false;
    row2.novelty_passed = true;
    db.seed_gate_decision("tenant-b", row2);

    let unknown_id = Uuid::new_v4();

    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );
    // DB-first audit writes, matching the production posture; the in-memory
    // double records the mirrored row rather than serving a read-back chain.
    Arc::make_mut(&mut state).require_db_mirror_writes = true;

    // A contributor token must never reach the competition read-back.
    let forbidden = scores_by_submission_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(ScoresBySubmissionRequest {
            submission_ids: vec![id1],
        }),
    )
    .await
    .expect_err("contributor tokens are rejected");
    assert_eq!(forbidden.0, StatusCode::FORBIDDEN);

    // Oversized batches are refused before any read.
    let too_large = scores_by_submission_handler(
        State(state.clone()),
        auth_headers("competition-read-worker-token-a"),
        Json(ScoresBySubmissionRequest {
            submission_ids: (0..501).map(|_| Uuid::new_v4()).collect(),
        }),
    )
    .await
    .expect_err("batches over the cap are rejected");
    assert_eq!(too_large.0, StatusCode::PAYLOAD_TOO_LARGE);

    let Json(scores) = scores_by_submission_handler(
        State(state.clone()),
        auth_headers("competition-read-worker-token-a"),
        Json(ScoresBySubmissionRequest {
            submission_ids: vec![id1, id2, unknown_id],
        }),
    )
    .await
    .expect("competition read worker token is admitted");
    assert_eq!(
        scores.len(),
        2,
        "unknown ids are omitted, not an error: {scores:?}"
    );

    let by_id: std::collections::HashMap<Uuid, _> =
        scores.into_iter().map(|s| (s.submission_id, s)).collect();
    let s1 = by_id.get(&id1).expect("id1 present");
    assert_eq!(s1.credit_quality_micros, Some(700_000));
    assert!(s1.gate_passed);
    let s2 = by_id
        .get(&id2)
        .expect("id2 present even though it lives in another tenant");
    assert_eq!(
        s2.credit_quality_micros, None,
        "an unscored decision reports null q rather than being dropped"
    );
    assert!(!s2.gate_passed);

    // The successful read emits exactly one hash-only Read audit row, and it
    // carries no submission id (surface label + count only).
    {
        let audit = db.audit_events.read().unwrap();
        let reads = audit
            .iter()
            .filter(|event| event.action == StorageTraceAuditAction::Read)
            .collect::<Vec<_>>();
        assert_eq!(reads.len(), 1, "one audited read: {audit:?}");
        assert!(
            reads[0].submission_id.is_none(),
            "score read-back audit must not name a submission"
        );
    }

    // Fail closed when the cross-tenant read backend is not configured.
    let no_mirror_state = test_state_with_options(
        temp.path().to_path_buf(),
        None,
        None,
        false,
        false,
        false,
        false,
    );
    let unavailable = scores_by_submission_handler(
        State(no_mirror_state),
        auth_headers("competition-read-worker-token-a"),
        Json(ScoresBySubmissionRequest {
            submission_ids: vec![id1],
        }),
    )
    .await
    .expect_err("no DB mirror fails closed");
    assert_eq!(unavailable.0, StatusCode::SERVICE_UNAVAILABLE);
}

/// Attach a test attestation signing key (the same PKCS#8/SPKI Ed25519 pair
/// used by the eddsa-signed-token tests) so
/// `score_attestation_handler`/`attestation_keyset_handler` leave their
/// fail-closed branch.
fn test_state_with_attestation_signing(mut state: Arc<AppState>) -> Arc<AppState> {
    let config = trace_commons_server::trace_score_attestation::AttestationConfig {
        signing_private_key_pem: TEST_EDDSA_PRIVATE_KEY_PEM.to_string(),
        signing_public_key_pem: TEST_EDDSA_PUBLIC_KEY_PEM.to_string(),
        signing_kid: "test-attestation-kid".to_string(),
        ttl_seconds: 3600,
    };
    let signing =
        trace_commons_server::trace_score_attestation::AttestationSigningState::build(&config)
            .expect("test attestation signing state builds");
    Arc::make_mut(&mut state).attestation_signing = Some(Arc::new(signing));
    state
}

/// Handler-level test for the score-attestation route
/// (`GET /v1/contributors/me/score-attestation`). Covers the fail-closed 503
/// when the signing key is unconfigured, the fail-closed 503 when no DB
/// mirror is configured, a successful signed attestation that verifies
/// against the published key and contains only the caller's own submission,
/// and — the non-negotiable this endpoint exists to enforce — that a SECOND
/// contributor authenticated with their own token gets their OWN scores back,
/// never the first contributor's, even though both submissions live in the
/// same tenant. `score_attestation_handler`'s signature takes only
/// `State`/`HeaderMap` (no body, no query extractor), so there is no
/// request parameter this test could even try to forge through — the
/// property is structural, and this test pins the resulting behavior.
#[tokio::test]
async fn score_attestation_handler_signs_only_the_callers_own_scores_and_fails_closed() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());

    let principal_a = static_token_principal_ref("token-a");
    let principal_a2 = static_token_principal_ref("token-a-2");

    let id1 = Uuid::new_v4();
    let mut row1 = rescore_test_decision_row(id1);
    row1.perplexity_passed = true;
    row1.novelty_passed = true;
    db.seed_gate_decision("tenant-a", row1.clone());
    db.seed_submission_with_principal("tenant-a", id1, &principal_a);
    db.update_trace_gate_decision_credit_quality("tenant-a", row1.decision_id, 750_000, 0, 1)
        .await
        .expect("seed row1 credit quality");

    // A decision belonging to a DIFFERENT contributor in the SAME tenant —
    // must never appear in token-a's attestation.
    let id2 = Uuid::new_v4();
    let mut row2 = rescore_test_decision_row(id2);
    row2.perplexity_passed = true;
    row2.novelty_passed = true;
    db.seed_gate_decision("tenant-a", row2.clone());
    db.seed_submission_with_principal("tenant-a", id2, &principal_a2);

    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;

    // Fails closed when the attestation signing key is unconfigured — the
    // endpoint must NEVER return an unsigned document.
    let unconfigured = score_attestation_handler(State(state.clone()), auth_headers("token-a"))
        .await
        .expect_err("unconfigured signing key fails closed");
    assert_eq!(unconfigured.0, StatusCode::SERVICE_UNAVAILABLE);
    assert_eq!(
        unconfigured.1.0.error,
        trace_commons_server::trace_score_attestation::ATTESTATION_SIGNING_KEY_UNCONFIGURED
    );

    let state = test_state_with_attestation_signing(state);

    let Json(response) = score_attestation_handler(State(state.clone()), auth_headers("token-a"))
        .await
        .expect("configured signing key succeeds");

    let decoding_key = DecodingKey::from_ed_pem(TEST_EDDSA_PUBLIC_KEY_PEM.as_bytes())
        .expect("test public key parses");
    let mut validation = Validation::new(Algorithm::EdDSA);
    validation.validate_exp = false;
    validation.required_spec_claims.clear();
    let decoded = jsonwebtoken::decode::<
        trace_commons_server::trace_score_attestation::ScoreAttestationClaims,
    >(&response.attestation, &decoding_key, &validation)
    .expect("attestation verifies against the published key");

    assert_eq!(decoded.claims.tenant_id, "tenant-a");
    assert_eq!(decoded.claims.auth_principal_ref, principal_a);
    assert!(decoded.claims.expires_at > decoded.claims.issued_at);
    assert_eq!(
        decoded.claims.submissions.len(),
        1,
        "only the caller's own submission is attested: {:?}",
        decoded.claims.submissions
    );
    assert_eq!(decoded.claims.submissions[0].submission_id, id1);
    assert_eq!(
        decoded.claims.submissions[0].credit_quality_micros,
        Some(750_000)
    );
    assert!(decoded.claims.submissions[0].gate_passed);
    // Schema v2: the signed entry states how much of the trace was scored.
    // `rescore_test_decision_row` is a capped decision with a persisted
    // pre-cap total, so the attestation must say 7 of 19 rather than let a
    // reader assume the whole trace was judged.
    assert_eq!(
        decoded.claims.submissions[0].coverage,
        trace_commons_server::trace_score_attestation::ScoreAttestationCoverage::Partial {
            chunks_scored: 7,
            chunks_total: 19,
        }
    );
    assert_eq!(
        decoded.claims.schema_version,
        "trace_commons.score_attestation.v2"
    );

    // The second contributor's own request returns THEIR OWN scores, never
    // token-a's — the resolution is auth-only, with no parameter through
    // which either caller could name the other.
    let Json(other_response) =
        score_attestation_handler(State(state.clone()), auth_headers("token-a-2"))
            .await
            .expect("second contributor's own request succeeds");
    let other_decoded = jsonwebtoken::decode::<
        trace_commons_server::trace_score_attestation::ScoreAttestationClaims,
    >(&other_response.attestation, &decoding_key, &validation)
    .expect("second attestation verifies");
    assert_eq!(other_decoded.claims.auth_principal_ref, principal_a2);
    assert_eq!(other_decoded.claims.submissions.len(), 1);
    assert_eq!(other_decoded.claims.submissions[0].submission_id, id2);

    // Fails closed when no DB mirror is configured.
    let no_mirror_state = test_state_with_attestation_signing(test_state_with_options(
        temp.path().to_path_buf(),
        None,
        None,
        false,
        false,
        false,
        false,
    ));
    let unavailable = score_attestation_handler(State(no_mirror_state), auth_headers("token-a"))
        .await
        .expect_err("no DB mirror fails closed");
    assert_eq!(unavailable.0, StatusCode::SERVICE_UNAVAILABLE);
}
/// Regression test for the one property Devfolio's in-flight v2 verifier
/// depends on: an UNSCOPED attestation is the document it always was. Slice
/// E's `pending`/`unknown` fields must be ABSENT -- not null, not empty
/// arrays -- so a verifier that pinned `trace_commons.score_attestation.v2`
/// and rejects on shape sees no change until it opts in by asking a scoped
/// question.
#[tokio::test]
async fn unscoped_score_attestation_omits_pending_and_unknown_entirely() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let principal_a = static_token_principal_ref("token-a");

    let id1 = Uuid::new_v4();
    let row1 = rescore_test_decision_row(id1);
    db.seed_gate_decision("tenant-a", row1.clone());
    db.seed_submission_with_principal("tenant-a", id1, &principal_a);
    // An owned submission with no gate decision at all: invisible to the
    // unscoped document, exactly as before.
    db.seed_submission_with_principal("tenant-a", Uuid::new_v4(), &principal_a);

    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;
    let state = test_state_with_attestation_signing(state);

    let Json(response) = score_attestation_handler(State(state), auth_headers("token-a"))
        .await
        .expect("unscoped attestation signs");

    let claims = decode_attestation_payload(&response.attestation);
    let object = claims.as_object().expect("claims are a JSON object");
    assert!(
        !object.contains_key("pending"),
        "unscoped attestation must not carry a pending key: {object:?}"
    );
    assert!(
        !object.contains_key("unknown"),
        "unscoped attestation must not carry an unknown key: {object:?}"
    );
    assert_eq!(
        object["schema_version"],
        serde_json::json!("trace_commons.score_attestation.v2"),
        "the schema version does not bump for scoped fields"
    );
    assert_eq!(
        object["submissions"]
            .as_array()
            .expect("submissions is an array")
            .len(),
        1
    );
}

/// A SCOPED request attests to exactly the asked-for ids, splitting them
/// three ways: scored (a gate decision exists), `pending` (owned, no
/// decision yet -- the signal that did not exist before, so a hacker
/// submitting at 23:58 hands the collector a signed "these are waiting"
/// rather than nothing), and `unknown`.
///
/// `unknown` deliberately collapses "belongs to another principal" and
/// "no such submission anywhere" into one bucket, so the route cannot be
/// used to probe for the existence of someone else's submission id.
#[tokio::test]
async fn scoped_score_attestation_reports_scored_pending_and_unknown() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let principal_a = static_token_principal_ref("token-a");
    let principal_a2 = static_token_principal_ref("token-a-2");

    let scored_id = Uuid::new_v4();
    let mut scored_row = rescore_test_decision_row(scored_id);
    scored_row.perplexity_passed = true;
    scored_row.novelty_passed = true;
    db.seed_gate_decision("tenant-a", scored_row.clone());
    db.seed_submission_with_principal("tenant-a", scored_id, &principal_a);

    let pending_id = Uuid::new_v4();
    db.seed_submission_with_principal("tenant-a", pending_id, &principal_a);

    // Owned by a DIFFERENT contributor in the same tenant, and scored.
    let other_id = Uuid::new_v4();
    db.seed_gate_decision("tenant-a", rescore_test_decision_row(other_id));
    db.seed_submission_with_principal("tenant-a", other_id, &principal_a2);

    // Never submitted anywhere.
    let absent_id = Uuid::new_v4();

    // Owned and scored, but NOT asked about: a scoped request attests to the
    // asked-for set and nothing else.
    let unasked_id = Uuid::new_v4();
    db.seed_gate_decision("tenant-a", rescore_test_decision_row(unasked_id));
    db.seed_submission_with_principal("tenant-a", unasked_id, &principal_a);

    let db_mirror: Arc<dyn Database> = db.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;
    let state = test_state_with_attestation_signing(state);

    let Json(response) = scoped_score_attestation_handler(
        State(state),
        auth_headers("token-a"),
        Json(ScopedScoreAttestationRequest {
            submission_ids: vec![scored_id, pending_id, other_id, absent_id],
        }),
    )
    .await
    .expect("scoped attestation signs");

    assert_eq!(response.scored, 1);
    assert_eq!(response.pending, 1);

    let claims = decode_attestation_payload(&response.attestation);
    let object = claims.as_object().expect("claims are a JSON object");
    assert_eq!(
        object["schema_version"],
        serde_json::json!("trace_commons.score_attestation.v2"),
        "scoped responses stay on v2"
    );
    let submissions = object["submissions"]
        .as_array()
        .expect("submissions is an array");
    assert_eq!(submissions.len(), 1, "{submissions:?}");
    assert_eq!(
        submissions[0]["submission_id"],
        serde_json::json!(scored_id.to_string())
    );
    assert_eq!(
        object["pending"],
        serde_json::json!([pending_id.to_string()])
    );
    assert_eq!(
        object["unknown"],
        serde_json::json!([other_id.to_string(), absent_id.to_string()]),
        "another principal's id and an id that exists nowhere are indistinguishable"
    );
}

/// The scoped request is capped by REQUEST SIZE rather than by the unscoped
/// path's global `LIMIT`, so a collector asking about more than the cap gets
/// a refusal it can chunk around -- never a silently truncated signed
/// document that omits ids it explicitly asked about.
#[tokio::test]
async fn scoped_score_attestation_refuses_more_ids_than_the_cap() {
    let temp = tempfile::tempdir().expect("temp dir");
    let db = Arc::new(PerplexityDriverTestDb::new());
    let db_mirror: Arc<dyn Database> = db.clone();
    let state = test_state_with_attestation_signing(test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    ));

    let too_many = (0..usize::try_from(SCORE_ATTESTATION_MAX_SUBMISSIONS).unwrap() + 1)
        .map(|_| Uuid::new_v4())
        .collect::<Vec<_>>();
    let refused = scoped_score_attestation_handler(
        State(state),
        auth_headers("token-a"),
        Json(ScopedScoreAttestationRequest {
            submission_ids: too_many,
        }),
    )
    .await
    .expect_err("an oversized scoped request is refused");
    assert_eq!(refused.0, StatusCode::PAYLOAD_TOO_LARGE);
}

/// The unscoped enumeration truncates by RECENCY, so a contributor past the
/// cap loses their oldest scores rather than an arbitrary slice of the
/// submission-UUID space. Ordering by `submission_id` -- a random v4 for
/// every trace -- made truncation unpredictable and unexplainable.
#[tokio::test]
async fn unscoped_gate_decision_enumeration_truncates_the_oldest_not_a_uuid_range() {
    let db = PerplexityDriverTestDb::new();
    let principal = "principal-truncation";

    let mut ids = Vec::new();
    for age_minutes in [30_i64, 20, 10] {
        let id = Uuid::new_v4();
        let mut row = rescore_test_decision_row(id);
        row.decided_at = Utc::now() - chrono::Duration::minutes(age_minutes);
        db.seed_gate_decision("tenant-a", row);
        db.seed_submission_with_principal("tenant-a", id, principal);
        ids.push(id);
    }
    let (oldest, newest) = (ids[0], ids[2]);
    let middle = ids[1];

    let kept = db
        .list_own_gate_decision_scores("tenant-a", principal, 2)
        .await
        .expect("enumeration succeeds");
    let kept_ids = kept.iter().map(|row| row.submission_id).collect::<Vec<_>>();
    assert_eq!(
        kept_ids,
        vec![newest, middle],
        "truncation drops the oldest decision, newest first"
    );
    assert!(!kept_ids.contains(&oldest));
}

/// Decode an attestation's claims as raw JSON, so a test can assert on the
/// PRESENCE of keys rather than on a typed struct that would silently
/// default an absent field.
fn decode_attestation_payload(attestation: &str) -> serde_json::Value {
    let decoding_key = DecodingKey::from_ed_pem(TEST_EDDSA_PUBLIC_KEY_PEM.as_bytes())
        .expect("test public key parses");
    let mut validation = Validation::new(Algorithm::EdDSA);
    validation.validate_exp = false;
    validation.required_spec_claims.clear();
    jsonwebtoken::decode::<serde_json::Value>(attestation, &decoding_key, &validation)
        .expect("attestation verifies against the published key")
        .claims
}

/// The attestation keyset endpoint fails closed (503, same missing-control
/// label) when signing is unconfigured, and publishes the configured key
/// under its `kid` otherwise — mirroring
/// `trace_upload_claim_issuer::keyset_handler`'s shape exactly so a
/// collector that already parses that response needs no new client code.
#[tokio::test]
async fn attestation_keyset_handler_fails_closed_then_publishes_the_key() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());

    let unconfigured = attestation_keyset_handler(State(state.clone()))
        .await
        .expect_err("unconfigured signing key fails closed");
    assert_eq!(unconfigured.0, StatusCode::SERVICE_UNAVAILABLE);
    assert_eq!(
        unconfigured.1.0.error,
        trace_commons_server::trace_score_attestation::ATTESTATION_SIGNING_KEY_UNCONFIGURED
    );

    let state = test_state_with_attestation_signing(state);
    let Json(keyset) = attestation_keyset_handler(State(state))
        .await
        .expect("configured signing key publishes the keyset");
    assert_eq!(keyset["keys"][0]["kid"], "test-attestation-kid");
    assert_eq!(
        keyset["keys"][0]["public_key_pem"].as_str(),
        Some(TEST_EDDSA_PUBLIC_KEY_PEM)
    );
}

#[test]
fn settlement_cap_bounds_the_account_not_each_principal() {
    fn event(principal: &str, points: f32) -> TraceCommonsCreditLedgerRecord {
        TraceCommonsCreditLedgerRecord {
            event_id: Uuid::new_v4(),
            tenant_id: "tenant-a".to_string(),
            tenant_storage_ref: tenant_storage_ref("tenant-a"),
            submission_id: Uuid::new_v4(),
            trace_id: Uuid::new_v4(),
            auth_principal_ref: principal.to_string(),
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: points,
            reason: None,
            external_ref: None,
            actor_role: TokenRole::Admin,
            actor_principal_ref: principal.to_string(),
            created_at: Utc::now(),
        }
    }

    // Three principals, each individually under a 1.0-point cap, all linked
    // to one durable account. Together they are 1.8 points against that cap.
    let events = vec![
        event("principal-1", 0.6),
        event("principal-2", 0.6),
        event("principal-3", 0.6),
    ];
    let cap = Some(1_000_000); // 1.0 points in micros
    let account = Uuid::new_v4();
    let linked: HashMap<String, Uuid> = ["principal-1", "principal-2", "principal-3"]
        .into_iter()
        .map(|p| (p.to_string(), account))
        .collect();

    let (settled, excluded, reasons) =
        apply_credit_settlement_account_cap(events.clone(), cap, &linked);
    assert!(
        settled.is_empty(),
        "the account is over cap, so none of its principals may settle"
    );
    assert_eq!(excluded, 3);
    assert_eq!(
        reasons.get("account_settlement_amount_exceeds_cap"),
        Some(&3)
    );

    // Without account linkage there is nothing to fold up, so the legacy
    // per-principal behaviour is preserved: each is under cap and settles.
    let (settled_unlinked, excluded_unlinked, _) =
        apply_credit_settlement_account_cap(events.clone(), cap, &HashMap::new());
    assert_eq!(
        settled_unlinked.len(),
        3,
        "unlinked principals are each under the cap and settle as before"
    );
    assert_eq!(excluded_unlinked, 0);

    // A single principal over the cap is still blocked, linked or not.
    let (over, over_excluded, _) =
        apply_credit_settlement_account_cap(vec![event("solo", 1.5)], cap, &HashMap::new());
    assert!(over.is_empty());
    assert_eq!(over_excluded, 1);
}

/// The dedup index must be held as a trait object so Phase 2 can substitute a
/// remote implementation without touching AppState's shape.
///
/// This is a compile-time assertion. `Option<Arc<UsearchVectorIndex>>` does NOT
/// coerce to `Option<Arc<dyn VectorIndex>>` — unsizing does not reach through
/// `Option` — so this fails to build until the builder's return type changes.
#[cfg(any(feature = "local-gpu-models", feature = "near-ai-scorer"))]
#[test]
fn dedup_vector_index_builder_returns_a_trait_object() {
    use std::sync::Arc;
    use trace_commons_gate_enclave::VectorIndex;

    let _: Option<Arc<dyn VectorIndex>> = build_dedup_vector_index_from_env();
}

// --- Loopback native-app sign-in -------------------------------------------
//
// These tests are the attack list from the design, not the happy path alone:
// an intercepted code without the verifier, a replayed code, a mismatched
// request handle, a browser cookie secret presented as a bearer, an expired
// token, and `revoke-all`. They run WITHOUT PostgreSQL — the account suite's
// pg-gated tests silently skip when no database is configured, and the checks
// below are exactly the ones that must never be skipped.
//
// Redirect matching is unit-tested exhaustively in
// `trace_commons_server::account_native_auth`, against every non-loopback
// spelling; the handler-level test here pins that the endpoint actually calls
// that validator.

#[derive(Clone)]
struct NativeTestSession {
    tenant_id: String,
    account_id: Uuid,
    token_hash: String,
    client_kind: String,
    expires_at: DateTime<Utc>,
    revoked: bool,
}

/// In-memory `Database` covering only the handful of calls the native sign-in
/// flow makes. Everything else keeps the trait's fail-closed default.
#[derive(Default)]
struct NativeAuthTestDb {
    sessions: std::sync::Mutex<Vec<NativeTestSession>>,
}

impl NativeAuthTestDb {
    fn session_count(&self) -> usize {
        self.sessions.lock().unwrap().len()
    }

    /// Insert a session row directly, so a test can pin an ALREADY-expired or
    /// non-native session without waiting or reaching for a second code path.
    fn insert_session(
        &self,
        tenant_id: &str,
        account_id: Uuid,
        token_hash: &str,
        client_kind: &str,
        expires_at: DateTime<Utc>,
    ) {
        self.sessions.lock().unwrap().push(NativeTestSession {
            tenant_id: tenant_id.to_string(),
            account_id,
            token_hash: token_hash.to_string(),
            client_kind: client_kind.to_string(),
            expires_at,
            revoked: false,
        });
    }
}

#[async_trait::async_trait]
impl Database for NativeAuthTestDb {
    async fn run_migrations(&self) -> Result<(), DatabaseError> {
        Ok(())
    }

    async fn enroll_instance_user(
        &self,
        _p: trace_commons_server::db::InstanceUserProvision,
    ) -> Result<(), DatabaseError> {
        Err(DatabaseError::Pool("stub".into()))
    }

    async fn reserve_instance_enrollment(
        &self,
        _instance_subject_hash: &str,
        _user_subject_hash: &str,
        _tenant_id: &str,
        _max_enrollments: i64,
    ) -> Result<trace_commons_server::db::InstanceEnrollmentOutcome, DatabaseError> {
        Err(DatabaseError::Pool("stub".into()))
    }

    async fn instance_ledger_rls_ready(&self) -> Result<bool, DatabaseError> {
        Ok(false)
    }

    async fn get_device_key(
        &self,
        _tenant_id: &str,
        _device_key_id: &str,
    ) -> Result<Option<trace_commons_server::db::DeviceKeyRecord>, DatabaseError> {
        Ok(None)
    }

    async fn issue_native_session(
        &self,
        tenant_id: &str,
        account_id: Uuid,
        session: trace_commons_server::db::NewSession<'_>,
        _audit: trace_commons_server::db::RedeemAudit,
    ) -> Result<(), DatabaseError> {
        self.insert_session(
            tenant_id,
            account_id,
            session.token_hash,
            session.client_kind,
            session.expires_at,
        );
        Ok(())
    }

    async fn validate_session(
        &self,
        tenant_id: &str,
        token_hash: &str,
    ) -> Result<Option<trace_commons_server::db::ValidatedSession>, DatabaseError> {
        let now = Utc::now();
        let sessions = self.sessions.lock().unwrap();
        Ok(sessions
            .iter()
            .find(|s| {
                s.tenant_id == tenant_id
                    && s.token_hash == token_hash
                    && !s.revoked
                    && s.expires_at > now
            })
            .map(|s| trace_commons_server::db::ValidatedSession {
                account_id: s.account_id,
                auth_credential_id: None,
                client_kind: s.client_kind.clone(),
                rotated_secret: None,
            }))
    }

    async fn expand_account_principals(
        &self,
        _tenant_id: &str,
        _account_id: Uuid,
    ) -> Result<AccountPrincipalSet, DatabaseError> {
        Ok(AccountPrincipalSet::from_iter_for_test_only([
            "principal_sha256:native-test".to_string(),
        ]))
    }

    async fn revoke_all_account_sessions(
        &self,
        tenant_id: &str,
        account_id: Uuid,
    ) -> Result<u64, DatabaseError> {
        let mut sessions = self.sessions.lock().unwrap();
        let mut revoked = 0;
        for s in sessions.iter_mut() {
            if s.tenant_id == tenant_id && s.account_id == account_id && !s.revoked {
                s.revoked = true;
                revoked += 1;
            }
        }
        Ok(revoked)
    }

    async fn revoke_current_session(
        &self,
        tenant_id: &str,
        token_hash: &str,
    ) -> Result<u64, DatabaseError> {
        let mut sessions = self.sessions.lock().unwrap();
        let mut revoked = 0;
        for s in sessions.iter_mut() {
            if s.tenant_id == tenant_id && s.token_hash == token_hash && !s.revoked {
                s.revoked = true;
                revoked += 1;
            }
        }
        Ok(revoked)
    }

    async fn append_account_audit(
        &self,
        _tenant_id: &str,
        _action: &str,
        _actor_ref: &str,
        _outcome: &str,
        _metadata: serde_json::Value,
    ) -> Result<(), DatabaseError> {
        Ok(())
    }
}

fn native_test_state(db: Arc<NativeAuthTestDb>) -> (tempfile::TempDir, Arc<AppState>) {
    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = db;
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );
    (temp, state)
}

/// A well-formed verifier/challenge pair, distinct per call so the per-code
/// rate limiter in one test cannot affect another.
fn native_test_pkce() -> (String, String) {
    let verifier = format!("{}{}", "verifier-", Uuid::new_v4().simple()).repeat(2);
    let verifier = format!("{verifier}{}", "x".repeat(64))
        .chars()
        .take(64)
        .collect::<String>();
    let challenge = challenge_for_verifier(&verifier);
    (verifier, challenge)
}

fn native_loopback_redirect() -> String {
    "http://127.0.0.1:49152/trace-commons/native-auth/callback".to_string()
}

async fn native_start(
    state: &Arc<AppState>,
    challenge: &str,
    redirect: &str,
) -> (StatusCode, Option<String>) {
    let body = serde_json::json!({
        "code_challenge": challenge,
        "code_challenge_method": "S256",
        "redirect_uri": redirect,
    });
    let response = native_authorize_start_handler(
        State(state.clone()),
        HeaderMap::new(),
        Ok(Json(
            serde_json::from_value(body).expect("valid start body"),
        )),
    )
    .await;
    let status = response.status();
    if status != StatusCode::OK {
        return (status, None);
    }
    let bytes = axum::body::to_bytes(response.into_body(), 64 * 1024)
        .await
        .expect("start body");
    let parsed: serde_json::Value = serde_json::from_slice(&bytes).expect("start json");
    let request_id = parsed
        .get("request_id")
        .and_then(|v| v.as_str())
        .expect("request_id")
        .to_string();
    (status, Some(request_id))
}

async fn native_exchange(
    state: &Arc<AppState>,
    request_id: &str,
    code: &str,
    verifier: &str,
) -> (StatusCode, Option<String>) {
    let body = serde_json::json!({
        "request_id": request_id,
        "code": code,
        "code_verifier": verifier,
    });
    let response = native_token_handler(
        State(state.clone()),
        HeaderMap::new(),
        Ok(Json(
            serde_json::from_value(body).expect("valid token body"),
        )),
    )
    .await;
    let status = response.status();
    if status != StatusCode::OK {
        return (status, None);
    }
    let bytes = axum::body::to_bytes(response.into_body(), 64 * 1024)
        .await
        .expect("token body");
    let parsed: serde_json::Value = serde_json::from_slice(&bytes).expect("token json");
    let token = parsed
        .get("access_token")
        .and_then(|v| v.as_str())
        .expect("access_token")
        .to_string();
    (status, Some(token))
}

/// Drive the flow to the point where a one-time code exists, WITHOUT needing a
/// database for the browser half: `issue_native_authorization_code` is exactly
/// what the confirm handler calls once a human has redeemed a login link.
async fn native_flow_to_code(
    state: &Arc<AppState>,
    challenge: &str,
    account_id: Uuid,
) -> (String, String) {
    let (status, request_id) = native_start(state, challenge, &native_loopback_redirect()).await;
    assert_eq!(status, StatusCode::OK, "authorize start succeeds");
    let request_id = request_id.expect("request id");
    let location =
        issue_native_authorization_code(state.as_ref(), &request_id, "tenant-a", account_id)
            .expect("a live pending request yields a loopback redirect");
    assert!(
        location.starts_with("http://127.0.0.1:49152/trace-commons/native-auth/callback?code="),
        "code is delivered only to the registered loopback URI: {location}"
    );
    let code = location
        .split("code=")
        .nth(1)
        .and_then(|rest| rest.split('&').next())
        .expect("code in the loopback redirect")
        .to_string();
    (request_id, code)
}

#[tokio::test]
async fn native_authorize_refuses_a_redirect_that_is_not_loopback() {
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db);
    let (_verifier, challenge) = native_test_pkce();
    for redirect in [
        "http://localhost:49152/trace-commons/native-auth/callback",
        "https://evil.example.com/trace-commons/native-auth/callback",
        "http://127.0.0.1:49152/somewhere-else",
    ] {
        let (status, request_id) = native_start(&state, &challenge, redirect).await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "must refuse {redirect}");
        assert!(request_id.is_none());
    }
}

#[tokio::test]
async fn native_authorize_refuses_plain_pkce() {
    // `plain` would make the challenge equal the verifier, so anyone who saw the
    // start request could finish the flow. Only S256 is accepted.
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db);
    let (verifier, _challenge) = native_test_pkce();
    let body = serde_json::json!({
        "code_challenge": verifier,
        "code_challenge_method": "plain",
        "redirect_uri": native_loopback_redirect(),
    });
    let response = native_authorize_start_handler(
        State(state.clone()),
        HeaderMap::new(),
        Ok(Json(serde_json::from_value(body).expect("body"))),
    )
    .await;
    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn an_intercepted_code_without_the_verifier_is_useless() {
    // THE central property. Another local process races the loopback listener
    // and gets the code. It does not have the verifier, so the exchange fails
    // and no session is ever created.
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let (_verifier, challenge) = native_test_pkce();
    let account_id = Uuid::new_v4();
    let (request_id, code) = native_flow_to_code(&state, &challenge, account_id).await;

    let (attacker_verifier, _) = native_test_pkce();
    let (status, token) = native_exchange(&state, &request_id, &code, &attacker_verifier).await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "wrong verifier is refused");
    assert!(token.is_none());
    assert_eq!(
        db.session_count(),
        0,
        "no session may exist after a failed exchange"
    );
}

#[tokio::test]
async fn a_replayed_code_fails() {
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let (verifier, challenge) = native_test_pkce();
    let account_id = Uuid::new_v4();
    let (request_id, code) = native_flow_to_code(&state, &challenge, account_id).await;

    let (status, token) = native_exchange(&state, &request_id, &code, &verifier).await;
    assert_eq!(status, StatusCode::OK, "the honest exchange succeeds");
    assert!(token.expect("token").starts_with("tcn1_"));
    assert_eq!(db.session_count(), 1);

    // Same code, same verifier, second time.
    let (status, token) = native_exchange(&state, &request_id, &code, &verifier).await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "a replayed code is refused"
    );
    assert!(token.is_none());
    assert_eq!(
        db.session_count(),
        1,
        "a replay must not mint a second session"
    );
}

#[tokio::test]
async fn a_code_presented_against_another_request_fails() {
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let (verifier, challenge) = native_test_pkce();
    let account_id = Uuid::new_v4();
    let (_request_id, code) = native_flow_to_code(&state, &challenge, account_id).await;

    let (_other_verifier, other_challenge) = native_test_pkce();
    let (status, other_request_id) =
        native_start(&state, &other_challenge, &native_loopback_redirect()).await;
    assert_eq!(status, StatusCode::OK);

    let (status, token) = native_exchange(
        &state,
        &other_request_id.expect("second request id"),
        &code,
        &verifier,
    )
    .await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "code is bound to its own request"
    );
    assert!(token.is_none());
    assert_eq!(db.session_count(), 0);
}

#[tokio::test]
async fn a_native_token_authenticates_the_account_surface_as_a_weak_session() {
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let (verifier, challenge) = native_test_pkce();
    let account_id = Uuid::new_v4();
    let (request_id, code) = native_flow_to_code(&state, &challenge, account_id).await;
    let (_status, token) = native_exchange(&state, &request_id, &code, &verifier).await;
    let token = token.expect("token");

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::AUTHORIZATION,
        HeaderValue::from_str(&format!("Bearer {token}")).expect("bearer header"),
    );
    let ctx = resolve_account_ctx(state.as_ref(), &headers)
        .await
        .expect("the native token resolves");
    assert_eq!(ctx.auth_method, AccountAuthMethod::NativeToken);
    assert_eq!(ctx.account_id.as_uuid(), account_id);
    assert_eq!(ctx.tenant_id, "tenant-a");
    assert!(
        ctx.actor_ref.starts_with("account-actor:"),
        "actor must be the reserved-prefix account actor, never a device ref"
    );
    assert!(
        !ctx.is_strong_session(),
        "a native token must stay WEAK: read and withdraw, never change authenticators"
    );
}

#[tokio::test]
async fn revoke_all_kills_a_native_token() {
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let (verifier, challenge) = native_test_pkce();
    let account_id = Uuid::new_v4();
    let (request_id, code) = native_flow_to_code(&state, &challenge, account_id).await;
    let (_status, token) = native_exchange(&state, &request_id, &code, &verifier).await;
    let token = token.expect("token");

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::AUTHORIZATION,
        HeaderValue::from_str(&format!("Bearer {token}")).expect("bearer header"),
    );
    assert!(resolve_account_ctx(state.as_ref(), &headers).await.is_ok());

    let revoked = db
        .revoke_all_account_sessions("tenant-a", account_id)
        .await
        .expect("revoke-all");
    assert_eq!(revoked, 1, "the native session is an ordinary session row");

    let err = resolve_account_ctx(state.as_ref(), &headers)
        .await
        .expect_err("a revoked native token must fail closed");
    assert_eq!(err.0, StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn an_expired_native_token_is_denied() {
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let account_id = Uuid::new_v4();
    let secret = "expired-native-secret";
    db.insert_session(
        "tenant-a",
        account_id,
        &hash_secret(secret),
        "native",
        Utc::now() - Duration::minutes(1),
    );
    let token = native_token_value("tenant-a", secret);

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::AUTHORIZATION,
        HeaderValue::from_str(&format!("Bearer {token}")).expect("bearer header"),
    );
    let err = resolve_account_ctx(state.as_ref(), &headers)
        .await
        .expect_err("an expired native token must fail closed");
    assert_eq!(err.0, StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn a_browser_session_secret_is_not_usable_as_a_native_bearer() {
    // The cookie's HttpOnly/SameSite=Strict shape exists so a native process
    // cannot reach the browser session. Even if a `'web'` session's secret were
    // somehow obtained and re-encoded as a `tcn1_` bearer, the client_kind guard
    // refuses it.
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let account_id = Uuid::new_v4();
    let secret = "a-browser-session-secret";
    db.insert_session(
        "tenant-a",
        account_id,
        &hash_secret(secret),
        "web",
        Utc::now() + Duration::days(7),
    );
    let token = native_token_value("tenant-a", secret);

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::AUTHORIZATION,
        HeaderValue::from_str(&format!("Bearer {token}")).expect("bearer header"),
    );
    let err = resolve_account_ctx(state.as_ref(), &headers)
        .await
        .expect_err("a web session must not be reachable as a native bearer");
    assert_eq!(err.0, StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn a_stale_native_request_id_cannot_be_completed_twice() {
    // The pending request is single-use: a second confirm carrying the same
    // `native` id (a replayed browser POST, or a second tab) mints no second
    // code.
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db);
    let (_verifier, challenge) = native_test_pkce();
    let (status, request_id) = native_start(&state, &challenge, &native_loopback_redirect()).await;
    assert_eq!(status, StatusCode::OK);
    let request_id = request_id.expect("request id");
    assert!(
        issue_native_authorization_code(state.as_ref(), &request_id, "tenant-a", Uuid::new_v4())
            .is_some()
    );
    assert!(
        issue_native_authorization_code(state.as_ref(), &request_id, "tenant-a", Uuid::new_v4())
            .is_none(),
        "a pending native request is consumed by the first completion"
    );
}

#[tokio::test]
async fn logging_out_a_native_token_revokes_its_session_row() {
    let _settlement_guard = SETTLEMENT_TEST_LOCK.lock().await;
    // Unlike the device-bearer path (a documented no-op), a native token HAS a
    // session row, so logout must actually revoke it rather than leave a
    // signed-out app holding a live token.
    let db = Arc::new(NativeAuthTestDb::default());
    let (_temp, state) = native_test_state(db.clone());
    let (verifier, challenge) = native_test_pkce();
    let account_id = Uuid::new_v4();
    let (request_id, code) = native_flow_to_code(&state, &challenge, account_id).await;
    let (_status, token) = native_exchange(&state, &request_id, &code, &verifier).await;
    let token = token.expect("token");

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::AUTHORIZATION,
        HeaderValue::from_str(&format!("Bearer {token}")).expect("bearer header"),
    );
    let ctx = account_ctx_ext(&state, &headers).await;
    account_logout_handler(State(state.clone()), ctx, headers.clone())
        .await
        .expect("logout succeeds");

    let err = resolve_account_ctx(state.as_ref(), &headers)
        .await
        .expect_err("a logged-out native token must fail closed");
    assert_eq!(err.0, StatusCode::UNAUTHORIZED);
}

